\begin{algorithm}[h!]
\SetAlgoLined
\caption{MO-CMA-MAE}
\label{alg:mo_cma_mae}
\SetKwInOut{Input}{input}
\SetKwInOut{Result}{result}
\SetKwProg{MOCMAMAE}{MO-CMA-MAE}{}{}
\DontPrintSemicolon
\MOCMAMAE{$(N, \psi, \lambda, \bm{x}_0, \sigma_0$, $\alpha$, $\epsilon)$}
{


\Input{A desired number of iterations $N$, the number of emitters $\psi$, a branching population size $\lambda$, an initial solution $\bm{x}_0$, an initial step size $\sigma_0$, a learning rate $\alpha$, and a bisection search error tolerance $\epsilon$.}
\Result{An archive $A$ of Pareto Sets. Each cell $e$ within $A$ contains a Pareto Set $P_e$ whose solutions are non-dominated by other solutions from cell $e$.}

\BlankLine
Initialize archive $A$ where $\forall e \in A, \; P_e \gets \emptyset, \; T_e \gets \emptyset$.

Initialize $\psi$ CMA-ES emitters, each with initial mean $\bm{\bar{x}} \leftarrow \bm{x}_0$, initial covariance matrix $\mathcal{C} \leftarrow \sigma_0\mathbf{I}$, and other internal parameters $\bm{p}$.

\For{$iter\leftarrow 1$ \KwTo $N$}{
    \For{$i\leftarrow 1$ \KwTo $\lambda$}{
        \label{mocmamae:startforloop} 
        $\bm{x}_i \sim \mathcal{N}(\bm{\bar{x}},\mathcal{C})$\; \label{mocmamae:sample} 

        ${\bf f}(\bm{x}_i), \bm{m}(\bm{x}_i) \gets \mbox{evaluate}(\bm{x}_i)$\; \label{mocmamae:evaluate}

        $e \gets \mbox{calculate\_cell}(A, \bm{m}(\bm{x}_i))$\; \label{mocmamae:calc_cell}

        \BlankLine
        \tcc{Add $\bm{x}_i$ to $P_e$ if ${\bf f}(\bm{x}_i)$ is non-dominated by $T_e$; then search for $d_i$ and add $d_i{\bf f}(\bm{x}_i)$ to $T_e$}
        $\Phi_i \gets \mbox{HVI}_r({\bf f}(\bm{x}_i), T_e)$\; \label{mocmamae:calc_hvi}
        \If{$\Phi_i > 0$}{
            $P_e \gets \{\bm{x}_i\} \cup \{\bm{x} \in P_e \mid \bm{x} \not\prec \bm{x}_i\}$\; \label{mocmamae:add_to_ps}

            $d_i \gets \mbox{bisect}({\bf f}(\bm{x}_i), T_e, \alpha, \epsilon)$\;

            $T_e \gets \{d_i{\bf f}(\bm{x}_i)\} \cup \{{\bf f} \in T_e \mid {\bf f} \not\prec d_i{\bf f}(\bm{x}_i)\}$\; \label{mocmamae:add_to_tpf}
            $\text{(Optional) } \mbox{downsize}(P_e, T_e)$\; \label{mocmamae:downsize}
         }

    \BlankLine
    \tcc{Adapt CMA-ES~\citep{pyribs} according to $\Phi_i$}
    rank $\bm{x}_i$ by $\Phi_i$ \; \label{mocmamae:ranking}
    adapt CMA-ES parameters $\bm{\bar{x}},\mathcal{C},\bm{p}$\; \label{mocmamae:adaptation}
    \If{\mbox{CMA-ES restart triggered}}{
        $\bm{x}_0 \gets \mbox{sample\_elite}(\{P_e, \forall e \in A\})$\;
        Restart CMA-ES with $\mathcal{C} \leftarrow \sigma_0 I$ and $\bm{\bar{x}} \leftarrow \bm{x}_0$.
    }
}
}
}

