	\subsection{The fully-discrete LDG scheme and its energy stability}
	\label{subse2}
	In this subsection,   the LDG scheme to solve the scheme \eqref{eq:semi-phi}-\eqref{eq:projection} is proposed. 

	Let $\mathcal{T}_h=\{K\}$ be a shape-regular subdivision of $\Omega$. $\mathcal{E}_h$ denotes the union of the boundary faces of elements $K \in \mathcal{T}_h$, and $\mathcal{E}_0=\mathcal{E}_h \setminus  \partial \Omega$. Let $\mathcal{P}^k(K)$ be the
	space of polynomials of degree at most $k\geq 0$ on $K \in
	\mathcal{T}_h$. The DG finite element spaces are denoted by
	\begin{align*}
		V_{h}=&\Bigl\{\varphi:\;\;\;\varphi\vert_K\in
		\mathcal{P}^k(K),\;\;\;\; \; \forall K\in \mathcal{T}_{h}\Bigr\},\\
		\bm{W}_h = & \Bigl\{\Phi=(\phi_1,\cdots,\phi_d)^T :\;\;\;
		\phi_l\vert_{ K }\in \mathcal{P}^k(K), \;\;l=1\cdots d,\;\;\;
		\forall K \in \mathcal{T}_{h}\Bigr\},\\
		\bm{\Pi}_h=&\Bigl\{\bm{\Theta}=(\bm{\theta}_1,\cdots,\bm{\theta}_d)^T :\;\;\;
		\bm{\theta}_l\vert_{ K }\in (\mathcal{P}^k(K))^d, \;\;l=1\cdots d,\;\;\;
		\forall K \in \mathcal{T}_{h}\Bigr\}.
	\end{align*}

	To develop the LDG scheme, we first rewrite \eqref{eq:semi-phi}-\eqref{eq:projection} as a first-order system
	\begin{subequations}\label{first_system}
		\begin{align}
			\frac{\phi^{n+1}-\phi^n}{\Delta t}=&\mathcal{M} \nabla \cdot \bm{w}^{n+1}-\nabla \cdot \bm{q}^{n+1}-\frac{K}{Ca} \tilde\mu_{\phi}^{n+1} |\bm{v}^n|,\\
			\bm{w}^{n+1}=&\nabla \tilde\mu_{\phi}^{n+1},\\
			\bm{q}^{n+1} =&\phi^n \bm{u}_{*}^n,\\
			\tilde\mu_{\phi}^{n+1}=&-\epsilon \nabla \cdot \bm{v}^{n+1}+\frac{S}{\epsilon}(\phi^{n+1}-\phi^n)+\frac{1}{\epsilon}f(\phi^n)-\frac{\beta}{\epsilon}\sum_{\pm} \frac{\zeta_{\pm}^{n+1}-\zeta_{\pm}^n}{\phi^{n+1}-\phi^n} C_{\pm}^{n+1},\\
			\bm{v}^{n+1} =& \nabla \phi^{n+1},\\
			\frac{\zeta_{\pm}^{n+1}C_{\pm}^{n+1}-\zeta_{\pm}^nC_{\pm}^n}{\Delta t} =&\frac{1}{Pe} \nabla \cdot \bm{w}_{\pm}^{n+1}-\nabla \cdot \bm{q}_{\pm}^{n+1},\\
			\bm{w}_{\pm}^{n+1} =&\zeta_{\pm}^n D_{\pm}^n   C_{\pm}^{n+1} \bm{s}_{\pm}^{n+1},\\
			\bm{s}_{\pm}^{n+1} =&\nabla \mu_{c_{\pm}}^{n+1},\\
			\mu_{c_{\pm}}^{n+1} =&\ln C_{\pm}^{n+1},\\
			\bm{q}_{\pm}^{n+1}=&\bm{u}_{*}^n \zeta_{\pm}^n C_{\pm}^{n},\\
			Re \frac{\widetilde{\bm{u}}^{n+1}-\bm{u}^n}{\Delta t}=&\eta \nabla \cdot \bm{Q}^{n+1}-Re (\bm{u}^n \cdot \nabla)\widetilde{\bm{u}}^{n+1}-\bm{r}^n-\frac{1}{Ca} \phi^n \bm{w}^{n+1}-\frac{\beta}{Ca \epsilon} \sum_{\pm} \zeta^n_{\pm}C_{\pm}^{n}\bm{s}_{\pm}^{n+1},\\
			\bm{Q}^{n+1}=&\nabla \widetilde{\bm{u}}^{n+1},\\
			\bm{r}^{n+1} =&\nabla p^{n+1},\\
			Re \frac{\bm{u}^{n+1}-\widetilde{\bm{u}}^{n+1}}{\Delta t} =&-(\bm{r}^{n+1}-\bm{r}^{n}),\\
			\nabla \cdot \bm{u}^{n+1} =&0.
		\end{align}
	\end{subequations}
	Then the LDG scheme to solve \eqref{first_system} is: find $\phi^{n+1}$, $\tilde\mu_{\phi}^{n+1}$, $C_{\pm}^{n+1}$, $\mu_{c_{\pm}}^{n+1}$, $p^{n+1} \in V_h$, $\bm{w}^{n+1}$, $\bm{q}^{n+1}$, $\bm{v}^{n+1}$, $\bm{w}_{\pm}^{n+1}$, $\bm{s}_{\pm}^{n+1}$, $\bm{q}_{\pm}^{n+1}$, $\widetilde{\bm{u}}^{n+1}$, $\bm{u}^{n+1}$, $\bm{r}^{n+1} \in \bm{W}_h$, $\bm{Q}^{n+1} \in \bm{\Pi}_h$, such that, for all test functions $\varphi_1$, $\varphi_2$, $\varphi_3$, $\psi_{\pm}$, $\chi_{\pm} \in V_h$, $\bm{\theta}_1$, $\bm{\theta}_2$, $\bm{\theta}_3$, $\bm{\theta}_4$, $\bm{\theta}_5$, $\bm{\theta}_6$, $\bm{\varrho}_{\pm}$, $\bm{\varpi}_{\pm}$,  $\bm{\vartheta}_{\pm} \in \bm{W}_h$, and $\bm{\Theta} \in \bm{\Pi}_h$, we have
	\begin{subequations}\label{LDG_scheme}
		\begin{align}
			\int_K \frac{\phi^{n+1}-\phi^n}{\Delta t} \varphi_1 dK=&-\int_K (\mathcal{M}\bm{w}^{n+1}-\bm{q}^{n+1}) \cdot \nabla \varphi_1 dK+\int_{\partial K} (\mathcal{M}\widehat{\bm{w}}^{n+1}\nonumber \\
			&-\widehat{\bm{q}}^{n+1}) \cdot \n \varphi_1 ds-\int_K \frac{K}{Ca} \tilde\mu_{\phi}^{n+1} |\bm{v}^n|\varphi_1 dK, 
			\label{LDG_scheme1}\\
			\int_K \bm{w}^{n+1} \cdot \bm{\theta}_1 dK=&-\int_K \tilde\mu_{\phi}^{n+1} \nabla \cdot \bm{\theta}_1 dK+\int_{\partial K} \widehat{\tilde\mu}_{\phi}^{n+1} \bm{\theta}_1 \cdot \n ds,\label{LDG_scheme2} \\
			\int_K \bm{q}^{n+1} \cdot \bm{\theta}_2 dK =& \int_K \phi^n \bm{u}_{*}^n \cdot \bm{\theta}_2 dK,\label{LDG_scheme3}\\
			\int_K \tilde\mu_{\phi}^{n+1} \varphi_2 dK=& \epsilon \int_K \bm{v}^{n+1} \cdot \nabla \varphi_2 dK-\epsilon \int_{\partial K} \widehat{\bm{v}}^{n+1} \cdot \n \varphi_2 ds+\frac{1}{\epsilon}\int_K f(\phi^n)\varphi_2 dK\nonumber \\
			&+ \int_K \left(\frac{S}{\epsilon}(\phi^{n+1}-\phi^n)-\frac{\beta}{\epsilon}\sum_{\pm} \frac{\zeta_{\pm}^{n+1}-\zeta_{\pm}^n}{\phi^{n+1}-\phi^n}C_{\pm}^{n+1}\right) \varphi_2 dK, \label{LDG_scheme4}\\
			\int_K \bm{v}^{n+1} \cdot \bm{\theta}_3 dK =& -\int_K \phi^{n+1} \nabla \cdot \bm{\theta}_3 dK+\int_{\partial K} \widehat{\phi}^{n+1} \bm{\theta}_3 \cdot \n ds,\label{LDG_scheme5}\\
			\int_K  \frac{\zeta_{\pm}^{n+1}C_{\pm}^{n+1}-\zeta_{\pm}^nC_{\pm}^n}{\Delta t}  \psi_{\pm} dK =&-\int_K (\frac{1}{Pe}\bm{w}_{\pm}^{n+1}-\bm{q}_{\pm}^{n+1}) \cdot \nabla \psi_{\pm} dK \nonumber \\
			&+\int_{\partial K}(\frac{1}{Pe} \widehat{\bm{w}}^{n+1}_{\pm}-\widehat{\bm{q}}^{n+1}_{\pm}) \cdot \n \psi_{\pm}ds,\label{LDG_scheme6}\\
			\int_K \bm{w}^{n+1}_{\pm} \cdot \bm{\varrho}_{\pm}dK=&\int_K \zeta_{\pm}^n D_{\pm}^n   C_{\pm}^{n+1} \bm{s}_{\pm}^{n+1} \cdot \bm{\varrho}_{\pm} dK,\label{LDG_scheme7}\\
			\int_K \bm{s}_{\pm}^{n+1} \cdot \bm{\varpi}_{\pm} dK =&-\int_K \mu_{c_{\pm}}^{n+1} \nabla \cdot \bm{\varpi}_{\pm} dK+\int_{\partial K} \widehat{\mu}_{c_{\pm}}^{n+1} \bm{\varpi}_{\pm} \cdot \n ds,\label{LDG_scheme8}\\
			\int_K \mu_{c_{\pm}}^{n+1} \chi_{\pm} dK =& \int_K \ln C_{\pm}^{n+1} \chi_{\pm} dK,\label{LDG_scheme9}\\
			\int_K \bm{q}_{\pm}^{n+1} \cdot \bm{\vartheta}_{\pm} dK =& \int_K \bm{u}_{*}^n \zeta^n_{\pm} C_{\pm}^{n} \cdot \bm{\vartheta}_{\pm} dK, \label{LDG_scheme10}\\
			Re \int_K \frac{\widetilde{\bm{u}}^{n+1}-\bm{u}^n}{\Delta t} \cdot \bm{\theta}_4 dK =& -\eta \int_K \bm{Q}^{n+1} \cdot \nabla  \bm{\theta}_4 dK+\eta \int_{\partial K} (\widehat{\bm{Q}}^{n+1} \cdot \n) \cdot \bm{\theta}_4 ds\nonumber\\
			&- \int_K (Re(\bm{u}^n \cdot \nabla) \widetilde{\bm{u}}^{n+1} +\bm{r}^n+\frac{1}{Ca} \phi^n \bm{w}^{n+1} \nonumber\\
			&+\frac{\beta}{Ca \epsilon} \sum_{\pm} \zeta_{\pm}^n C_{\pm}^{n} \bm{s}_{\pm}^{n+1}) \cdot \bm{\theta}_4 dK,\label{LDG_scheme11}\\
			\int_K \bm{Q}^{n+1} \cdot \bm{\Theta} dK =& -\int_K \widetilde{\bm{u}}^{n+1} \nabla \cdot \bm{\Theta} dK+\int_{\partial K} \widehat{\widetilde{\bm{u}}}^{n+1} \bm{\Theta} \cdot \n ds,\label{LDG_scheme12}\\
			\int_K \bm{r}^{n+1} \cdot \bm{\theta}_5 dK =&-\int_K p^{n+1} \nabla \cdot \bm{\theta}_5 dK+\int_{\partial K} \widehat{p}^{n+1} \bm{\theta}_5 \cdot \n ds,\label{LDG_scheme13}\\
			Re \int_K \frac{\bm{u}^{n+1}-\widetilde{\bm{u}}^{n+1}}{\Delta t} \cdot \bm{\theta}_6 dK=&-\int_K (\bm{r}^{n+1}-\bm{r}^n) \cdot \bm{\theta}_6 dK,\label{LDG_scheme14}\\ 
			0 =& -\int_K \bm{u}^{n+1} \cdot \nabla \varphi_3 dK +\int_{\partial K} \widehat{\bm{u}}_p^{n+1} \cdot \n \varphi_3 ds, \label{LDG_scheme15} 
		\end{align}
	\end{subequations}
	with 
	\begin{equation}\label{LDG_scheme_star}
		\bm{u}_{*}^n=\bm{u}^n-\frac{\Delta t}{Ca Re} \phi^n \bm{w}^{n+1}-\frac{\beta \Delta t}{Ca \epsilon Re} \sum_{\pm} \zeta_{\pm}^n C_{\pm}^{n} \bm{s}_{\pm}^{n+1}.
	\end{equation}
	Here, the ``hat'' terms are the so-called numerical fluxes. To properly define the numerical fluxes, we need to introduce the following notations.

	Let $e$ be an interior  face shared by the ``left'' and ``right'' elements $K_L$ and $K_R$ and define the normal vectors $\n_L$ and  $\n_R$ on $e$ pointing exterior to $K_L$ and $K_R$, respectively. For our purpose, ``left'' and ``right'' can be uniquely defined for each face according to any fixed rule. For example, we choose $\n_0$ as a constant vector. The left element $K_L$ to the face requires that $\n_L \cdot \n_0<0$, and the right one $K_R$ requires $\n_R \cdot \n_0 \geq 0$. If $\psi$ is a function on $K_L$ and $K_R$, but possibly discontinuous across $e$ , let $\psi_L$ denote $(\psi|_{K_L})|_e$ and $\psi_R$ denote $(\psi|_{K_R})|_e$, the left and right trace, respectively.

	In the following proof of the energy stability, we can see the alternating numerical fluxes can guarantee the energy stability, such as
	\begin{align}\label{flux}
		& \widehat{\bm{w}}^{n+1}=\bm{w}^{n+1}_{L}, \;\;\;\; \widehat{\bm{q}}^{n+1}=\bm{q}^{n+1}_L, \;\;\;\; 
		\widehat{\tilde\mu}_{\phi}^{n+1}=\tilde\mu^{n+1}_{\phi,R},\;\;\;\; 
		\widehat{\bm{v}}^{n+1}=\bm{v}^{n+1}_L, 
		\nonumber \\
		& 
		\widehat{\phi}^{n+1}=\phi^{n+1}_R,\;\;\;\;\widehat{\bm{q}}_{\pm}^{n+1}=\bm{q}^{n+1}_{\pm,L},\;\;\;\;\widehat{\bm{w}}_{\pm}^{n+1}=\bm{w}^{n+1}_{\pm,L},\;\;\;\;
		\widehat{\mu}^{n+1}_{c_{\pm}}=\mu^{n+1}_{c_{\pm},R},\\
		&\widehat{\bm{Q}}^{n+1}=\bm{Q}^{n+1}_R,\;\;\;\;  \widehat{\widetilde{\bm{u}}}^{n+1}=\widetilde{\bm{u}}^{n+1}_{L},\;\;\;\;\widehat{p}^{n+1}=p^{n+1}_R, \;\;\;\; \widehat{\bm{u}}_p^{n+1}=\bm{u}^{n+1}_L. \nonumber
	\end{align}
	Under the boundary condition \eqref{eqn: bdc}, the boundary numerical fluxes are
	\begin{equation}\label{flux_bc}
		\widehat{\bm{w}}^{n+1}\cdot \n=0, ~\widehat{\bm{q}}^{n+1}=\bm{0},  ~
		\widehat{\bm{v}}^{n+1}\cdot\n = 0,~
		\widehat{\bm{w}}^{n+1}_{\pm} \cdot \n=0,~
		\widehat{\bm{q}}^{n+1}_{\pm} =\bm{0},~
		\widehat{\bm{u}}_p^{n+1}=\bm{0},    
	\end{equation}
	and the rest boundary fluxes come from the interior of the domain.

	For the convenience of presentation, we introduce some LDG operators. Denote
	\begin{align*}
		&H_K^{+}(r,\bm{v})=\int_K r \nabla \cdot \bm{v} dK\!-\!\int_{\partial K} r_R \bm{v} \cdot \n ds,~
		H_K^{-}(\bm{v},r)=\int_K \bm{v} \cdot \nabla r dK\!-\!\int_{\partial K} \bm{v}_L \cdot \n r ds.
	\end{align*}
	Summing up over $K$, we define
	\begin{equation*}
		H^{+}(r,\bm{v})=\sum_{K}  H_K^{+}(r,\bm{v}),\;\;\;\;\; H^{-}(\bm{v},r)=\sum_{K}  H_K^{-}(\bm{v},r).
	\end{equation*}
	With the special choice of the flux \eqref{flux} and the boundary conditions \eqref{eqn: bdc}, we have the property 
	\begin{equation}\label{H_propeety}
		H^{+}(r,\bm{v})=-H^{-}(\bm{v},r).
	\end{equation}

	Next, we will prove its energy stability.

	\begin{thm}
		Assuming that the condition \eqref{truncation} is satisfied and $S \geq L/2$. Then the solution to the fully-discrete LDG scheme \eqref{LDG_scheme} with the numerical fluxes \eqref{flux} and the boundary conditions \eqref{flux_bc} satisfies the following discrete energy dissipation
		\begin{equation*}
			\mathcal{E}_h^{n+1}-\mathcal{E}_h^n \leq -\Delta t \int_{\Omega} \left(\eta |\bm{Q}^{n+1}|^2+\frac{\mathcal{M}}{Ca} |\bm{w}^{n+1}|^2+\frac{1}{Ca}\frac{K}{Ca}|\bm{v}^n||\tilde\mu_{\phi}^{n+1}|^2+\sum_{\pm} \frac{\beta}{Ca \epsilon Pe}\zeta_{\pm}^nD_{\pm}^n   C_{\pm}^{n+1} |\bm{s}_{\pm}^{n+1}|^2\right)d\x,
		\end{equation*}
		where
		\begin{align*}
			\mathcal{E}_h^n=&\frac{Re}{2} \int_{\Omega}|\bm{u}^n|^2 d\x+\frac{1}{Ca}\int_{\Omega} \left(\frac{\epsilon}{2}|\bm{v}^n|^2+\frac{1}{\epsilon}F(\phi^n)\right)d\x+\frac{\Delta t^2}{2Re}\int_{\Omega} |\bm{r}^n|^2 d\x+\frac{\beta}{Ca \epsilon} \sum_{\pm} \int_{\Omega} \zeta_{\pm}^n C_{\pm}^n (\ln C_{\pm}^n-1)d\x.
		\end{align*}
	\end{thm}
	\begin{proof}
		Taking the inner product of \eqref{LDG_scheme_star} with $\bm{u}_{*}^n$, we obtain
		\begin{equation}\label{LDG-pf1}
			\frac{Re}{\Delta t} \int_K \bm{u}_{*}^n\cdot (\bm{u}_{*}^n-\bm{u}^n)dK=-\int_K \left(\frac{1}{Ca} \phi^n \bm{w}^{n+1}+\frac{\beta}{Ca \epsilon} \sum_{\pm} \zeta_{\pm}^n C_{\pm}^{n} \bm{s}_{\pm}^{n+1}\right) \cdot  \bm{u}_{*}^n dK.   
		\end{equation}
		From \eqref{LDG_scheme_star}, we have
		\begin{equation}\label{LDG-pf2}
			Re \frac{\widetilde{\bm{u}}^{n+1}-\bm{u}^n}{\Delta t}+\frac{1}{Ca} \phi^n \bm{w}^{n+1}+\frac{\beta}{Ca \epsilon}  \sum_{\pm} \zeta_{\pm}^n C_{\pm}^{n} \bm{s}_{\pm}^{n+1} =Re  \frac{\widetilde{\bm{u}}^{n+1}-\bm{u}_{*}^n}{\Delta t}.
		\end{equation}
		For \eqref{LDG_scheme11} of the LDG scheme, taking the test function $\bm{\theta}_4=\widetilde{\bm{u}}^{n+1}$ and using the relation \eqref{LDG-pf2}, we derive
		\begin{align}\label{LDG-pf3}
			Re \int_K \frac{\widetilde{\bm{u}}^{n+1}-\bm{u}_{*}^n}{\Delta t} \cdot  \widetilde{\bm{u}}^{n+1} dK =& -\eta \int_K \bm{Q}^{n+1} \cdot \nabla  \widetilde{\bm{u}}^{n+1} dK+\eta \int_{\partial K} (\widehat{\bm{Q}}^{n+1} \cdot \n) \cdot \widetilde{\bm{u}}^{n+1} ds \nonumber\\
			&- \int_K (Re(\bm{u}^n \cdot \nabla) \widetilde{\bm{u}}^{n+1}+\bm{r}^n) \cdot \widetilde{\bm{u}}^{n+1} dK.
		\end{align}
		For the convenience of presentation, for any $w$ we denote $\mathcal{D}w=w^{n+1}-w^n$. For \eqref{LDG_scheme5} and \eqref{LDG_scheme13}, subtracting the equation at time level $t^n$ from the equation at time level $t^{n+1}$, and choosing test functions $\bm{\theta}_3=\frac{\epsilon}{Ca \Delta t} \bm{v}^{n+1}$, $\bm{\theta}_5=\bm{u}^{n+1}$, we get
		\begin{align}
			\frac{\epsilon}{Ca \Delta t} \int_K \mathcal{D} \bm{v} \cdot \bm{v}^{n+1} dK &=-\frac{\epsilon}{Ca \Delta t} H_K^{+}(\mathcal{D}\phi, \bm{v}^{n+1}),\label{LDG-pf4}\\
			\int_K \mathcal{D} \bm{r} \cdot \bm{u}^{n+1} dK &=-H_K^{+}(\mathcal{D}p,\bm{u}^{n+1}).\label{LDG-pf5}
		\end{align}
		For \eqref{LDG_scheme1}, \eqref{LDG_scheme2}, \eqref{LDG_scheme3}, \eqref{LDG_scheme4}, \eqref{LDG_scheme6}, \eqref{LDG_scheme7}, \eqref{LDG_scheme8}, \eqref{LDG_scheme9}, \eqref{LDG_scheme10}, \eqref{LDG_scheme12}, \eqref{LDG_scheme14} and \eqref{LDG_scheme15} in the fully-discrete scheme, taking the test functions as
		\begin{align*}
			& \varphi_1=\frac{1}{Ca} \tilde\mu_{\phi}^{n+1},\;\; \bm{\theta}_1=\frac{1}{Ca}(\mathcal{M} \bm{w}^{n+1}-\bm{q}^{n+1}),\;\;\bm{\theta}_2=\frac{1}{Ca} \bm{w}^{n+1},\;\; \varphi_2=-\frac{1}{Ca \Delta t} \mathcal{D} \phi,\\
			&\psi_{\pm}=\frac{\beta }{Ca \epsilon} \mu_{c_{\pm}}^{n+1},\;\; \bm{\varrho}_{\pm}=-\frac{\beta }{Ca \epsilon Pe} \bm{s}_{\pm}^{n+1},\;\;\bm{\varpi}_{\pm}=\frac{\beta}{Ca \epsilon} (\frac{1}{Pe} \bm{w}_{\pm}^{n+1}-\bm{q}_{\pm}^{n+1}),\;\;\bm{\theta}_6=\bm{u}^{n+1},\\
			& \chi_{\pm}=-\frac{\beta}{Ca \epsilon \Delta t}(\zeta_{\pm}^{n+1}C_{\pm}^{n+1}-\zeta_{\pm}^{n}C_{\pm}^{n}),\;\;\bm{\vartheta}_{\pm}=\frac{\beta }{Ca \epsilon} \bm{s}_{\pm}^{n+1},\;\;\bm{\Theta}=\eta \bm{Q}^{n+1}, \;\;\varphi_3=\mathcal{D} p.
		\end{align*}
		We have
		\begin{align}
			\frac{1}{Ca \Delta t}\int_K \mathcal{D} \phi \tilde\mu_{\phi}^{n+1} dK =&-\frac{1}{Ca}H_K^{-}(\mathcal{M} \bm{w}^{n+1}-\bm{q}^{n+1},\tilde\mu_{\phi}^{n+1}) \nonumber\\
			&-\frac{1}{Ca}\frac{K}{Ca}\int_K |\bm{v}^n| |\tilde\mu_{\phi}^{n+1}|^2 dK,\\
			\frac{1}{Ca}\int_K \bm{w}^{n+1} \cdot (\mathcal{M} \bm{w}^{n+1}-\bm{q}^{n+1}) dK =&-\frac{1}{Ca} H_K^{+}(\tilde\mu_{\phi}^{n+1},\mathcal{M} \bm{w}^{n+1}-\bm{q}^{n+1}),\\
			\frac{1}{Ca}\int_K \bm{q}^{n+1} \cdot \bm{w}^{n+1} dK &=\frac{1}{Ca} \int_K \phi^n \bm{u}_{*}^n \cdot \bm{w}^{n+1}dK,\\
			-\frac{1}{Ca \Delta t}\int_K \tilde\mu_{\phi}^{n+1} \mathcal{D} \phi dK =&-\frac{\epsilon}{Ca \Delta t} H_K^{-}(\bm{v}^{n+1},\mathcal{D}\phi)+\frac{\beta}{Ca \Delta t \epsilon}\int_K \sum_{\pm} \mathcal{D} \zeta_{\pm} C_{\pm}^{n+1}dK\nonumber\\
			&-\frac{1}{Ca \Delta t}\int_K \left(\frac{S}{\epsilon}(\mathcal{D}\phi)^2+\frac{1}{\epsilon} f(\phi^n) \mathcal{D}\phi\right)dK,\\
			\frac{\beta}{Ca \epsilon \Delta t}\int_K (\zeta_{\pm}^{n+1}C_{\pm}^{n+1}-\zeta_{\pm}^{n}C_{\pm}^{n})\mu_{c_{\pm}}^{n+1}dK=& -\frac{\beta}{Ca \epsilon} H_K^{-}(\frac{1}{Pe} \bm{w}_{\pm}^{n+1}-\bm{q}_{\pm}^{n+1},\mu_{c_{\pm}}^{n+1}),\\
			-\frac{\beta}{Ca \epsilon Pe}\int_K \bm{w}^{n+1}_{\pm} \cdot \bm{s}_{\pm}^{n+1}dK=&-\frac{\beta}{Ca \epsilon Pe}\int_K \zeta_{\pm}^n D_{\pm}^n   C_{\pm}^{n+1} \bm{s}_{\pm}^{n+1} \cdot \bm{s}_{\pm}^{n+1} dK,\\
			\frac{\beta}{Ca \epsilon}\int_K \bm{s}_{\pm}^{n+1} \cdot (\frac{1}{Pe}\bm{w}^{n+1}_{\pm}-\bm{q}^{n+1}_{\pm}) dK =&-\frac{\beta }{Ca \epsilon}H_K^{+}(\mu_{c_{\pm}}^{n+1},\frac{1}{Pe}\bm{w}^{n+1}_{\pm}-\bm{q}^{n+1}_{\pm}),\\
			-\frac{\beta}{Ca \epsilon \Delta t}\int_K \mu_{c_{\pm}}^{n+1} (\zeta_{\pm}^{n+1}C_{\pm}^{n+1}-\zeta_{\pm}^{n}C_{\pm}^{n}) dK =&-\frac{\beta}{Ca \epsilon \Delta t} \int_K \ln C_{\pm}^{n+1} (\zeta_{\pm}^{n+1}C_{\pm}^{n+1}-\zeta_{\pm}^{n}C_{\pm}^{n}) dK,\\
			\frac{\beta}{Ca \epsilon}\int_K \bm{q}_{\pm}^{n+1} \cdot \bm{s}_{\pm}^{n+1}dK =& \frac{\beta}{Ca \epsilon}\int_K \bm{u}_{*}^n \zeta^n_{\pm} C_{\pm}^{n} \cdot \bm{s}_{\pm}^{n+1} dK, \\
			\eta \int_K \bm{Q}^{n+1} \cdot \bm{Q}^{n+1} dK =& -\eta \int_K \widetilde{\bm{u}}^{n+1} \nabla \cdot \bm{Q}^{n+1} dK+\eta \int_{\partial K} \widehat{\widetilde{\bm{u}}}^{n+1} \bm{Q}^{n+1} \cdot \n ds,\\
			Re \int_K \frac{\bm{u}^{n+1}-\widetilde{\bm{u}}^{n+1}}{\Delta t} \cdot \bm{u}^{n+1} dK=&-\int_K (\bm{r}^{n+1}-\bm{r}^n) \cdot \bm{u}^{n+1} dK,\\
			0=&-H_K^{-}(\bm{u}^{n+1},\mathcal{D}p).\label{LDG-pf6}
		\end{align}
		Now combining the equations \eqref{LDG-pf1}, \eqref{LDG-pf3}-\eqref{LDG-pf6}, summing over all elements $K$ and by the property \eqref{H_propeety}, we have
		\begin{align}\label{LDG-pf7}
			& \frac{\epsilon}{Ca \Delta t} \int_{\Omega}  \bm{v}^{n+1} \cdot(\bm{v}^{n+1}-\bm{v}^n)d\x +\frac{Re}{\Delta t} \int_{\Omega} \bm{u}^{n+1} \cdot (\bm{u}^{n+1}-\widetilde{\bm{u}}^{n+1})d\x \\
			&+\frac{Re}{\Delta t} \int_{\Omega} \bm{u}_{*}^n \cdot (\bm{u}_{*}^n-\bm{u}^n) d\x\!\! +\!\!\frac{Re}{\Delta t} \int_{\Omega} \widetilde{\bm{u}}^{n+1} \cdot (\widetilde{\bm{u}}^{n+1}-\bm{u}_{*}^n)d\x \!\!+\!\!\frac{1}{Ca} \int_{\Omega} \mathcal{M} \bm{w}^{n+1} \cdot  \bm{w}^{n+1} d\x\nonumber \\
			&+\frac{K}{Ca} \int_{\Omega} |\bm{v}^n| |\tilde\mu_{\phi}^{n+1}|^2 d\x +\frac{\beta}{Ca \epsilon Pe} \sum_{\pm} \int_{\Omega} \zeta_{\pm}^n D_{\pm}^n   C_{\pm}^{n+1} \bm{s}_{\pm}^{n+1} \cdot  \bm{s}_{\pm}^{n+1} d\x\nonumber \\
			&+\eta \int_{\Omega} \bm{Q}^{n+1} \cdot \bm{Q}^{n+1} d\x+\int_{\Omega} \bm{r}^n \cdot \widetilde{\bm{u}}^{n+1}d\x +\frac{1}{Ca \Delta t}\int_{\Omega} \left(\frac{S}{\epsilon}\mathcal{D}\phi+\frac{f(\phi^n)}{\epsilon}\right)\mathcal{D} \phi d\x\nonumber\\
			&+\frac{\beta}{Ca \epsilon \Delta t}\sum_{\pm}\int_{\Omega} \left(\ln C_{\pm}^{n+1}(\zeta_{\pm}^{n+1} C_{\pm}^{n+1}-\zeta_{\pm}^{n} C_{\pm}^{n})-\mathcal{D} \zeta_{\pm} C_{\pm}^{n+1}\right) d\x =0.\nonumber
		\end{align}



		For the last two terms in \eqref{LDG-pf7}, we have
		\begin{align}\label{LDG-pf8}
			&\frac{1}{Ca}\int_{\Omega} \left(\frac{S}{\epsilon}\mathcal{D}\phi+\frac{f(\phi^n)}{\epsilon}\right)\mathcal{D} \phi d\x+\frac{\beta}{Ca \epsilon}\sum_{\pm}\int_{\Omega} \left(\ln C_{\pm}^{n+1}(\zeta_{\pm}^{n+1} C_{\pm}^{n+1}-\zeta_{\pm}^{n} C_{\pm}^{n})-\mathcal{D} \zeta_{\pm} C_{\pm}^{n+1}\right) d\x  \\
			=&\frac{1}{Ca \epsilon} \int_{\Omega} \left(F(\phi^{n+1})-F(\phi^n)\right) d\x+\frac{1}{Ca \epsilon} \int_{\Omega} \left(S-\frac{f'(\xi_n)}{2}\right) (\mathcal{D}\phi)^2 d\x\nonumber\\
			&+\frac{\beta}{Ca \epsilon} \sum_{\pm} \int_{\Omega}\left(\zeta_{\pm}^{n+1}C_{\pm}^{n+1}(\ln C_{\pm}^{n+1}-1)-\zeta_{\pm}^{n}C_{\pm}^{n}(\ln C_{\pm}^{n}-1)\right) d\x+\frac{\beta}{Ca \epsilon} \sum_{\pm} \int_{\Omega} \frac{\zeta_{\pm}^n C_{\pm}^n}{2\xi^2}(\mathcal{D} C_{\pm})^2d\x.\nonumber 
		\end{align}
		To deal with the term $\int_{\Omega} \bm{r}^n \cdot \widetilde {\bm{u}}^{n+1}$, we take $\bm{\theta}_6=\bm{r}^n$  and $\bm{r}^{n+1}$ in \eqref{LDG_scheme14}, sum over all elements,
		% and use the identity
		% \begin{equation*}
			%     (a-b)b=\frac{1}{2}a^2-\frac{1}{2}b^2-\frac{1}{2}(a-b)^2
			% \end{equation*}
		%to obtain
		\begin{align}\label{LDG-pf9}
			\frac{Re}{\Delta t} \int_{\Omega} \widetilde{\bm{u}}^{n+1} \cdot \bm{r}^n d\x=\frac{1}{2} \int_{\Omega}\left(|\bm{r}^{n+1}|^2-|\bm{r}^{n}|^2-|\bm{r}^{n+1}-\bm{r}^{n}|^2\right) d\x,\\
			\frac{Re}{\Delta t} \int_{\Omega} \widetilde{\bm{u}}^{n+1} \cdot \bm{r}^{n+1} d\x=\frac{1}{2} \int_{\Omega}\left(|\bm{r}^{n+1}|^2-|\bm{r}^{n}|^2+|\bm{r}^{n+1}-\bm{r}^{n}|^2\right) d\x.
		\end{align}
		where the term $\int_{\Omega} \bm{u}^{n+1} \cdot \bm{r}^n d\x$ is zero because of the divergence-free condition.

		Using the above two equations and  \eqref{LDG_scheme14}  yield
		\begin{equation}\label{LDG-pf10}
			\frac{Re^2 }{\Delta t^2} \int_{\Omega}|\bm{u}^{n+1}-\widetilde{\bm{u}}^{n+1}|^2 d\x=\int_{\Omega} |\bm{r}^{n+1}-\bm{r}^n|^2 d\x.  
		\end{equation}
		% by the equality
		% \begin{equation*}
			%     \frac{Re}{\Delta t} \int_{\Omega} \widetilde{\bm{u}}^{n+1} \cdot \bm{r}^{n+1} d\x=\frac{1}{2} \int_{\Omega}\left(|\bm{r}^{n+1}|^2-|\bm{r}^{n}|^2+|\bm{r}^{n+1}-\bm{r}^{n}|^2\right) d\x.
			% \end{equation*}
		Combining \eqref{LDG-pf9} and \eqref{LDG-pf10}, we find
		\begin{equation}\label{LDG-pf11}
			\int_{\Omega} \bm{r}^n \cdot \widetilde{\bm{u}}^{n+1}d\x=\frac{\Delta t}{2Re}\int_{\Omega} (|\bm{r}^{n+1}|^2-|\bm{r}^{n}|^2)d\x-\frac{Re}{2 \Delta t} \int_{\Omega} |\bm{u}^{n+1}-\widetilde{\bm{u}}^{n+1}|^2d\x.
		\end{equation}
		Combining \eqref{LDG-pf7}, \eqref{LDG-pf8}, and \eqref{LDG-pf11}, we obtain
		\begin{align*}
			&\frac{\epsilon}{2Ca \Delta t}\int_{\Omega} \left(|\bm{v}^{n+1}|^2-|\bm{v}^n|^2\right)d\x+\frac{Re}{2\Delta t} \int_{\Omega} \left(|\bm{u}^{n+1}|^2-|\bm{u}^n|^2\right)d\x+\frac{\Delta t}{2Re}\int_{\Omega} \left(|\bm{r}^{n+1}|^2-|\bm{r}^n|^2\right)d\x\\
			& +\frac{1}{Ca \epsilon \Delta t} \int_{\Omega} \left(F(\phi^{n+1})-F(\phi^n)\right) d\x+\frac{\beta}{Ca \epsilon \Delta t} \sum_{\pm} \int_{\Omega} \left(\zeta_{\pm}^{n+1}C_{\pm}^{n+1}(\ln C_{\pm}^{n+1}-1)-\zeta_{\pm}^{n}C_{\pm}^{n}(\ln C_{\pm}^{n}-1)\right)d\x \\
			\leq &-\left(\frac{1}{Ca} \int_{\Omega} \mathcal{M} |\bm{Q}^{n+1}|^2 d\x+\frac{1}{Ca}\frac{K}{Ca} \int_{\Omega} |\tilde\mu_{\phi}^{n+1}|^2 |\bm{v}^n|d\x+\eta\int_{\Omega} |\bm{Q}^{n+1}|^2 d\x+\frac{\beta}{Ca \epsilon Pe} \sum_{\pm} \int_{\Omega} \zeta_{\pm}^n D_{\pm}^n   C_{\pm}^{n+1} |\bm{s}_{\pm}^{n+1}|^2 d\x\right),
		\end{align*}
		where we use the identity
		$ a(a-b)=\frac{1}{2}a^2-\frac{1}{2}b^2+\frac{1}{2}(a-b)^2 $
		for $a=\bm{u}^{n+1},\bm{u}_{*}^n, \widetilde{\bm{u}}^{n+1}, \bm{v}^{n+1}$, and $b=\widetilde{\bm{u}}^{n+1}, \bm{u}^{n}, \bm{u}_{*}^n, \bm{v}^n$, respectively. 
		Therefore, we have the energy stability result.
	\end{proof}



	\subsection{The semi-implicit SDC method}
	\label{subse3}
	The scheme proposed above is energy stable. However, it is limited to first-order temporal accuracy, while the LDG method is high-order accurate in space. To achieve high-order accuracy in time and space, we iteratively incorporate the semi-implicit spectral deferred correction (SDC) method \cite{guo-xia, guo-xu-xia}, based on the energy-stabilized first-order scheme. 

	We now perform the SDC procedure over each time interval \([t^n, t^{n+1}]\). To do this, we divide the interval \([t^n, t^{n+1}]\) into \(P\) subintervals by selecting interpolation points \(\{t^{n,m}\}_{m=0}^P\) such that
	\[
	t^n = t^{n,0} < t^{n,1} < \cdots < t^{n,m} < \cdots < t^{n,P} = t^{n+1}.
	\]
	Let \(\Delta t^{n,m} = t^{n,m+1} - t^{n,m}\) and denote by \(\phi_L^{n,m}\) the \(L\)th-order approximation of \(\phi(t^{n,m})\). To ensure high-order accuracy and avoid the instability associated with equispaced nodes, the time nodes \(\{t^{n,m}\}_{m=0}^P\) can be chosen as the Chebyshev–Gauss–Lobatto points on \([t^n, t^{n+1}]\).

	Starting from the known solution \((\phi^n, \bm{u}^n, C_{\pm}^n)\) at time \(t^n\), we outline below the algorithm used to compute the updated solution \((\phi^{n+1}, \bm{u}^{n+1}, C_{\pm}^{n+1})\).

	{\bf Compute the initial approximation:}

	Let $\phi_1^{n,0}=\phi^n$, $\bm{u}_1^{n,0}=\bm{u}^n$ and $C_{\pm,1}^{n,0}=C_{\pm}^n$.

	Use the first-order scheme  \eqref{eq:semi-phi}-\eqref{eq:projection}  to compute a first-order accurate approximate solution $\phi_1$, $\bm{u}_1$ and $C_{\pm,1}$ at the nodes $\{t^{n,m}\}_{m=1}^P$, i.e. 

	For $m=0,\ldots,P-1$

	\noindent {\bf Step 1:}
	\begin{equation}
		\left\{
		\begin{aligned}
			& \phi^{n,m+1}_1=\phi^{n,m}_1+\Delta t^{n,m} (\mathcal{M} \Delta \tilde \mu_{\phi,1}^{n,m+1}-\nabla \cdot (\phi_1^{n,m}\bm{u}^{n,m}_{*,1})-\frac{K}{Ca}\tilde \mu_{\phi,1}^{n,m+1} |\nabla \phi_{1}^{n,m}|),\\
			& \tilde \mu_{\phi,1}^{n,m+1}=-\epsilon \Delta \phi_1^{n,m+1}+\frac{S}{\epsilon}(\phi_1^{n,m+1}-\phi_1^{n,m})+\frac{1}{\epsilon} f(\phi_1^{n,m})-\frac{\beta}{\epsilon}\sum_{\pm} \frac{\zeta_{\pm,1}^{n,m+1}-\zeta_{\pm,1}^{n,m}}{\phi_1^{n,m+1}-\phi_1^{n,m}} C_{\pm,1}^{n,m+1}, \\
			&\zeta_{\pm,1}^{n,m+1}C_{\pm,1}^{n,m+1}=\zeta_{\pm,1}^{n,m}C_{\pm,1}^{n,m}+\Delta t^{n,m}(\frac{1}{Pe} \nabla \cdot (\zeta_{\pm,1}^{n,m}D_{\pm,1}^{n,m}C_{\pm,1}^{n,m+1}\nabla \mu_{{c}_{\pm,1}}^{n,m+1})-\nabla \cdot(\bm{u}^{n,m}_{*,1}\zeta_{\pm,1}^{n,m}C_{\pm,1}^{n,m} )),\\
			&\mu_{{c}_{\pm,1}}^{n,m+1}=\ln C_{\pm,1}^{n,m+1},
		\end{aligned}
		\right .
	\end{equation}
	with
	\begin{equation}
		\bm{u}_{*,1}^{n,m}=\bm{u}_1^{n,m}-\frac{\Delta t^{n,m}}{Ca Re} \phi_1^{n,m} \nabla \tilde \mu_{\phi,1}^{n,m+1} -\frac{\beta \Delta t^{n,m}}{Ca \epsilon Re}\sum_{\pm}\zeta_{\pm,1}^{n,m} C_{\pm,1}^{n,m} \nabla \mu_{c_{\pm,1}}^{n,m+1};
	\end{equation}
	\noindent {\bf Step 2:}
	\begin{align}
		\widetilde{\bm{u}}_1^{n,m+1}=&\bm{u}_1^{n,m}-\Delta t^{n,m} (\bm{u}_1^{n,m} \cdot \nabla) \widetilde{\bm{u}}_1^{n,m+1} \nonumber\\
		&+\frac{\Delta t^{n,m}}{Re} (\eta \Delta \widetilde{\bm{u}}_1^{n,m+1}-\nabla p_1^{n,m}-\frac{1}{Ca} \phi_1^{n,m} \nabla \tilde \mu_{\phi,1}^{n,m+1}-\frac{\beta}{Ca \epsilon}\sum_{\pm}\zeta_{\pm,1}^{n,m} C_{\pm,1}^{n,m} \nabla \mu_{c_{\pm,1}}^{n,m+1} );
	\end{align}
	\noindent {\bf Step 3:}
	\begin{align}
		-\Delta (p_1^{n,m+1}-p_1^{n,m})&=-\frac{Re}{\Delta t^{n,m}} \nabla \cdot \widetilde{\bm{u}}^{n,m+1}_1,\\
		\bm{u}_1^{n,m+1}&=\widetilde{\bm{u}}^{n,m+1}_1-\frac{\Delta t^{n,m}}{Re}\nabla (p_1^{n,m+1}-p_1^{n,m}).
	\end{align}

	{\bf Compute successive corrections:}

	For $l=1,...,L$, 

	Let $\phi_{l+1}^{n,0}=\phi^n$, $\bm{u}_{l+1}^{n,0}=\bm{u}^n$ and $C_{\pm,l+1}^{n,0}=C_{\pm}^n$.

	For $m=0,\ldots,P-1$

	\noindent {\bf Step 1:}
	\begin{equation}
		\left\{
		\begin{aligned}
			\phi^{n,m+1}_{l+1}=& \phi^{n,m}_{l+1}+\Delta t^{n,m} (\mathcal{M} \Delta \tilde \mu_{\phi,l+1}^{n,m+1}-\nabla \cdot (\phi_{l+1}^{n,m}\bm{u}^{n,m}_{*,l+1})-\frac{K}{Ca}\tilde \mu_{\phi,l+1}^{n,m+1} |\nabla \phi_{l+1}^{n,m}| \\
			&-\mathcal{M} \Delta \tilde \mu_{\phi,l}^{n,m+1}+\nabla \cdot (\phi_{l}^{n,m}\bm{u}^{n,m}_{*,l})+\frac{K}{Ca}\tilde \mu_{\phi,l}^{n,m+1} |\nabla \phi_{l}^{n,m}|)+I_m^{m+1} (F_{\phi}), \\
			\tilde \mu_{\phi,l+1}^{n,m+1}=&-\epsilon \Delta \phi_{l+1}^{n,m+1}+\frac{S}{\epsilon}(\phi_{l+1}^{n,m+1}-\phi_{l+1}^{n,m})+\frac{1}{\epsilon} f(\phi_{l+1}^{n,m})-\frac{\beta}{\epsilon}\sum_{\pm} \frac{\zeta_{\pm,l+1}^{n,m+1}-\zeta_{\pm,l+1}^{n,m}}{\phi_{l+1}^{n,m+1}-\phi_{l+1}^{n,m}} C_{\pm,l+1}^{n,m+1},\\
			\zeta_{\pm,l+1}^{n,m+1} C_{\pm,l+1}^{n,m+1}=&\zeta_{\pm,l+1}^{n,m} C_{\pm,l+1}^{n,m}+\Delta t^{n,m} (\frac{1}{Pe}\nabla \cdot (\zeta_{\pm,l+1}^{n,m}D_{\pm,l+1}^{n,m}C_{\pm,l+1}^{n,m+1} \nabla \mu_{c_{\pm,l+1}}^{n,m+1})-\nabla \cdot (\bm{u}_{*,l+1}^{n,m}\zeta_{\pm,l+1}^{n,m}C_{\pm,l+1}^{n,m}) \\
			&-\frac{1}{Pe}\nabla \cdot (\zeta_{\pm,l}^{n,m}D_{\pm,l}^{n,m}C_{\pm,l}^{n,m+1} \nabla \mu_{c_{\pm,l}}^{n,m+1})+\nabla \cdot (\bm{u}_{*,l}^{n,m}\zeta_{\pm,l}^{n,m}C_{\pm,l}^{n,m}))+I_m^{m+1}(F_{c_{\pm}}),\\
			\mu_{{c}_{\pm,l+1}}^{n,m+1}=&\ln C_{\pm,l+1}^{n,m+1},
		\end{aligned}
		\right.
	\end{equation}
	with
	\begin{align*}
		& \bm{u}_{*,l+1}^{n,m}=\bm{u}_{l+1}^{n,m}-\frac{\Delta t^{n,m}}{Ca Re} \phi_{l+1}^{n,m} \nabla \tilde \mu_{\phi,l+1}^{n,m+1} -\frac{\beta \Delta t^{n,m}}{Ca \epsilon Re}\sum_{\pm}\zeta_{\pm,l+1}^{n,m} C_{\pm,l+1}^{n,m} \nabla \mu_{c_{\pm,l+1}}^{n,m+1},\\
		&  F_{\phi}=\mathcal{M} \Delta \tilde \mu_{\phi,l}-\nabla \cdot(\phi_l \bm{u}_l)-\frac{K}{Ca} \tilde \mu_{\phi,l} |\nabla \phi_l|,\\
		&F_{c_{\pm}}=\frac{1}{Pe} \nabla \cdot(\zeta_{\pm,l}D_{\pm,l}C_{\pm,l}\nabla \mu_{c_{\pm,l}})-\nabla \cdot (\bm{u}_l \zeta_{\pm,l}C_{\pm,l});
	\end{align*}
	\noindent {\bf Step 2:}
	\begin{align}
		\widetilde{\bm{u}}_{l+1}^{n,m+1}=&\bm{u}_{l+1}^{n,m}-\Delta t^{n,m}((\bm{u}_{l+1}^{n,m} \cdot \nabla) \widetilde{\bm{u}}_{l+1}^{n,m+1}-(\bm{u}_{l}^{n,m} \cdot \nabla) \widetilde{\bm{u}}_{l}^{n,m+1})+\frac{\Delta t^{n,m}}{Re}(\eta \Delta \widetilde{\bm{u}}_{l+1}^{n,m+1}-\nabla p_{l+1}^{n,m} \nonumber \\
		&-\frac{1}{Ca} \phi_{l+1}^{n,m} \nabla \tilde \mu_{\phi,l+1}^{n,m+1}-\frac{\beta}{Ca \epsilon}\sum_{\pm}\zeta_{\pm,l+1}^{n,m} C_{\pm,l+1}^{n,m} \nabla \mu_{c_{\pm,l+1}}^{n,m+1}-\eta \Delta \widetilde{\bm{u}}_{l}^{n,m+1}+\nabla p_{l}^{n,m}  \\
		&+\frac{1}{Ca} \phi_{l}^{n,m} \nabla \tilde \mu_{\phi,l}^{n,m+1}+\frac{\beta}{Ca \epsilon}\sum_{\pm}\zeta_{\pm,l}^{n,m} C_{\pm,l}^{n,m} \nabla \mu_{c_{\pm,l}}^{n,m+1})+I_m^{m+1} (F_{\bm{u}}), \nonumber
	\end{align}
	where
	\begin{equation*}
		F_{\bm{u}}=-(\bm{u}_l \cdot \nabla) \widetilde{\bm{u}}_l+\frac{1}{Re}(\eta \Delta \widetilde{\bm{u}}_l-\nabla p_l-\frac{1}{Ca} \phi_l \nabla \tilde \mu_{\phi,l}-\frac{\beta}{Ca \epsilon} \sum_{\pm} \zeta_{\pm,l}C_{\pm,l} \nabla \mu_{c_{\pm,l}});
	\end{equation*}
	\noindent {\bf Step 3:}
	\begin{align}
		&- (\Delta p^{n,m+1}_{l+1}-\Delta p^{n,m}_{l+1}) = -\frac{Re}{\Delta t^{n,m}} (\nabla \cdot \widetilde{\bm{u}}^{n,m+1}_{l+1}-\nabla \cdot \widetilde{\bm{u}}^{n,m+1}_l) +I_m^{m+1} (F),\\
		&\bm{u}_{l+1}^{n,m+1}=\widetilde{\bm{u}}^{n,m+1}_{l+1}+\frac{\Delta t^{n,m}}{Re}\nabla(p_{l+1}^{n,m+1}-p_{l+1}^{n,m})-\frac{\Delta t^{n,m}}{Re}\nabla(p_{l}^{n,m+1}-p_{l}^{n,m}),
	\end{align}
	where
	\begin{equation*}
		F=-\frac{Re}{(\Delta t^{n,m})^2} \nabla \cdot \widetilde{\bm{u}}_l.
	\end{equation*}
	Here, $I_m^{m+1}(F_{\phi})$ is the integral of the $P$-th degree interpolating polynomial on the $P+1$ points $(t^{n,m},F_{\phi})_{m=0}^P$ over the subinterval $[t^{n,m},t^{n,m+1}]$, which is the numerical quadrature approximation of
	\begin{equation*}
		\int_{t^{n,m}}^{t^{n,m+1}} F_{\phi} dt.
	\end{equation*}
	Finally, we have $\phi^{n+1}=\phi^{n,P}_{L+1}$, $\bm{u}^{n+1}=\bm{u}^{n,P}_{L+1}$ and $C_{\pm}^{n+1}=C_{\pm,L+1}^{n,P}$.
	\begin{remark}(Local truncation error.) 
		The local truncation error obtained with the above semi-implicit SDC scheme \cite{guo-xu-xia} is
		$\mathcal{O}(\tau^{\min[L+1,P+1]}),$
		where $\tau=\max \limits_{n,m} \Delta t^{n,m}$.
	\end{remark}
	% \begin{remark}
		% The proposed LDG spatial discretization and semi-implicit SDC temporal integration methods are capable of achieving high-order accuracy in both space and time. However, due to the increased computational cost associated with higher-order schemes, we restrict our numerical experiments to second-order accuracy in both time and space.
		% \end{remark}
