\section{Model Derivation Details}
We calculate the time derivative of the total energy given in \eqref{energyfunction}.
For the first term, by using the first two equations of equation \eqref{kimematic assume oss}, we have 
\begin{align}\label{eqn: kinetic dissipation}
I_1 
=&\frac{d}{dt}(\frac{1}{2}\int_{\Omega}\rho|\bm{u}|^{2}d\bm{x})
\nonumber\\
=&\frac{1}{2}\int_{\Omega}\frac{\partial\rho}{\partial t}|\bm{u}|^{2}d\bm{x}
+\int_{\Omega}\rho\bm{u}\cdot\frac{\partial \bm{u}}{\partial t}d\bm{x}
\nonumber\\
=&\frac{1}{2}\int_{\Omega}\frac{\partial\rho}{\partial t}|\bm{u}|^{2}d\bm{x}
+\int_{\Omega}\rho\bm{u}\cdot\frac{\textbf{D}\bm{u}}{\textbf{D}t}d\bm{x}
+\int_{\Omega}\nabla\cdot(\rho\bm{u})\frac{|\bm{u}|^{2}}{2}d\bm{x}
\nonumber\\
=&\int_{\Omega}\bm{u}\cdot(\nabla\cdot\bm\sigma_{\eta}+\nabla\cdot\bm\sigma_{\phi})d\bm{x}
-\int_{\Omega}p\nabla\cdot\bm{u}d\bm{x}
\nonumber\\
=&-\int_{\Omega}\nabla\bm{u}:(\bm\sigma_{\eta}+\bm\sigma_{\phi})d\bm{x}
-\int_{\Omega}p\nabla\cdot\bm{u}d\bm{x}. 
\end{align}
where pressure is induced as a Lagrange multiplier for incompressibility. 

For the second term,  the equation of the concentrations and label functions  yields 
\begin{eqnarray}
I_2+I_3 &=& \frac{d}{dt}\left\{  \int_{\Omega}RT \left( \zeta_+   C_+(\ln{\frac{ C_+}{c_\infty}}-1) +  \zeta_- C_-(\ln{\frac{C_-}{c_\infty}}-1)\right) d\bm{x}+ \int_{\Omega} \lambda \left(\frac{l^2|\nabla\phi|^2 }{2}+F(\phi)\right) d\bm{x}\right\}\nonumber\\
&=& \int_{\Omega}RT \left(\zeta_+\ln \frac{ C_+}{c_\infty}\frac{\partial  C_+}{\partial t} +\zeta_-\ln \frac{ C_+}{c_\infty}\frac{\partial C_-}{\partial t} \right)d\bm{x} \nonumber\\
&&+ \int_{\Omega}\left(RT\left( \frac{\partial \zeta_+}{\partial \phi}   C_+(\ln{\frac{ C_+}{c_\infty}}-1) +  \frac{\partial\zeta_-}{\partial\phi} C_-(\ln{\frac{C_-}{c_\infty}}-1)\right)+\mu_{\phi}\right)\frac{\partial\phi}{\partial t}d\bm{x} \nonumber\\
&=& \int_{\Omega} RT \left(\ln \frac{ C_+}{c_\infty}\frac{\partial (\zeta_+ C_+)}{\partial t} +\ln \frac{ C_+}{c_\infty}\frac{(\partial \zeta_-C_-)}{\partial t} \right) d\bm{x}  \nonumber\\
&& +  \int_{\Omega}\left(RT\left( \frac{\partial \zeta_+}{\partial \phi}   C_+(\ln{\frac{ C_+}{c_\infty}}-1) +  \frac{\partial\zeta_-}{\partial\phi} C_-(\ln{\frac{C_-}{c_\infty}}-1)\right)+\mu_{\phi}- C_+\ln{\frac{ C_+}{c_\infty}}\frac{\partial \zeta_+}{\partial \phi} -C_-\ln{\frac{C_-}{c_\infty}}\frac{\partial \zeta_-}{\partial \phi}\right)\frac{\partial\phi}{\partial t}d\bm{x} \nonumber\\
&=&  \int_{\Omega} RT \left(\ln \frac{ C_+}{c_\infty}\frac{\partial (\zeta_+ C_+)}{\partial t} +\ln \frac{ C_+}{c_\infty}\frac{\partial (\zeta_-C_-)}{\partial t} \right) d\bm{x}   
+   \int_{\Omega}\left(RT\left(- \frac{\partial \zeta_+}{\partial \phi}   C_+ - \frac{\partial\zeta_-}{\partial\phi} C_-  \right)+\mu_{\phi} \right)\frac{\partial\phi}{\partial t}d\bm{x} \nonumber\\
&=& \int_{\Omega} RT \left(-\ln \frac{ C_+}{c_\infty}  \nabla\cdot(\zeta_+ C_+\bm{u})  -\ln \frac{ C_+}{c_\infty}\nabla\cdot (\zeta_-C_-\bm{u}) \right) d\bm{x}  \nonumber\\
&&+ \int_{\Omega} RT \left(-\ln \frac{ C_+}{c_\infty}  \nabla\cdot(\zeta_+\bm{J}_+)  -\ln \frac{C_-}{c_\infty}\nabla\cdot (\zeta_-\bm{J}_-) \right) d\bm{x}   \nonumber\\
&&+\int_{\Omega}\tilde{\mu}_{\phi}(-\nabla\cdot(\bm{u}\phi)-\nabla\cdot\bm{J}_{\phi}+S_{\phi}|\nabla\phi|)d\bm{x} \nonumber\\
% &=&\int_{\Omega}RT(\zeta_+\nabla C^+ \cdot\bm{u} +\zeta_-\nabla C_- \cdot\bm{u} )dx +\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_C_-) dx\\
% &&+\int_{\Omega} (\nabla\tilde{\mu}_{\phi}\phi \cdot\bm{u}+ \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi})+\int_{\Omega} \tilde{\mu}_{\phi} S|\nabla\phi|dx\nonumber\\
&=& \int_{\Omega}(RT\zeta_+\nabla  C_+ \cdot\bm{u} +RT\zeta_-\nabla C_- \cdot\bm{u} )d\bm{x}  +\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_c^-) d\bm{x} \nonumber\\
&&+\int_{\Omega} (\nabla\tilde{\mu}_{\phi}\phi \cdot\bm{u}+ \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi}) d\bm{x}  +\int_{\Omega} \tilde{\mu}_{\phi} S_{\phi}|\nabla\phi|d\bm{x} \nonumber\\
&=& \int_{\Omega}(RT\zeta_+\nabla  C_+  +RT\zeta_-\nabla C_-  +\nabla\tilde{\mu}_{\phi}\phi)\cdot\bm{u}d\bm{x} \nonumber\\
&&+\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_c^-)d\bm{x}  +\int_{\Omega}   \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi}  d\bm{x} +\int_{\Omega} \tilde{\mu}_{\phi} S_{\phi}|\nabla\phi|d\bm{x}  \nonumber\\
&=& \int_{\Omega}(-(RT  \frac{\partial \zeta_+}{\partial \phi}   C_+  + RT\frac{\partial \zeta_-}{\partial \phi} C_-)-\tilde{\mu}_{\phi} )\nabla\phi\cdot\bm{u}d\bm{x}  +\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_c^-)d\bm{x} \nonumber \\
&&+\int_{\Omega}   \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi}  dx +\int_{\Omega} \tilde{\mu}_{\phi} S_{\phi}|\nabla\phi|d\bm{x}  \nonumber\\
&=& -\int_{\Omega}\mu_{\phi}\nabla\phi\cdot\bm{u}d\bm{x}  +\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_c^-) d\bm{x} \\
&&+\int_{\Omega}   \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi}  d\bm{x} +\int_{\Omega} \tilde{\mu}_{\phi} S_{\phi}|\nabla\phi|d\bm{x}   \nonumber\\ 
&=&  \int_{\Omega} -\lambda  l^2 (\nabla\phi\otimes\nabla\phi):\nabla\bm{u}d\bm{x}  +\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_c^-) d\bm{x} +\int_{\Omega}   \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi}  d\bm{x}   +\int_{\Omega} \tilde{\mu}_{\phi} S_{\phi}|\nabla\phi|d\bm{x} \nonumber 
\end{eqnarray}

In summary, we have 
\begin{align*}
&\frac{dE}{dt} \\
=&   -\int_{\Omega}\nabla\bm{u}:(\bm\sigma_{\eta}+\bm\sigma_{\phi})d\x
-\int_{\Omega}p\nabla\cdot\bm{u}d\x  - \int_{\Omega} \lambda l^2 (\nabla\phi\otimes\nabla\phi):\nabla\bm{u}d\x +\int_{\Omega} (\zeta_+\bm{J}_+\cdot\nabla\mu_c^++\zeta_-\bm{J}_-\cdot\nabla\mu_c^-)d\x \\
& +\int_{\Omega}   \bm{J}_{\phi}\cdot\nabla\tilde{\mu}_{\phi}  d\x+\int_{\Omega} \tilde{\mu}_{\phi} S_{\phi}|\nabla\phi|d\x  \\
=&-\Delta.  
\end{align*}

