\section{Instance Dividing Assignment Algorithm}
In this section, we present an approximation algorithm for $\mathbf{P}$, named the Instance Dividing Assignment Algorithm ($\mathtt{IDAssign}$), which leverages a local ratio framework combined with an instance-dividing technique. Later in this section, we formally prove that $\mathtt{IDAssign}$ achieves a $\frac{1}{6}$-approximation ratio for $\mathbf{P}$. To the best of our knowledge, $\mathtt{IDAssign}$ is the first algorithm that provides a constant approximation ratio for DOAP.

The detailed steps of $\mathtt{IDAssign}$ are outlined in Algorithm \ref{alg:divide}. For each assignment instance $\ell$, let $\tilde{b}_\ell = \frac{b_\ell}{B_\ell}$ and $\tilde{c}_\ell = \frac{c_\ell}{C_\ell}$ represent the normalized bandwidth and computation resource allocation, respectively. We classify an assignment instance $\ell$ as a \textit{light instance} if $\tilde{b}_\ell \le \frac{1}{2}$ and $\tilde{c}_\ell \le \frac{1}{2}$, and as a \textit{heavy instance} otherwise. Let $\mathcal{L}_L$ denote the set of all light instances in $\mathcal{L}$, and $\mathcal{L}_H$ the set of all heavy instances in $\mathcal{L}$. The algorithm is then recursively called with the initial invocation $\mathtt{IDAssign}(\mathbf{u}, \mathcal{L})$, where $\mathbf{u}$ is a vector containing the utility values $u(\ell)$ for all $\ell \in \mathcal{L}$. Since the utility of each assignment instance is updated at each recursive layer, we denote the updated utility of $\ell$ at the $i$-th recursive layer as $w^i(\ell)$, where $u(\ell)$ represents the initial utility of $\ell$. 

%In the following, we prove the approximation ratio of $\mathtt{IDAssign}$ for $\mathbf{P}$.

In each recursive layer $i$, the algorithm selects an instance $\ell^i$ with the smallest $\max\{\tilde{b}_{\ell^i}, \tilde{c}_{\ell^i}\}$, prioritizing instances in $\mathcal{L}_L$ over those in $\mathcal{L}_H$ (line $4$). The utility value $w^i(\ell)$ for each assignment instance $\ell \in \mathcal{L}$ is then decomposed into two components, $w_1^i(\ell)$ and $w_2^i(\ell)$ (line $5$), where $w_2^i(\ell)$ represents the marginal gain corresponding to the choice of $\ell^i$. The marginal utility vector $\mathbf{w_2^i}$ becomes the utility vector $\mathbf{w^{i+1}}$ for the next recursive layer (line $6$). Based on the solution $\mathcal{S}^{i+1}$ returned from layer $(i+1)$, $\ell^i$ is added to the solution if it satisfies the feasibility constraints \eqref{eq:eop1}--\eqref{eq:eop3}. Next, we prove the approximation ratio of $\mathtt{IDAssign}$ for $\mathbf{P}$ as follows.

\begin{algorithm}[tb]
    \caption{\scalebox{1}{Instance Dividing Assignment Algorithm}}\label{alg:divide}

    \SetAlgoHangIndent{0pt} 
    \SetKwProg{Fn}{}{:}{}
    \SetKwInOut{Input}{input}
    \SetKwInOut{Output}{output}
    \SetKw{Return}{return}

    %Dividing set $\mathcal{L}$ into $\mathcal{L}_L$ and $\mathcal{L}_H$\;
    %\BlankLine
    \Fn{$\mathtt{IDAssign}$($\mathbf{w^i}$, $\mathcal{L}$)}{
    Remove all instances $\ell$ from $\mathcal{L}$ with $w^i(\ell) \le 0$\;
    \lIf{$\mathcal{L} = \emptyset$}{\Return $\mathcal{S}^i=\emptyset$}
    %Given $\mathcal{L} = \mathcal{L}_L \cup \mathcal{L}_H$,
    \leIf{$\mathcal{L}_L \neq \emptyset$}{$\ell^i \leftarrow \argmin_{\ell \in \mathcal{L}_L} (\max\{\tilde{b}_\ell, \tilde{c}_\ell\})$}{$\ell^i \leftarrow \argmin_{\ell \in \mathcal{L}_H} (\max\{\tilde{b}_\ell, \tilde{c}_\ell\})$}

    Decompose utility vector $\mathbf{w^i}$ into $\mathbf{w_1^i}$ and $\mathbf{w_2^i}$ (i.e., $\mathbf{w^i}=\mathbf{w_1^i}+\mathbf{w_2^i}$) such that for any $\ell \in \mathcal{L}$,
    \begin{equation*}
         w_1^i(\ell) = w^i(\ell^i) \cdot
        \begin{cases}
            1 & \text{if } \ell \in \mathcal{L}(\ell^i)\\
            (\tilde{b}_{\ell} + \tilde{c}_{\ell}) & \text{if }  \ell \in \mathcal{E}(\ell^i) \setminus \mathcal{L}(\ell^i)\\
            0 & \text{otherwise}
        \end{cases};
    \end{equation*}

    $\mathcal{S}^{i+1} \leftarrow $ $\mathtt{IDAssign}$($\mathbf{w_2^i}$, $\mathcal{L}$)\;
    \leIf{$\mathcal{S}^{i+1} \cup \{\ell^i\}$ is feasible}{\Return $\mathcal{S}^i \leftarrow \mathcal{S}^{i+1} \cup \{\ell^i\}$}{\Return $\mathcal{S}^i \leftarrow \mathcal{S}^{i+1}$}
    }
\end{algorithm}


\begin{theorem}\label{theorem:divide}
    \scalebox{0.97}{$\mathtt{IDAssign}$ is a $\frac{1}{6}$-approximation algorithm for $\mathbf{P}$.}
\end{theorem}
\begin{proof}
    Suppose $\mathcal{Q}$ is an optimal solution of $\mathbf{P}$.
    Let the innermost recursive layer of $\mathtt{IDAssign}$ be layer $I$, and the outermost be layer $1$. We use simple induction to prove this lemma by showing that $w^i(\mathcal{S}^i) \ge \frac{1}{6}w^i(\mathcal{Q})$ for $i=I, I-1, ..., 1$ (since $\mathbf{w^1} = \mathbf{u}$).

    \textbf{Base Case} ($i=I$): When $i=I$, $w^i(\ell) \le 0, \forall \ell \in \mathcal{L}$. The returned $\mathcal{S}^I = \emptyset$, so 
    $w^I(\mathcal{S}^I) = 0 \ge w^I(\mathcal{Q}) \ge \frac{1}{6}w^I(\mathcal{Q})$.

    \textbf{Inductive Step} ($i < I$): When $i < I$, suppose $w^{i+1}(\mathcal{S}^{i+1}) \ge \frac{1}{6}w^{i+1}(\mathcal{Q})$. Since $\mathbf{w_2^i} = \mathbf{w^{i+1}}$, $w_2^{i}(\mathcal{S}^{i+1}) \ge \frac{1}{6}w_2^{i}(\mathcal{Q})$. Based on the utility decomposition in line $5$, $w_1^i(\ell^i)=w^i(\ell^i)$, so $w_2^i(\ell^i)$$=$$0$; thus,
    \begin{equation}\label{eq:light1}
        {\textstyle w_2^{i}(\mathcal{S}^{i}) = w_2^{i}(\mathcal{S}^{i+1}) \ge \frac{1}{6}w_2^{i}(\mathcal{Q})}.
    \end{equation}
    In line $7$, if $\ell^i$ can be added to $\mathcal{S}^{i}$, $w_1^{i}(\mathcal{S}^{i}) \ge w^i(\ell^i)$. 
    Otherwise, either one $\ell \in \mathcal{L}(\ell^i)$ already exists in $\mathcal{S}^{i+1}$ that stops $\ell^i$ from being added to $\mathcal{S}^{i}$ (constraint \eqref{eq:eop3}) or the remaining resource in ES $m_{\ell^i}$ is not enough to accommodate $\ell^i$ (constraints \eqref{eq:eop1} and \eqref{eq:eop2}). In the former case, $w_1^{i}(\mathcal{S}^{i}) \ge w^i(\ell^i)$ due to line $5$. In the latter case, let $\mathcal{A}^{i} = \mathcal{S}^{i+1} \cap \mathcal{E}(\ell^i)$, representing the instances that have been selected in $\mathcal{S}^{i+1}$ and have resource contention with $\ell^i$. We consider the following two situations for the latter case: $\ell^i \in \mathcal{L}_H$ and $\ell^i \in \mathcal{L}_L$. If $\ell^i \in \mathcal{L}_H$, as we only consider instances in $\mathcal{L}_H$ when $\mathcal{L}_L=\emptyset$, the solution $\mathcal{S}^{i+1}$ contains only heavy instances; in this situation, there exists at least one heavy instance $\ell \in \mathcal{S}^{i+1}$ that prevents $\ell^i$ being added to the solution due to resource contention. Based on line $5$ and the definition of heavy instances, $w_1^{i}(\mathcal{S}^{i}) \ge \frac{1}{2}w^i(\ell^i)$. If $\ell^i \in \mathcal{L}_L$, either $\sum_{\ell \in \mathcal{A}^{i}}\tilde{b}_{\ell} \ge \frac{1}{2}$ or $\sum_{\ell \in \mathcal{A}^{i}}\tilde{c}_{\ell} \ge \frac{1}{2}$ (i.e., at least $\frac{1}{2}$ of $m_{\ell^i}$'s bandwidth or computation resource are allocated to $ \mathcal{S}^{i+1}$); thus, $w_1^{i}(\mathcal{S}^{i})  \ge \frac{1}{2}w^i(\ell^i)$ due to line $5$. 
    % \begin{itemize}
    %     \item If $\ell^i \in \mathcal{L}_H$, there must be at least one heavy instance $\ell \in \mathcal{L}_H$ has been added into $\mathcal{S}^{i+1}$ (we only consider instances in $\mathcal{L}_H$ when $\mathcal{L}_L=\emptyset$). Based on line $5$ and the definition of heavy instances, $w_1^{i}(\mathcal{S}^{i}) \ge \frac{1}{2}w^i(\ell^i)$.
    %     \item If $\ell^i \in \mathcal{L}_L$, either $\sum_{\ell \in \mathcal{A}^{i}}\tilde{b}_{\ell} \ge \frac{1}{2}$ or $\sum_{\ell \in \mathcal{A}^{i}}\tilde{c}_{\ell} \ge \frac{1}{2}$ (i.e., at least $\frac{1}{2}$ of $m_{\ell^i}$'s bandwidth or computation resource are allocated to $ \mathcal{S}^{i+1}$); thus, $w_1^{i}(\mathcal{S}^{i})  \ge \frac{1}{2}w^i(\ell^i)$ due to line $5$. 
    % \end{itemize}
    Therefore, if instance $\ell^i$ cannot be added to $\mathcal{S}^{i}$, we have $w_1^{i}(\mathcal{S}^{i}) \ge \frac{1}{2}w^i(\ell^i)$. 
    Besides, $w_1^i(\mathcal{Q})$ is maximized when $\mathcal{Q}$ contains one $ \ell \in \mathcal{L}(\ell^i) \setminus \mathcal{E}(\ell^i)$ and all resources of ES $m_{\ell^i}$ has been allocated to $\ell' \in \mathcal{Q} \cap \mathcal{E}(\ell^i) \setminus \mathcal{L}(\ell^i)$; in this case, $w_1^i(\mathcal{Q}) = w^i(\ell^i) + 2w^i(\ell^i) = 3w^i(\ell^i).$
    % \begin{equation*}
    %     w_1^i(\mathcal{Q}_L) = w^i(\ell^i) + 4w^i(\ell^i) = 5w^i(\ell^i).
    % \end{equation*}
    Hence, we have 
    \begin{equation}\label{eq:light2}
        w_1^{i}(\mathcal{S}^{i}) \ge \frac{1}{6}w_1^i(\mathcal{Q}).
    \end{equation}
    Given Eq. \eqref{eq:light1}, Eq. \eqref{eq:light2}, and $\mathbf{w^i}=\mathbf{w_1^i}+\mathbf{w_2^i}$, we have $w^{i}(\mathcal{S}^{i}) \ge \frac{1}{6}w^i(\mathcal{Q})$. Based on simple induction, $w^{i}(\mathcal{S}^{i}) \ge \frac{1}{6}w^i(\mathcal{Q})$ for $i = I, ..., 1$.
\end{proof}

\textit{Time Complexity.} Since $\mathcal{L}$ contains at most $NMBC$ assignment instances, $\mathtt{IDAssign}$ has at most $NMBC$ recursive layers. In line $5$, at most $NMBC$ assignment instances are considered for utility decomposition. Thus, the time complexity of $\mathtt{IDAssign}$ is $\mathcal{O}((NMBC)^2)$.


