    \centering
    \includegraphics[width=0.9\linewidth, page=1]{figures/experiment_result.pdf}
    \caption{Performance ratios of algorithms under different resource utilization range combinations ($ru_b, ru_c$)}
    \label{fig:exp1}
    \Description{performances of all algorithms under different resource utilization}
