\subsection{Notations}
We use uppercase letters to represent matrices and lowercase bold letters to represent vectors\cite{ref17}. We denote the $(i,j)$ entry of a matrix $\boldsymbol{A}$ with $A_{ij}$. We denote a graph $G=\left\{ N,E \right\} $ consisting of $n$ nodes $N=\left\{ n_1,n_2,....,n_n \right\} $ and $l$ edges $E\subseteq N\times N$, where $\left( n_i.n_j \right) \in E$ captures the existence of a link from node $n_i$ to node $n_j$. A graph is connected if an undirected path exists between all pairs of nodes, where each edge $(n_i,n_j)$ is associated with a non-negative weight $w_{ij}\geq 0$. The neighborhood $\mathcal{N}_i$ of node $n_i$ is defined as the set of adjacent nodes ${n_j|(n_i,n_j) \in E }$. The weighted Laplacian matrix $\boldsymbol{L}$ is then defined with off-diagonal entries $L _{ij}=-w_{ij}$ when $\left( n_i.n_j \right) \in E$, zero otherwise, while its diagonal entries satisfy $L_{ij}=\sum_{i\ne j}{w_{ij}}$ to ensure the zero-row-sum property.
\subsection{Control Barrier Function}
\par We consider the following control affine system: 
\begin{equation}
\dot{\boldsymbol{x}}=f\left( \boldsymbol{x} \right) +g\left( \boldsymbol{x} \right) \boldsymbol{u}
\end{equation}
\par \par where state $\boldsymbol{x}\in \mathbb{R} ^n$, input $\boldsymbol{u}\in \mathbb{R} ^m$, and Lipschitz continuous dynamics $f: \mathcal{D}\rightarrow \mathbb{R} ^n$ and $g:\mathcal{D} \rightarrow \mathbb{R} ^{n\times m}$.
\par \textbf{Definition 3.1} \cite{ref18} We define a set $\mathcal{C}$ for the system (1). Let $\mathcal{C}$ be forward invariant, if $\boldsymbol{x_0}\in \mathcal{C}$ implies that $\boldsymbol{x}\in \mathcal{C}$ for all $k\in \mathcal{T}$. Therefore, we call the system (1) safe with the set $\mathcal{C}$.
\par \textbf{Definition 3.2} \cite{ref18} A set $\mathcal{C} \in \mathcal{D}$ is a 0-superlevel set of a continuously differentiable function $h:\mathcal{D} \rightarrow \mathbb{R} $ when
\begin{subequations}
\begin{align}
\mathcal{C} &= \left\{ \boldsymbol{x} \in \mathcal{D} : h\left( \boldsymbol{x} \right) \geqslant 0 \right\}  \\
\partial \mathcal{C} &= \left\{ \boldsymbol{x} \in \mathcal{D} : h\left( \boldsymbol{x} \right) = 0 \right\}  \\
\mathrm{Int}\,\mathcal{C} &= \left\{ \boldsymbol{x} \in \mathcal{D} : h\left( \boldsymbol{x} \right) > 0 \right\} 
\end{align}
\end{subequations}
\par \textbf{Definition 3.3} \cite{ref18} Let $\mathcal{C} =\left\{ \boldsymbol{x}\in \mathbb{R} ^n|h\left( \boldsymbol{x} \right) \geq 0 \right\}$ express as the 0-superlevel set of a continuous function $h:\mathbb{R}^n\rightarrow \mathbb{R} ^n$. The function $h$ is a control barrier function (CBF) for (1) on $\mathcal{C}$ if there exists an $\alpha \in \left[ 0,1 \right] $ for each $\boldsymbol{x}\in \mathbb{R} ^n$, there exists $\boldsymbol{u}\in \mathbb{R} ^n$ such that:
\begin{equation}
h\left( \boldsymbol{x} \right) \geq \alpha h\left( \boldsymbol{x} \right) 
\end{equation}
