\begin{algorithm}
\caption{Distributed Model Predictive Control for Vehicle Platooning}
\begin{algorithmic}
    \State \textbf{Input:} 
    \begin{itemize}
        \item Initialization state $x_0$
        \item Maximum calculation times $CalMax$
        \item Vehicle constraints of $u,v,p$
    \end{itemize}
    \State \textbf{Output:} Pareto-optimal solutions $u^*$
    \State \textbf{Initialization of the leader vehicle} $k = 0$: \textbf{for} $i \in N$ \textbf{do}
    \State a) Prearrange $x_i(0)$ and $u_i(0)$:
    \[
    x_i(0) = 
    \begin{cases} 
    x_i(0), & k = 0, \\
    A x_i(k-1) + F u_i(k-1), & k \in K. 
    \end{cases}
    \]
    \[
    u_i(0) \in U_i, \quad k \in K.
    \]

    \State \textbf{Online Phase at following vehicle} $k \geq 0$: \textbf{for} $i \in N$ \textbf{do}
    \State a) Convey $x_i(k)$ to vehicles $j \in N$;
    \State b) Receive $x_j(k)$ from vehicles $j \in N$;
    \State c) Resolve the probability using Markov states, then attain $u_i^*(k)$ and $x_i^*(k)$;
    \State d) Resolve the probability of $\delta_{ij}$, determine whether neighbor states are successfully acquired;
    \State e) Take $u_i^*(0)$ for the control of vehicle $i$;
    \State f) Prearrange $x_i^*(k+1)$ and $u_i^*(k+1)$:
    \[
    x_i^*(k+1) =
    \begin{cases} 
    x_i^*(k), \text{if vehicle failed}, \\
    A x_i(k) + F u_i(k) + \delta_{ij}(k) \cdot (x_j(k) - x_i(k)),  \\ 
    \text{if vehicle succeeded}.
    \end{cases}
    \]
    \[
    u_i^*(k+1) =
    \begin{cases} 
    u_i^*(k),  \text{if vehicle failed}, \\
    \sum_{j \in N} \delta_{ij}(k) \left( x_j(k) - x_i(k) - \Delta p_{j,i} \right), \\
    \text{if vehicle succeeded}.
    \end{cases}
    \]

    \State \textbf{Iteration at } $t \geq 0$: \textbf{for} $i \in N$,
    \State \quad a) Set initial solution and candidates:
    \[
    \mathrm{solution}_i(0) \gets \emptyset, \quad \mathrm{candidates}_i(0) \gets \text{getInitialCandidates}()
    \]
    \State \quad b) Select candidate with maximum value:
    \[
    u^*_i(t) \gets \underset{c \in \mathrm{candidates}_i(t)}{\arg\max} \, J(c)
    \]

    \State \quad c) Update solution if feasible:
    \begin{align*}
    \mathrm{solution}_i(t+1) \gets 
    \begin{cases}
    \mathrm{solution}_i(t) \cup \{u^*_i(t)\} \\ \text{if } \mathrm{isFeasible}(u^*_i(t)), \\
    \mathrm{solution}_i(t),  \text{otherwise}.
    \end{cases}
    \end{align*}

    \State \quad d) Prune candidates:
    \begin{align*}
    \mathrm{candidates}_i(t+1) \gets 
    \begin{cases}
    \mathrm{candidates}_i(t) \setminus \{u^*_i(t)\} \\ \text{if } \mathrm{isFeasible}(u^*_i(t)), \\
    \mathrm{candidates}_i(t),  \text{otherwise}.
    \end{cases}
    \end{align*}

    \State \quad e) Check termination:
    \[
    \text{If } \mathrm{isTerminal}(\mathrm{solution}_i(t+1)) \text{, return } \mathrm{solution}_i(t+1).
    \]

\end{algorithmic}
\end{algorithm}

