\begin{algorithm}
\caption{NSGA-II for Multi-Objective Optimization}
\begin{algorithmic} % 关键修改：[0]表示禁用行号
\State \textbf{Input:} 
    \begin{itemize}
        \item Population size $N$
        \item Maximum generations $GenMax$
        \item The maximum solution of $J(u^*)$
    \end{itemize}
\State \textbf{Output:} Pareto-optimal solutions $y^*$

% \State Initialize population $P_0$ with $N$ individuals parents $y^{gk}_l$
% \State Evaluate objectives by (25) for each individual
% \State Perform non-dominated sort on $Y_0=\left\{ y_{l}^{gk}=0|k\in K,l\in L,g\in \left\{ 0,1,2,...,\varTheta \right\} \right\}$ to assign ranks
% \State Compute crowding distance for diversity preservation to reduced to one-fourth of $Y_0=\left\{ y_{l}^{gk}=0|k\in K,l\in L,g\in \left\{ 0,1,2,...,\varTheta \right\} \right\}$

\For{$t \gets 1$ to $GenMax$}
    % \State \textbf{Reproduction:}
    % \State Select parents using binary tournament selection
    % \State Apply simulated binary crossover (SBX) with probability $p_c$
    % \State Apply polynomial mutation with probability $p_m$
    % \State Source node and destination node

    % \State \textbf{Evaluation:}
    % \For{each offspring $y(u,v,p)$ in $Y^{'}=\left\{ y_{l}^{gk}(t)|k\in K,l\in L,g\in \left\{ 0,1,2,...,\varTheta \right\} \right\}$}
    %     \State Compute $Y(u^*,v^*,p^*) \gets max Y(u,v,p)$ in (25)\Comment{Maximization objective}
    %     \State Compute $J(u^*) \gets max -J(u)$ in (25)\Comment{Minimization transformed}
    %     \State \textbf{Check constraints:}
    %     \If{any of $u$, $v$, $p$ violated}
    %         \State Assign penalty fitness values
    %     \EndIf
    % \EndFor

    % \State Combine parent and offspring populations $Y_t=Y_t \cup Y^{'}_t$
    % \State Perform non-dominated sort on combined population
    % \State Select new population $Y_{t+1}$ based on ranks and crowding distance
    \State \textbf{Initialization at } $t = 0$:
\State \quad a) Generate initial population:
\[
\mathcal{Y}_t(i) \gets \text{randomIndividual}(), \quad \mathcal{Y}^{'}_t \gets \emptyset
\]
\State \quad b) Evaluate the first objective and constraints:
\[
\max_{u,v,p} \quad -J(u) , \quad \forall u \in U
\]
\State \quad c) Evaluate the second objective and constraints:
\[
\max_{u,v,p} \quad Y(y^{gk}_l) , \quad \forall k \in K, l \in L, g\in \left\{ 0,1,2,...,\varTheta \right\}
\]
\State \textbf{Generational loop at } $t \geq 0$:
\State \quad a) Combine populations:
\[
\mathcal{Y}_t \gets \mathcal{Y}_t \cup \mathcal{Y}^{'}_t
\]
\State \quad b) Non-dominated sorting:
\[
(y^{gk}_{l_1}, y^{gk}_{l_2}, \dots) \gets \text{sortNonDominated}(\mathcal{Y}_t)
\]
\State \quad c) Crowding distance calculation with the first objective:
\begin{itemize}
    \item $\text{Distance}(x) \gets \sum_{k=1}^m \frac{Y(y^{gk}_{l_i}) - Y(y^{gk}_{l_{i+1}})}{Y^{\max} - Y^{\min}}$
    \item $\forall k, l, g$
\end{itemize}
\State \quad d) Crowding distance calculation with joint objective:
\begin{itemize}
    \item $\text{DISTANCE}(x) \gets \sum_{k=1}^m \frac{-J(u_i) + J(u_{i+1})}{(-J^{\max}) - (-J^{\min})}$
    \item $\forall u \in U$
\end{itemize}
\State \quad e) Crowding distance calculation with the second objective:
\[
\text{distance}(x) \gets \text{Distance}(x)-\text{DISTANCE}(x), 
\]
\State \quad f) Population selection:
\[
\mathcal{Y}_{t+1} \gets \bigcup_{i=1}^{l} y^{gk}_{l_i} \quad \text{until } |\mathcal{Y}_{t+1}| + |\mathcal{Y}_{l+1}^{'}| > N
\]
\State \quad g) Generate offspring:
\[
\mathcal{Y}_{t+1}^{'} \gets \text{tournamentSelect}(\mathcal{Y}_{t+1}) \oplus \text{adaptive crossover/mutation}
\]
\State \quad h) Termination:
\[
\text{If } t+1 = GernMax \text{, return } \text{ParetoFront}(\mathcal{Y}_t).
\]
\EndFor
\end{algorithmic}
\end{algorithm}

