To construct a labeled meta-model training set, we leverage the concordance concept from survival analysis in the medical domain \cite{harrell1982evaluating} and pairwise ranking idea in information retrieval domain \cite{liu2009learning}. The core idea in medical language is that a patient living shorter should have a lower survival probability at any given time compared to a patient living longer. Therefore, the uncertainty in a survival model’s predictions can be quantified by evaluating its ability to correctly rank the survival probabilities of samples relative to each other.

Intuitively, comparing a sample against some referenced points enhances the quality of the quantified uncertainty. For efficiency consideration, we design an anchor-based learning strategy. Following the literature we assume that censoring occurs completely at random \cite{deephit, dsm}. Specifically, we randomly select $K$ uncensored samples from the survival model training set $\mathcal{D}$ as anchors, denoted by $\mathcal{D}^{A}\!\!=\!\!\{(\bm{x}^A_k,t^A_k, \delta^A_k\!\!=\!\!1)\}^K_{k=1}$. For the $j$-th uncensored sample $(\bm{x}_j, t_j, \delta_j=1)\in\mathcal{D}$, we treat it as a training instance for the meta-model, and calculate its uncertainty label as follows:
\begin{align}
y^\text{meta}_{j}=\frac{\sum^K_{k=1}\boldsymbol{\mathbbm{1}}\!\left(t_j<t^A_k,S\left(t_j|\bm{x}_j\right)\geq S\left(t_j|\bm{x}^A_k\right)\right)}{\sum^K_{k=1}\boldsymbol{\mathbbm{1}}\!\left(t_j<t^A_k\right)}, \label{eq:label}
\end{align}
which measures the proportion of incorrectly ordered pairs by the survival model $F(\cdot)$, resulting in an uncertainty score ranging from 0 to 1 for the predicted sample. A higher uncertainty score indicates a less reliable prediction. Here $\boldsymbol{\mathbbm{1}}\!(\cdot)$ is an indicator function that returns 1 if the specified conditions are met and 0 otherwise. $S(t_j|\bm{x}_j)$ and $S(t_j|\bm{x}^A_k)$ denote the survival probabilities estimated by $F(\cdot)$ for samples with covariates $\bm{x}_j$ and $\bm{x}^A_k$ at time $t_j$, respectively. As a result, we construct the meta-model training set $\mathcal{D}^\text{meta}=\{(\bm{x}_j, y^\text{meta}_j)\}_{j=1}^{N^{\prime}}$ with $N^\prime$ labeled samples. 

Based on the constructed meta-model training set $\mathcal{D}^{\text{meta}}$, we explore two different architectures of the meta-model $U(\cdot)$ with sample covariates as input, including a multi-layer perceptron (MLP) model and a random forest model, referred to as \textbf{SurvUnc-MLP} and \textbf{SurvUnc-RF}, respectively. After training on $\mathcal{D}^\text{meta}$, the trained SurvUnc models provide uncertainty scores for the predictions from the corresponding survival model. Algorithm~\ref{alg:framework} summarizes the learning procedure of SurvUnc. Note that during inference, the event or censoring time for a test sample is unknown, requiring the meta-model $U(\cdot)$ to estimate predictive uncertainty solely from the covariates.

\SetKwInput{KwInit}{Init}
\SetKwInput{KwUse}{Usage}
\begin{algorithm}[tbp] 
    \caption{The learning procedure of SurvUnc}\label{alg:framework}
    \KwIn{\RaggedRight{Survival data $\mathcal{D}=\{(\bm{x}_i, t_i, \delta_i)\}^N_{i=1}$;\\ 
    \hspace{3em}Pretrained survival model $F(\cdot)$; Anchor number $K$}}
    \KwOut{Uncertainty quantification model $U(\cdot)$}

    Randomly sample $K$ anchors from $\mathcal{D}$, i.e., $\mathcal{D}^{A}$

    Initialize the model $U(\cdot)$

    $\mathcal{D}^{\text{meta}}\leftarrow\emptyset$

    \For{$(\bm{x}_j, t_j,\delta_j=1)\in\mathcal{D}$}{
        Obtain label $y_i^\text{meta}$ based on \eqref{eq:label} and $\mathcal{D}^{A}$\\
        $\mathcal{D}^\text{meta}\leftarrow \mathcal{D}^\text{meta} \cup \{(\bm{x}_i, y^\text{meta}_i)\}$
    }
    Train the model $U(\cdot)$ with $\mathcal{D}^{\text{meta}}$ \\
    \KwUse{$u_i = U(\bm{x}_{i})$}
\end{algorithm}



\section{Experiments}\label{sec:exp}
In this section, we show that our proposed SurvUnc framework effectively quantifies uncertainty in survival models and is applicable in different scenarios. Specifically, we conduct experiments to answer the following questions:
\begin{itemize}[leftmargin=10px]
\item \textbf{RQ1:} How does SurvUnc perform w.r.t. total uncertainty quantification, particularly in distinguishing between correctly and incorrectly predicted samples, compared to existing methods?
\item \textbf{RQ2:} How does SurvUnc perform w.r.t. epistemic uncertainty quantification, particularly in detecting OOD data, when compared to existing methods?
\item \textbf{RQ3:} How do different hyperparameter settings, such as meta-model structure and the number of anchors, affect the performance of SurvUnc?
\end{itemize}

\subsection{Experimental Settings}\label{sec:exp_settings}
\subsubsection{Datasets.}
We experiment with three real-world and one synthetic, publicly available survival analysis datasets:
\begin{itemize}[leftmargin=10px]
    \item \textbf{FLCHAIN} is a study of the relationship between free light chains and mortality in an elderly population \cite{flchain}.
    \item \textbf{SUPPORT} contains a dataset that aims to improve the care for seriously ill patients by understanding their prognosis and treatment preferences \cite{support}.
    \item \textbf{SEER-BC} is derived from the SEER database \cite{seer}, which contains survival information for oncology patients in the U.S. Following the processing steps in \cite{wang2022survtrace}, we select breast cancer patients to create the SEER-BC dataset. For the later OOD detection experiments, we curate a SEER-HD dataset, comprising the same number of patients as SEER-BC but diagnosed with heart disease.
    \item \textbf{SAC3} is a synthetic dataset from \cite{kvamme2021continuous}, which simulates survival times by sampling from a combination of three hazard functions. Thus, this dataset provides the ground-truth survival curves.
\end{itemize} 
Table~\ref{tab:dataset} presents the basic statistics of all datasets. For the SUPPORT dataset, we retain the original training/test split and reserve 20\% of the training set for validation. For all other datasets, we randomly split into training, validation, and test sets in a ratio of 6:2:2. 

\subsubsection{Survival Models.} To evaluate the effectiveness as well as robustness of our proposed SurvUnc framework on survival models, we select five representative survival models for uncertainty quantification, including three deep learning models of \textbf{DeepSurv} \cite{deepsurv}, \textbf{DeepHit} \cite{deephit}, \textbf{DSM} \cite{dsm}, one machine learning model of \textbf{RSF} \cite{rsf}, and one Bayesian-based model of \textbf{BNNSurv} \cite{lillelund2023uncertainty}. For each survival model, we optimize hyperparameters so that the reported performance on datasets is comparable to those published in the literature, thereby validating the correctness of pretrained survival models. 

\subsubsection{Uncertainty Quantification Baselines.} Given the lack of prior studies on model-agnostic uncertainty quantification for survival models, we adapt two widely used uncertainty quantification methods of \textbf{MC-Dropout} \cite{mcdropout} and \textbf{Deep Ensembles (Ensemble)} \cite{ensemble} to survival analysis. For MC-Dropout, we set the number of forward passes to 100. For Ensemble, we train 10 survival models with different random initializations. Note that the RSF model does not support the dropout mechanism, making MC-Dropout incompatible with it. Unlike MC-Dropout and Ensemble, which are general uncertainty quantification methods applicable across models, {BNNSurv} is a specialized Bayesian survival model that inherently estimates uncertainty but cannot be integrated with other survival models for uncertainty quantification.

\subsubsection{Tasks \& Metrics.}
As discussed before, standardized evaluation protocols for uncertainty quantification methods with survival models remain lacking. To address this, we extend existing evaluation methodologies from uncertainty quantification studies to the survival analysis domain, incorporating multiple tasks and metrics.

\textbf{Selective prediction} evaluates how well an uncertainty quantification method differentiates between correct and incorrect predictions. A good uncertainty quantification method should improve survival model performance by selectively discarding samples with high uncertainty. To evaluate this, we use two widely adopted survival analysis metrics.
\begin{itemize}[leftmargin=10px]
    \item \textbf{Time Dependent Concordance Index ($C^{\text{td}}$).} This metric measures the model discrimination power by comparing the relative survival probabilities across all pairs of samples in the test set \cite{antolini2005time}, defined as 
    \begin{align}
    C^{\text{td}}=\frac{\sum_{i=1}^n\sum_{j=1}^n\delta_i\cdot \boldsymbol{\mathbbm{1}}\!\left(t_i<t_j, S(t_i|\bm{x}_i)<S(t_i|\bm{x}_j)\right)}{\sum_{i=1}^n\sum_{j=1}^n\delta_i\cdot \boldsymbol{\mathbbm{1}}\!\left(t_i<t_j\right)}. \nonumber
    \end{align}
The range of $C^{\text{td}}$ is [0, 1], and a larger value indicates better model prediction. $C^{\text{td}}$=0.5 corresponds to a random prediction.

\item \textbf{Integral Brier Score (IBS).} This metric is an integral of the Brier score at all time points, while the Brier score calculates the mean squared error between predicted survival probability and binary observation at a given time \cite{kvamme2023brier}, defined as 
    \begin{align}
    BS(t)\!=\!\frac{1}{n}\!\sum^n_{i=1}[\frac{(0-S(t|\bm{x}_i))^2\cdot\!\!\boldsymbol{\mathbbm{1}}\!({t\!\geq\! t_i, \delta_i=1})}{\hat{G}(t_i)}\!+\!\frac{(1-S(t|\bm{x}_i))^2\!\cdot\!\boldsymbol{\mathbbm{1}}\!(t\!<\!t_i)}{\hat{{G}}(t)}], \nonumber
    \end{align}
where $\hat{G}(t)$ is the censoring survival function using Kaplan-Meier estimator \cite{kaplan1958nonparametric}. Unlike $C^{\text{td}}$, which relies on pairwise comparisons, IBS assesses each sample independently and provides an overall measure of model accuracy, where lower values indicate better performance. The range of IBS is [0, 1].
\end{itemize}

\textbf{Misprediction detection} examines whether uncertainty estimates align with actual prediction errors. To assess this, we use the following metric:
\begin{itemize}[leftmargin=10px]
    \item \textbf{Pearson Correlation Coefficient $\rho$.} This metric measures the linear correlation between the quantified uncertainty scores and IBSs of test samples, i.e., to evaluate whether the uncertainty quantification method can distinguish correctly and incorrectly predicted samples by survival models. The range of $\rho$ is [-1, 1], while we expect a positive correlation ($\rho\geq0$) here, i.e., samples with larger uncertainty have larger IBS.
\end{itemize}

\textbf{OOD detection} evaluates the ability of uncertainty quantification methods to distinguish in-distribution (IND) from OOD samples. We use the following two metrics:
\begin{itemize}[leftmargin=10px]
    \item \textbf{AUROC and AUPRC.} We adopt the area under the receiver operating curve (AUROC) and the area under the precision-recall curve (AUPRC) to evaluate the performance in OOD detection experiments. Specifically, IND test samples are labeled as the negative class, while OOD samples are labeled as the positive class \cite{Shen2023}. Both metrics are in the range of [0, 1], and a higher value indicates better performance.
\end{itemize}


