\section{Population Dynamics of NSGA-III on OJZJ}
In this section we investigate the population dynamics of the steady state \nsgaIII on $d$-\OJZJ and demonstrate that, in an expected linear number of generations, the population is evenly distributed across a subset $V \subset F^*$ already covered by $P_t$. Furthermore, if the population $P_t$ is Pareto optimal in generation $t$ and all future ones, the distribution can be even more characterized by bounding the cover number of every $v \in F^*$ by $\lceil{\mu/|V|}\rceil$ from above. Notably, for $|V| = |F^*|$, this is the best possible distribution of $P_t$ across the whole Pareto front one can achieve. We also demonstrate that once such a distribution is reached, it is maintained for all future generations.
%The key tool for the proof is Lemma~\ref{lem:even-cover}. 

\begin{lemma}
\label{lem:sparsity}
    Assume the same conditions as in Lemma~\ref{lem:Reference-Points} where stochastic population update is disabled. Suppose
    $\mu \in 2^{O(n)}$. Let $V \subset F^*$ be covered by $P_t$. The following properties are satisfied after $O(n)$ generations and all future ones with probability at least $1-e^{-\Omega(n)}$ and in expectation.
    \begin{itemize}
        \item[(1)] 
        For all $v \in V$ we have $c_t(v) \geq \beta:=\lfloor{\mu/(2n/d+1)^{d/2}}\rfloor$. 
        \item[(2)]
        If all populations $P_0,P_1, \ldots$ consist only of Pareto optimal individuals, we have that $c_t(v) \leq \lceil{\mu / |V|}\rceil$.
    \end{itemize}
\end{lemma}

\begin{proof}
    (1): Fix a Pareto optimal $x$ with $v:=f(x) \in V$. We show that $c_t(v) \geq \beta$ with probability at least $1-e^{-\Omega(n)}$ after $O(n)$ generations. By Lemma~\ref{lem:even-cover}(1), $c_t(v) \leq \beta$ cannot decrease since a maximum set of mutually incomparable solutions $I$ fulfills $|I| \leq (2n/d+1)^{d/2}$ and hence, $c_t(v) \leq \beta \leq \mu/|I|$. We define two phases where the second phase only applies if $\beta>n$.\\
    \textbf{Phase 1:} We have $c_t(v) \geq \ell:=\min\{\beta,n\}$.\\
    \textbf{Phase 2:} We have $c_t(v) \geq \beta$.\\
    In the next lemma we determine the expected duration of each phase under the assumptions of Lemma~\ref{lem:sparsity}.
    \begin{lemma}
    \label{lem:phases}
        Both phases are finished in $O(n)$ generations with probability at least $1-e^{-\Omega(n)}$ and in expectation.    
    \end{lemma}
	\begin{proof}
		We consider both phases separately.\\
		\textbf{Phase 1}: For $j \in [\ell-1]$ let $X_j$ be a random variable that counts the number of generations with $c_t=j$. Then the number of generations until the cover number of $v$ is at least $\ell$ is at most $X:=\sum_{j=1}^{\ell-1} X_j$. Note that $c_t$ can be increased by choosing an individual $y$ with $f(x)=f(y)$ as parent and flipping no bits (prob. $1/\mu \cdot (1-1/n)^n \geq 1/(4 \mu)=:\sigma_t$). Hence, the probability of increasing $c_t$ in one generation is at least 
		$$1-(1-\sigma_t)^{\mu} \geq \frac{\sigma_t \mu}{1+\sigma_t \mu} = \frac{1/4}{1+1/4} = \frac{1}{5}$$
		where the first inequality is due to Lemma~10 in~\citep{Badkobeh2015}. 
		%Hence, the expected number of generations until $d_t$ is increased is at most $1+4/(1-p_c)$ and therefore, at most $n+4n/(1-p_c)$ until $d_t=\min\{\ell,n\}$ is $n+4n/(1-p_c)$.   
		Hence, $X$ is stochastically dominated by a independent sum $Z:=\sum_{j=1}^{\ell-1}Z_j$ of geometrically distributed random variables $Z_j$ with success probability $1/5$. 
		%At first we estimate the time until $d_t=\min\{\ell,n\}$. So let $Z:=\sum_{j = 1}^{\min\{\ell,n\}} Z_j$. Then $E[Z] \leq 8 n/(1-p_c)$ and hence by Theorem~15 in~\citep{DOERR2019115} we obtain for $d:= \sum_{i=1}^{\min\{\ell,n\}} \frac{1}{\beta_j^2} \leq (1-p_c)^2\ell/64$, $\beta:=\beta_j$ and $\lambda \geq 0$
		Then $E[X] \leq E[Z] \leq 5\ell \leq 5n$ and hence by Theorem~15 in~\citep{DOERR2019115} we obtain for $d:= 25\ell$, and $\lambda \geq 0$
		\[
		P(Z \geq E[Z] + \lambda) \leq \exp\left(-\frac{1}{4} \min\left\{\frac{\lambda^2}{d}, \frac{\lambda}{5} \right\}\right)
		\]
		and for $\lambda=n$ we obtain $P(X \geq 6n) \leq P(X \geq  5\ell + n) \leq  P(Z \geq E[Z] + n) = e^{-\Omega(n)}$.\\
		\textbf{Phase 2:} We can assume that $\beta > n$. Let $Y_t$ be the number of individuals $x$ with $f(x)=v$. Denote by $N_t$ the number of new created individuals of this form. Then $E[N_t] \geq Y_t/4$ since in one trial such an individual is cloned with probability at least $n/(4 \mu)$ (with prob. at least $n/\mu$ one such individual is selected as parent and no bit is changed with prob. $(1-1/n)^n \geq 1/4$ during mutation) and a generation consists of $\mu$ trials. By a classical Chernoff bound $P(N_t \leq 2E[N_t]/3) = e^{-\Omega(Y_t)} = e^{-\Omega(n)}$. Hence, with probability $1-e^{-\Omega(n)}$ we have that $Y_{t+1} \geq \min\{Y_t+Y_t/6,\beta\} = \min\{7Y_t/6,\beta\}$ or, in other words, $Y_t$ increases by a factor of at least $7/6$ if the value $\beta$ is not reached. Note that at most $O(n)$ such generations in a row are sufficient to obtain a cover number of $v$ of at least $\beta$ (since $(7n/6)^n > \mu > \beta$), and this occurs with probability at least $1-e^{-\Omega(n)}$ by a union bound.
	\end{proof}
    Now we obtain by a union bound on both phases and every $v \in V$ that in $O(n)$ generations the cover number of every $v \in V$ is at least $\beta$ with probability at least $1-e^{-\Omega(n)}$ (since $|V|=O(n^{d/2}) = e^{o(n)}$). The bound on the expected number of generations follows by applying the same arguments for an additional period of $O(n)$ generations and by the fact that $(1+o(1))O(n) = O(n)$ such periods are sufficient.\\
    (2): %Fix a Pareto optimal $x$ with $v:=f(x) \in V$ and let $b_t$ be the cover number of $v$. 
    With the same argument as in (1) we obtain with probability $1-e^{-\Omega(n)}$ that, after $O(n)$ generations, the cover number of all $v \in V$ is at least $\lceil{\mu/|V|}\rceil$ or one of these cover numbers has decreased at least one time when it was at most $\lceil{\mu/|V|}\rceil$. Suppose that the former happens. If $\lceil{\mu/|V|}\rceil>\mu/|V|$ we see that $\lceil{\mu/|V|}\rceil \cdot |V| > |V| \cdot \mu/|V| = \mu$, a contradiction. Hence, $\lceil{\mu/|V|}\rceil=\mu/|V|$ and all $\mu$ individuals are completely evenly distributed on $V$. If the latter happens, we see with Lemma~\ref{lem:even-cover}(2) that the cover number of all vectors $v \in F^*$ is at most $\lceil{\mu/|V|}\rceil$. 
    By Lemma~\ref{lem:even-cover}(3) the maximum cover number cannot increase, proving Lemma~\ref{lem:sparsity}.
