		% \dirk{the first inequality holds without the $+n^{-\delta}$ term if $2n/m + 1 \le n$, which is true if and only if $m \ge 4$. For $m=2$ it holds as well as then the exponent is $1$. Maybe add an explanation about this?  TO DO Dirk}$(2n/m+1)^{m/2} \cdot n^{-\delta} \leq n^{m/2} \cdot n^{-\delta} +n^{-\delta}\leq n^{-\delta + m/2}+n^{-\delta} = n^{m/2+1-c/4} + n^{1-c/4}$ 
		The bound on the expected number of generations follows by applying the same arguments for an additional period of $8dn\ln(n)$ generations and by the fact that $1+o(1)$ such periods are sufficient. %Note that in $cn\ln(n)$ generations the algorithm makes $cn \ln(n)\mu$ fitness evaluations.
		%for $c=2m+5$ since $n^{m/2+1-c/4} + n^{1-c/4} = o(1)$ for $c = 2m-5$.\dirk{Why do we need a larger $c$ here?}
	\end{proof}
  To generate a Pareto optimal $y$ with $Z_{f(y)} = Z_{f(x)}$ and $O_{f(y)} = O_{f(x)} \cup \{i\}$ we consider both versions of \nsgaIII separately. \\
  For \nsgaIII without stochastic population update an additional phase of expected $O(n)$ generations ensures that every fitness vector $w \in F^*$ with $L(w)=L(f(x))$ has cover number at least $c:=\lfloor{\mu/(2n/d+1)^{d/2}}\rfloor$ (by Lemma~\ref{lem:sparsity}(1)). Then, to generate $y$, one can choose $z$ with $L(f(z))=L(f(x))$ and $\ones{z^{(i+1)/2}}=2n/d-k$ as a parent (prob. $c/\mu$), and flip $k$ specific bits while keeping the remaining bits unchanged (prob. $(1-1/n)^{n-k}/n^k \geq 1/(e n^k)$). Hence, in one generation this happens with probability at least 
  $$1-\Bigl(1-\frac{c}{e \mu n^k}\Bigl)^\mu \geq \frac{c/(en^k)}{1+c/(en^k)} = \Omega(c/n^k).$$
  where the first inequality is due to Lemma 10 in~\citep{Badkobeh2015}. Hence, in total, we obtain $O(n^k/c+n\ln(n)) = O(n^{k+d/2}/\mu+n\ln(n))$ generations in expectation to generate $y$. \\
  For \nsgaIII with stochastic population update we consider a sequence of $k$ successive generations and for $\ell \in [k]$ we call the $\ell$-th generation \emph{successful} if an individual $z$ is created with $2n/d-k+\ell$ ones in block $(i+1)/2$ while $z^j=x^j$ for $j \in [d/2] \setminus \{(i+1)/2\}$ and $z$ is not removed. Suppose that the $(\ell-1)$-th generation is successful. Then, generation $\ell$ is successful if in one trial one chooses a parent $p$ with $\ones{p^{(i+1)/2}} = 2n/d-k+\ell-1$ and $z^j=x^j$ for $j \in [d/2] \setminus \{(i+1)/2\}$, flips a zero bit in the $((i+1)/2)$-th block while keeping the remaining bits unchanged and finally keeps the new created individual. With probability at least 
  \[
  1-\left(1-\frac{k-\ell+1}{e \mu n}\right)^{\mu} \geq \frac{\frac{k-\ell+1}{en}}{1+\frac{k-\ell+1}{en}} \geq \frac{k-\ell+1}{4n}
  \]
  a desired individual $z$ is created in generation $\ell$. Note that $z$ is not Pareto-optimal for $\ell<k$. However, $\mu-\lceil{3\mu/2}\rceil$ individuals chosen uniformly at random survive (see Line~\ref{line:update} and Line~\ref{line:survival} in Algorithm~\ref{alg:nsga-iii} for $a=1$) and hence even a non Pareto optimal individual remains with probability at least $(\mu - \lceil{3 \mu/2}\rceil)/\mu = \lfloor{\mu/2}\rfloor/\mu \geq (\mu/2-1)/\mu = 1/2- 1/\mu$. For $n$ sufficiently large, we have $1/2- 1/\mu \geq 1/3$ and hence with probability at least $(k-\ell+1)/(12n)$, generation $\ell$ is successful. If all $k$ generations are successful, the desired $y$ is created, which happens with probability at least 
  \begin{align*}
  \prod_{\ell=1}^k \frac{k-\ell+1}{12n} = \frac{k!}{(12n)^k} \geq \frac{k^k}{(12en)^k}
  \end{align*}
  (since $k! \geq (k/e)^k$ by Stirling's approximation). Hence, the expected number of generations to create the desired $y$ is at most $k(12en)^k/k^k$.\\
  In either case, by symmetry, the above bounds also apply to create a Pareto optimal $y$ such that $Z_{f(y)} = Z_{f(x)} \cup \{i\}$ for $i \in Z_v \setminus Z_{f(x)}$ and $O_{f(y)} = O_{f(x)}$ else. Since $O_v$ and $Z_v$ are both finite, we obtain that a Pareto optimal individual $z$ with $O_{f(z)}=O_v$ and $Z_{f(z)} = Z_v$ is created in expected $O(n^{k+d/2}/\mu+n \ln(n))$ generations when stochastic population update is turned off and $O(k(\frac{12en}{k})^k)$ it it is turned on. With Lemma~\ref{lem:interior-covering} we obtain that all Pareto optimal $v$ with $L(v)=L(f(z))$ are covered in expected $O(n \ln(n))$ generations, proving the lemma.
\end{proof}

We see that for $\mu \in \Omega(n^{d/2}) \cap O(n^{k+d/2-1}/\ln(n))$, the derived runtime if $a=0$ is $O(n^{k+d/2})$ in terms of fitness evaluations and, hence, independent of the population size $\mu$. An important consequence is that, if the number of objectives is $2$, \nsgaIII outperforms \nsga if also $\mu \in \omega(n^{d/2}) \cap o(n^2/k^2)$ (compare with~\citep{DoerrQu2023a} for the tight runtime bound of $\Theta(\mu n^k)$ of \nsga on $2$-\OJZJ in terms of fitness evaluations if $n+1 \leq \mu \in o(n^2/k^2)$).

\section{Lower Runtime Bounds}
In this section we prove sharp lower runtime bounds of \nsgaIII without stochastic population update on \OJZJ for the bi-objective case which are tight for many parameter settings. To this purpose, we show that with probability $1-e^{-\Omega(n)}$ after $O(n)$ generations, the cover number of every $v \in F^*$ can be bounded from above by a sufficiently small value, which also remains for all future iterations. In other words, the population remains well-distributed across $F^*$. %The main tool for this analysis is Lemma~\ref{lem:even-cover}(3).

\begin{lemma}{lemsparsity}
    \label{lem:sparsity-2}
    %, and suppose that all interior points of the Pareto front have been found \andre{define}. 
