		&= \frac{2n}{d} - k +\left(1-\frac{1}{\beta}\right)\left(k-\frac{n}{d}\right) + \frac{3}{2\beta} < \frac{2n}{d} - k.
		%&\leq \frac{2n}{m} - k -\frac{k(6-2\beta)}{2\beta}+\frac{3}{2\beta} \leq \frac{2n}{d} - k
	\end{align*}
	Note that for 
	$$B_1:=\frac{\frac{2n(\beta-1)}{d}+2k-3}{2\beta}$$ %= \frac{n}{m}\left(1-\frac{1}{\beta}\right) + \frac{2k - 3}{2\beta} < k.
	we have $B_1+B_2 = 2n/d$ and therefore $B_1 = 2n/d-B_2 \geq k$. 
	%and similarly
	%\begin{align*}
	%&B_1:=\frac{\frac{2n(\beta-1)}{m}+2k-3}{2\beta} = \frac{n}{m}\left(1-\frac{1}{\beta}\right) + \frac{2k - 3}{2\beta} < k.
