      \field{labelnamesource}{author}
      \field{labeltitlesource}{title}
      \field{abstract}{In this paper we showcase the lack of robustness of one of the foremost results connecting game theory and learning theory. We show that the zero-sum, i.e. rank-zero, condition on a two-player game is critical to Freund and Schapire{’}s fundamental result (Freund \& Schapire, 1996) that establishes convergence (of cumulative strategies to a {N}ash equilibrium) when each player uses the weighted majority algorithm. We show that weighted majority no longer accomplishes such distributed learning in the slightly wider class of games of rank at most one (nearly zero-sum). Our contribution stands in contrast with recent findings showing that the centralized tractability of computing a {N}ash equilibrium carries through from zero-sum games (as established by the minimax theorem) to nearly zero-sum games.}
      \field{booktitle}{{ICML} {Workshop} on {Markets}, {Mechanisms}, and {Multi}-{Agent} {Models}}
      \field{title}{The {Weighted} {Majority} {Algorithm} does not {Converge} in {Nearly} {Zero}-sum {Games}}
      \field{year}{2012}
