\vspace{-0.5em}
\section{Main algorithms}\label{sec:mainalgo}

We can finally present our main algorithms, where we use Newton
iteration to compute lexicographic Gr\"obner bases: we are given
$\mathcal{F}=(f_1,\dots,f_t)$ in $\Z[x,y]$, and we compute either the
Gr\"obner basis $\mathcal G=(g_0,\dots,g_s)$ of $I=\langle
f_1,\dots,f_t \rangle$, or the Gr\"obner basis
$\mathcal{G}^0=(g^0_0,\dots,g^0_r)$ of the $\langle
x,y\rangle$-primary component of $I$ using $p$-adic approximation, for
a prime $p$. In what follows, we give details for the computation of
$\mathcal G$; we will mention what modifications are needed if we want
to compute $\mathcal{G}^0$.

The algorithm is randomized; it takes a parameter $P \ge 1$, our
goal being to obtain the correct output with probability at least
$1-1/2^P$. Throughout, we assume that $f_1$ has maximum degree among
the $f_i$'s (we write $d=\deg(f_1)$) and that $I$ has dimension zero.
Let $\delta =\deg(I) =\dim_\Q \Q[x,y]/I$, $\delta \le d^2$ and let $b$
be the maximum height of the numerators and denominators of the
coefficients in $\mathcal G$. Each polynomial in $\mathcal G$ has at
most $\delta+1$ coefficients, so the total bit-size of the output is
$O(s \delta b)$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\vspace{-0.5em}
\subsection{Overview}\label{sec:overview}

We start by presenting the main steps of the algorithm, leaving out
some details of the analysis for the next subsection. Runtimes are
given in terms of bit operations; here, we use the fact that
operations $(+,\times)$ modulo a positive integer $M$ take
$\softO(\log(M))$ bit operations, as does inversion modulo $M$ if $M$
is prime~\cite{GaGe13}.

\smallskip\noindent{\bf Introducing a change of coordinates.} We first
choose a change of variables $\bm\gamma$ with coefficients in
$\Z$. Applying it to the input equations $\mathcal F$ gives
polynomials $\mathcal{H}=(h_1,\dots,h_t)$, which we do not need to
compute explicitly (as they may have large height). We let
$\mathcal{B} = (B_0,\dots,B_\sigma)$ be the lexicographic Gr\"obner
basis of these polynomials in $\Q[x,y]$ (as with $\mathcal{H}$, we
do not compute it explicitly).

We assume that $\bm\gamma$ satisfies the assumptions of
\cref{prop:F1,prop:F2}, so that their conclusions hold.

\smallskip\noindent{\bf Computing Gr\"obner bases modulo $\bm p$.}
Next, we choose two primes $p,p'$, and compute the
Gr\"obner bases $\mathcal B_{p}$ of $(\mathcal H \bmod p)$, and $\mathcal B_{p'}$ of
$(\mathcal H \bmod p')$. We assume that neither $p$ nor $p'$ divides
the integers $\beta_{\mathcal F}$ and $\beta_{\mathcal H}$ from
\cref{def:H} applied to $\mathcal F$ and $\mathcal H$, respectively. In
particular, all denominators in $\mathcal B$ are invertible modulo $p$
and $p'$, and $\mathcal B_{p}=\mathcal B \bmod p$ and $\mathcal B_{p'}=\mathcal
H \bmod p'$.

To compute $\mathcal B_{p}$ and $\mathcal B_{p'}$, the algorithm reduces the $O(t d^2)$
coefficients of $\mathcal F$ modulo $p$ and $p'$. Then, we apply
$\bm\gamma$ to the results, to obtain $\mathcal H \bmod p$ and
$\mathcal H \bmod p'$. Due to \cref{prop:F1}, the coefficient of $y^d$
in $h_1$ is a nonzero constant; if this is still the case modulo $p$
and $p'$, we use $\textsc{HermiteGroebnerBasis}$ with $D=d$ to get
$\mathcal B_{p}$ and $\mathcal B_{p'}$; otherwise, we raise an error.

\smallskip\noindent{\bf Changing coordinates in $\mathcal B_{p}$ and $\mathcal B_{p'}$.}
Using the Gr\"obner bases $\mathcal B_{p}$ and $\mathcal B_{p'}$ of $(\mathcal H \bmod
p)$ and $(\mathcal H \bmod p')$, we compute the Gr\"obner bases of
$(\mathcal F \bmod p)$ and $(\mathcal F \bmod p')$. This is done using
the algorithm of~\cite{NeSc20}. Since $pp'$ does not divide
$\beta_{\mathcal F}$, we deduce that we obtain $\mathcal G_{1} = \mathcal G
\bmod p$ and $\mathcal G_{1}' =\mathcal G \bmod p'$.

\smallskip\noindent{\bf Computing $\mathcal G_{k}$.} At each step of the main
loop, we start from $\mathcal G_{{k/2}} = \mathcal G \bmod p^{k/2}$, and we
compute $\mathcal G_{{k}}=\mathcal G \bmod p^{k}$. For this, we first need
$\mathcal F \bmod p^{k}$; then, we use procedure
\textsc{LiftOneStepGroebner} from~\cite[Remark~7.3]{ScSt23} to obtain
$\mathcal G_{{k}}$.


\smallskip\noindent{\bf Rational reconstruction.}  We next attempt to
recover all rational coefficients of $\mathcal G$, given those
of $\mathcal G_{k} = \mathcal G \bmod p^k$. For each coefficient $\alpha$ of
$\mathcal G_k$, we attempt to recover a pair $(\eta,\theta)$ in $\Z\times
\N$, with $|\eta| < p^{k/2}/2$ and $\theta \le p^{k/2}$, $\theta$
invertible modulo $p$ and $\alpha = \eta/\theta \bmod p^k$.

By assumption, all nonzero coefficients of $\mathcal G$
have numerators and denominators of height at most $b$, it follows
that if $p^{k/2} > 2 e^b$, we will succeed and correctly recover the
corresponding coefficient in $\mathcal G$~\cite[Theorem~5.26]{GaGe13}.
For smaller values of $k$, rational reconstruction may find no
solution (in which case we reenter the lifting loop at precision
$2k$), or may already terminate; in this case, its output $\mathcal
G_{\rm rec}$ may be different from $\mathcal G$.

%\smallskip\noindent{\em Cost:} Rational reconstruction takes
%$\softO(k\log(p))$ bit operations per coefficient, for a total of
%$\softO(s \delta k \log(p))$.

\smallskip\noindent{\bf Testing for correctness.} The final step in
the loop is a randomized test, using $\mathcal G_{1}'=\mathcal G \bmod
p'$ as a witness to detect those cases where rational reconstruction
returned an incorrect result. We attempt to reduce $\mathcal G_{\rm
  rec}$ modulo our second prime $p'$ ($\mathcal G_{\rm red}$); if this fails (because $p'$
divides one of the denominators in it), we reenter the lifting loop at
precision $2k$. We
simply compare $\mathcal G_{\rm red}$ and $\mathcal G_{1}'=\mathcal G \bmod
p'$. If they coincide, we return $\mathcal G_{\rm rec}$, otherwise, we
reenter the lifting loop.
\vspace{-1em}
\begin{algorithm}
 \caption{GroebnerBasis(${\mathcal F}$)}
  \begin{algorithmic}[1]
    \Require $\mathcal F=(f_1,\dots,f_t)$ in $\Z[x,y]$, $d=\max\{\deg f_i\}$, 
    \Ensure the lexicographic Gr\"obner basis of $\mathcal F$ in $\Q[x,y]$
    \State choose $\bm \gamma$ in $M_2(\Z)$
    \State choose two different primes $p,p'$;  do steps 3-6  for $i\in \{p,p'\}$
    \State {\bf if} {$\bm \gamma \bmod i$ is not invertible} {\bf then} {raise an error}
    \State $\mathcal H_i \gets \textsc{ChangeCoordinates}(\mathcal F \bmod i, \bm\gamma \bmod i)$
    %\State $h_1 \gets \mathcal H_i(1)$
    \State {\bf if} {the coefficient of $y^d$ in $\mathcal H_i(1)$ is zero} {\bf then} {raise an error}
    \State $\mathcal B_{i} \gets \textsc{HermiteGroebnerBasis}(\mathcal H_{i}, d)$

    \State $\mathcal G_{1} \gets \textsc{ChangeCoordinatesGroebner}(\mathcal B_{p}, \bm \gamma^{-1} \bmod p)$
    \State $\mathcal G_{1}' \gets \textsc{ChangeCoordinatesGroebner}(\mathcal B_{p'}, \bm \gamma^{-1} \bmod p')$

    \State $k \gets 1$
    \Repeat
    \State $k \gets 2k$
    \State $\mathcal G_{k} \gets \textsc{LiftOneStepGroebner}(\mathcal F \bmod p^k, \mathcal G_{{k/2}})$
    \State $error, \mathcal G_{\rm rec} \gets \textsc{RationalReconstruction}(\mathcal G_{k})$
    \State {\bf if\ not} $error$ {\bf then}
    {$error, \mathcal G_{\rm red} \gets \mathcal G_{\rm rec} \bmod p'$}
    \Until \textbf{not} $error$ \textbf{and} $\mathcal G_{\rm red} = \mathcal G_1'$
    \State \Return $\mathcal G_{\rm rec}$
  \end{algorithmic}
\end{algorithm}
\vspace{-1em}\\ 

