\begin{lstlisting}[language=Rust, backgroundcolor=\color{rustBackgroundColor},  multicols=2,caption={An example script of an agent's behaviour, embedded in Rust, but simplified for readability. The script demonstrates stateful reasoning, reacting to an agreement in the control plane by taking action. This script defines the behaviour of agent Amy in \Cref{sec:scenario:isolated_execution}.}, label={lst:eg_agent_script}]
self.handler
  // Wait for the fact
  // `(surf utils) ready.`,
  // publish `amy 1`.
  .on_truth(
    slick::parse::ground_atom(
      "(surf utils) ready"
    ),
    |view| view.stated.add(
      Recipient::All,
      create_message(1, "amy", r#"
(amy count-patients)
  has input ((surf utils) entry-count).
(amy count-patients) has input
  ((st-antonius patients-2024) patients).
(amy count-patients)
  has output num-patients.
(amy count-patients) ready."#)
    )
  )
  // Wait for the action `st-antonius b`,
  // publish `amy 2`.
  .on_enacted(
    ("st-antonius", 'b'),
    |view, _| view.stated.add(
      Recipient::All,
      create_message(2, "amy", r#"
(amy end) has input
  ((amy count-patients) num-patients).
(amy end) ready.
(amy end) executed."#)
    )
  )
  // Wait for agreement and selected
  // statements, publish `amy a`
  .on_agreed_and_stated(
    ("consortium", 1),
    [
      ("amy", 1), ("amy", 2),
      ("st-antonius", 1),
      ("st-antonius", 2),
      ("st-antonius", 3), ("surf", 1),
    ],
    |view, agree, just| {
      view.enacted.add(
        Recipient::All,
        create_action(
          'a', "amy",
          agree, just
        )
      );
      self.store.read(
        (
          ("amy", "count-patients"),
          "num-patients"
        ),
        ("amy", 'a')
      );
      Ok(())
    })?
  .finish()
\end{lstlisting}
