\begin{lstlisting}[language=Rust, backgroundcolor=\color{rustBackgroundColor},  multicols=2,label={lst:game_loop},caption={Simplified Rust source code showing the ``game loop'' of the system, orchestrating the agents and managing their access to state.}]
fn game_loop(
  agents: Vec<dyn Agent>,
  sync: Box<dyn Synchronizer>
) {
  let st = AsyncSet::<Message>::new();
  let en = AsyncSet::<Action>::new();
  let ti = TimesSet::new();
  let ag = 
    HashSet::<Agreement<Message, u64>>
      ::new();

  loop {
    for agent in &mut agents {
      agent.poll((
        &mut st.scope(agent.id()),
        &mut en.scope(agent.id()),
        &ag,
        &ti,
      ));
    }

    match sync.poll((
      &mut st.scope("environment"),
      &mut en.scope("environment"),
      &mut ag,
      &mut ti,
    )) {
      ControlFlow::Continue => continue,
      ControlFlow::Break => break,
} } }
\end{lstlisting}
\end{figure}

