    \subsection{Prediction and Optimization}
    \textbf{Prediction.} Finally, we can utilize scale-shared and scale-specific temporal representations, which contain non-redundant multi-scale features, to make the prediction:
    \begin{equation}
    \label{pred}
        \hat{\mathbf{y}}_{T+1}={Prediction}(\mathbf{F}_{sha}||\mathbf{F}_{spe}),
    \end{equation}

    \noindent where $\mathbf{F}_{sha}=\frac{1}{S+1}\sum_{s=0}^S\mathbf{F}_{s,sha}$, $\mathbf{F}_{spe}= \underset{s=0}{\overset{S}{\|}} \mathbf{F}_{s,spe}$, $\|$ indicates the concatenation operator, and $Prediction(\cdot)$ is a feed forward network with two fully-connected layers.





   \noindent\textbf{Optimization.}
   To empower the DisMS-TS with the capability to effectively learn both scale-shared and scale-specific temporal representations, we introduce two regularization terms to constrain their feature distributions. First, we propose a similarity regularization term to ensure that all scale-shared temporal representations exhibit a consistent distribution, i.e., $\forall i,j\in \{0:S\}, \mathbf{F}_{i,sha}=\mathbf{F}_{j,sha}$. Specifically, 

        \begin{equation}
        \label{sim}
    \small
        \mathcal{L}_{sim}=\frac{2}{S{(S+1)}} \sum_{i=0}^{S-1}\sum_{j=i+1}^S {MSE}({Sim}(\mathbf{F}_{i,sha},\mathbf{F}_{j,sha}),1),
    \end{equation}

    \noindent where $MSE(\cdot)$ denotes the mean squared error function and $Sim(\cdot)$ refers to the cosine similarity. 

    Second, the disparity regularization term is designed to ensure that all scale-specific representations are orthogonal and maintain independent distributions, i.e., $\forall i, j \in \{0:S\}, i\neq j$, $\mathbf{F}_{i,spe}\perp\mathbf{F}_{j,spe}$, which is formulated as:
    \begin{equation}
    \label{dis}
    \small
        \mathcal{L}_{dis}=\frac{2}{S{(S+1)}} \sum_{i=0}^{S-1}\sum_{j=i+1}^S {MSE}({Sim}(\mathbf{F}_{i,spe},\mathbf{F}_{j,spe}),0).
    \end{equation}

    \noindent The final training objective is,
    \begin{equation}
    \label{loss}
        \small
        \mathcal{L}=\mathcal{L}_{class}+\lambda_1\mathcal{L}_{sim}+\lambda_2\mathcal{L}_{dis}
    \end{equation}
    \noindent where $\mathcal{L}_{class}$ is the cross-entropy loss, $\lambda_1$ and $\lambda_2$ are the hyperparameters striking a balance between three terms. 

    The algorithm of  DisMS-TS is shown in Algorithm 1.


    \begin{algorithm}[t]
    \label{algorithm1}
\caption{Training pipeline for DisMS-TS}
\begin{algorithmic}[1]  % The number indicates the number of the lines to be printed
\State \textbf{Input:} Time series $\mathbf{X}$, training epochs $L$, scale number $S$, hyperparameter $\lambda_1$, $\lambda_2$.
\State \textbf{Output:} Optimized parameters $\Theta_m$, prediction of $\hat{\mathbf{y}}_{T+1}$.
\State Randomly initializes the model parameters.
\For{$l=1,2,...,L$}
    \State Obtain multi-scale series $\{\mathbf{X}_s\}_{s=0}^S$ as Eq.\eqref{MSG}.
    \State Generate temporal representations $\{\mathbf{F}_s\}_{s=0}^S$ as Sec.\ref{MTE}.
    \State Obtain $\{\mathbf{F}_{s,sha}\}_{s=0}^S$ and $\{\mathbf{F}_{s,spe}\}_{s=0}^S$ as Eq.\eqref{decompose}.
    \State Make prediction as Eq.\eqref{pred}.
    \State Calculate similarity and disparity loss as Eq.\eqref{sim} \& Eq.\eqref{dis}.
    \State Update the model according to Eq.\eqref{loss}.
\EndFor
\end{algorithmic}
\end{algorithm}




