\begin{lstlisting}[language=C++, caption={CPU C Code with TVM dependency.},label={lst:cpu_with_tvm}, breaklines=true]
TVM_DLL int32_t default_function(void* args, int32_t* arg_type_ids, int32_t num_args, void* out_ret_value, int32_t* out_ret_tcode, void* resource_handle) {
    void* compute = (((TVMValue*)args)[1].v_handle);
    void* compute_1 = (((DLTensor*)compute)[0].data);
    // Computation Loop
    for (int32_t i1 =0; i1 <36; ++i1) {
        for (int32_t i2 =0; i2 <9; ++i2) {
            int32_t cse_var_1 = ((i1  *9) + i2);
            ((float*)compute_1)[cse_var_1] =cosf(((float*)tarray_1)[cse_var_1]);
        }
    }
