\section{SVD-based Iterative Tensor Decomposition}
\label{sec:section3}
\subsection{SVD-based Tensor Decomposition}
Assume a linear projection layer of an LLM that projects a hidden dimension of size \( K \) to size \( N \), with batch size \( M \). This layer can be expressed as:
\begin{equation}
    \mathbf{Y} = \mathbf{XW}, \quad \mathbf{X} \in \mathbb{R}^{M \times K},  \mathbf{W} \in \mathbb{R}^{K \times N}, \, \mathbf{Y} \in \mathbb{R}^{M \times N}
\end{equation}
where \( \mathbf{X} \) is the activation matrix, \( \mathbf{W} \) is the weight matrix, and \( \mathbf{Y} \) is the output. SVD can be used to decompose and approximate the weight matrix, producing an approximation of the matrix-matrix product. In this context, SVD decomposes a weight matrix \( \mathbf{W}\) into three matrices: \( \mathbf{U} \), \( \boldsymbol{\Sigma} \), and \( \mathbf{V}\), where \( \boldsymbol{\Sigma} \) is a diagonal matrix, with the diagonal values in \( \boldsymbol{\Sigma} \) being the singular values of \( \mathbf{W} \), and \( \mathbf{U}\) and \( \mathbf{V} \) are the corresponding left and right singular vector matrices, respectively \cite{10.5555/264989}. An approximation can be obtained by keeping the \( r \) largest singular values while the rest are truncated.
\begin{equation}
    \mathbf{W} \approx (\mathbf{U}_r \boldsymbol{\Sigma}_r^{\frac{1}{2}})(\boldsymbol{\Sigma}_r^{\frac{1}{2}} \mathbf{V}_r^\top) = \mathbf{W}_1\mathbf{W}_2
\end{equation}
where \( \mathbf{W}_1 \in \mathbb{R}^{K \times r}, \mathbf{W}_2 \in \mathbb{R}^{r \times N}\). To leverage the benefits of this low-rank decomposition in terms of computational efficiency and memory usage, the activation \( \mathbf{X} \) is directly multiplied by the decomposed matrices without reconstructing the original weight matrix \( \mathbf{W} \). Thus, the forward pass of the linear layer can be rewritten as:
\begin{equation}
\label{eq:svd_multiply}
    \mathbf{Y} \approx \mathbf{XW} = (\mathbf{X}\mathbf{W}_1)\mathbf{W}_2
\end{equation}

Usually, quantization is applied to the resulting \(\mathbf{W}_1\) and \(\mathbf{W}_2\) matrices. This transforms the original single matrix multiplication into two sequential matrix multiplications with the possibility to reduce the total number of operations and model parameters by selecting a suitable decomposition rank.

\subsection{SVD-based Iterative Tensor Decomposition Algorithm}

% Previous work has demonstrated that the main building block of LLMs, the transformer layer, contains magnitude outliers in weights\cite{wei2023outliersuppressionpushinglimit,bondarenko2021understandingovercomingchallengesefficient}. Post-training quantization-only approach suffers from considerable overflow error or from considerable rounding error, leading to substantial task accuracy degradation. We reshape the error surface of quantization by integrating quantization with SVD-based tensor decomposition through an iterative approach, allowing more flexibility in the approximation of the matrix.

Our SVD iterative decomposition transforms the traditional SVD decomposition into a refinement loop consisting of $r$ iterations.  In each iteration, the algorithm quantizes the singular vectors corresponding to the largest singular values. At the beginning, residual $\tilde{\mathbf{R}}$ is initialized as the weight $\mathbf{W}$. During subsequent iterations, the residual is updated by subtracting the product of the two quantized rank-1 singular vectors from the current residual. This iterative algorithm aims to minimize the Frobenius norm of the residual $\tilde{R}$ by producing two new quantized rank-1 singular vectors at each step. Outliers in the weight matrix with large magnitudes contribute disproportionately to the residual, forcing the algorithm to focus on these outliers for better approximation.

\begin{equation}
\| \tilde{\mathbf{R}}_r \|_F^2 = \| \mathbf{W} - \sum_{k=1}^r \mathbf{W'}_1^k \mathbf{W'}_2^k \|_F^2
\end{equation}
At the end of the loop, all quantized rank-1 singular vectors are augmented to constitute two quantized rank-$r$ matrices $\mathbf{W'}_1$, $\mathbf{W'}_2$. The details of the proposed iterative algorithm are illustrated in Fig.~\ref{img:iterative_quant_svd} and Algorithm \ref{alg:iterative_svd}.

\begin{figure}[t]
\centering
\includegraphics[width=\linewidth]{image/section3/iterative_quant_svd1.png}
\vspace{-15pt}
\caption{The proposed iterative tensor decomposition algorithm with SVD and quantization in a closed loop}
\label{img:iterative_quant_svd}
\end{figure}

\begin{algorithm}
\caption{SVD-based Iterative Tensor Decomposition}
\label{alg:iterative_svd}
\footnotesize
\begin{flushleft}
\textbf{Input:} $\mathbf{W}$, $\mathbf{r}$, \textbf{weight\_wl}\\
\Comment{\textcolor{magenta}{$\mathbf{W}$ is a FP32 weight matrix. $\mathbf{r}$ is the target rank for the decomposition, and \textbf{weight\_wl} is the word length of the quantization scheme.}} \\
\textbf{Output:} $\mathbf{W'}_1$, $\mathbf{W'}_2$\\
\Comment{\textcolor{magenta}{Output tensor decompositions are quantized with precision \textbf{weight\_wl}.}} \\
\end{flushleft}

\begin{algorithmic}[t]
\State Initialize $k \gets 1$
\State  $\mathbf{W}_1^1, \mathbf{W}_{2}^1 = \text{SVD}(\mathbf{W})_1$ \Comment{\textbf{Rank-1 Approximation}}
\State $\mathbf{W'}_1^1, \mathbf{W'}_2^1 = \text{Quant}(\mathbf{W}_1^1, \mathbf{W}_{2}^1,\text{weight\_wl})$ \Comment{\textbf{Quantization}}
\State $\tilde{\mathbf{R}} = \mathbf{W}-\mathbf{W'}_1^1\mathbf{W'}_2^1$ \Comment{\textbf{Residual Update}}
\State $\mathbf{W'}_1 = \left[\mathbf{W'}_1^1\right]$ and $\mathbf{W'}_2 = \left[\mathbf{W'}_2^1\right]$
\While{$k < r$}
    \State  $\mathbf{W}_{1}^k, \mathbf{W}_{2}^k = \text{SVD}(\tilde{\mathbf{R}})_1$ 
    \Comment{\textbf{Rank-1 Approximation} on Residual}
    \State $\mathbf{W'}_{1}^k, \mathbf{W'}_{2}^k = \text{Quant}(\mathbf{W}_{1}^k, \mathbf{W}_{2}^k,\text{weight\_wl})$ \Comment{\textbf{Quantization}}
    \State $\mathbf{W'}_1=\text{hstack}(\mathbf{W'}_1,\mathbf{W'}_{1}^k)$
    \State $\mathbf{W'}_2=\text{vstack}(\mathbf{W'}_2,\mathbf{W'}_{2}^k)$ \Comment{Augmentation}
    \State $\tilde{\mathbf{R}} = \tilde{\mathbf{R}}-\mathbf{W'}_{1}^k, \mathbf{W'}_{2}^k$ \Comment{\textbf{Residual Update}}
    \State $k \gets k + 1$

\EndWhile
\State return $\mathbf{W'}_1$, $\mathbf{W'}_2$
\end{algorithmic}
\end{algorithm}

\section{Sensitivity-Based Rank Allocation}
\label{sec:section4}
% The distribution of singular values within a matrix reflects its information redundancy and sensitivity to specific types of information \cite{kim2019efficientneuralnetworkcompression}. In LLMs, the singular value distributions exhibit significant variations across different layers. Certain layers have a concentration of larger singular values, indicating lower sensitivity to rank truncation and making them easier to compress. In contrast, other layers exhibit a more uniform singular value distribution, suggesting a more balanced contribution from multiple singular vectors to the model's functionality. This diversity in distribution presents unique challenges, necessitating layer-specific optimization to preserve the overall functionality and performance of LLMs.
Different layers in LLMs exhibit varying degrees of sensitivity to rank truncation, as shown in Fig.~\ref{img:sensitivity_analysis}. While some layers can tolerate significant rank reduction, others are more sensitive and require higher ranks to preserve the overall model functionality. To address this variability, we introduce a novel Sensitivity-based Rank Allocation (SRA) algorithm that tunes the approximation of each layer of an LLM by adjusting the rank in its decomposition. The goal is to assign a rank for each layer so that the model achieves the best performance possible under a specific model compression ratio.

\begin{figure}[H]
\centering
\includegraphics[width=0.85\linewidth]{image/section2/sensitivity.png}
\vspace{-5pt}
\caption{The sensitivity analysis measures the reduction in \texttt{BLEU Score} when varying the percentage of rank retained in each layer. Each layer's weight matrices are truncated to the specified rank percentage, temporarily replacing the original matrices in the model while keeping other layers unchanged.}
\label{img:sensitivity_analysis}
\vspace{-5pt}
\end{figure}

\subsection{Problem Formulation}

Let \( L \) represent the number of layers in the LLM. Denote the rank allocated to the \( i \)-th layer as \( r_i \), where \( r_i \in \mathbb{N} \). Our objective is to find the rank allocation \( [r_1, r_2, \dots, r_L] \) under the constraint that the total rank is equal to a given rank budget \( R_{\text{total}}^* \), and the model inference accuracy \(A\) is maximized. The optimization problem can be formulated as:
\begin{equation}
    \max_{[ r_1, r_2, \dots, r_L]} A \quad \text{subject to} \quad \sum_{i=1}^{L} r_i = R_{\text{total}}^*
\end{equation}

\subsection{Sensitivity-Based Rank Allocation (SRA) Algorithm}
The SRA algorithm iteratively allocates ranks to the layers of the LLM model \(\mathcal{L}\) based on their varying sensitivities. The algorithm's workflow is outlined below.
\begin{enumerate}
    \item \textbf{Initial Setup:} Initialize the rank \( r_i \) for each layer with  \( r_i = \frac{R_{\text{total}}^*}{L} \), such that the total rank budget is split equally across all layers.
    \item \textbf{Objective Evaluation:} For the given rank allocation \([r_1, r_2, \dots, r_L] \), the model accuracy \( A \) is evaluated using a randomly sampled calibration set.
    \begin{equation}
        A\leftarrow \mathcal{L}[r_1, r_2, \dots, r_L]
    \end{equation}
    \item \textbf{Sensitivity Approximation:} The sensitivity $S_{r_i}$ is defined as the partial derivative of model accuracy $A$ to the rank $r_i$. The idea is that layers with higher sensitivity will be allocated more ranks in order to achieve a larger improvement in accuracy.
    \begin{equation}
        S_{r_i}=\frac{\partial A}{\partial r_i} 
    \end{equation}
    Due to the non-linear nature of LLM, the model accuracy is not directly differentiable with respect to the rank of each layer, so we approximate the sensitivity $S_{r_i}$ using the finite difference method as:
    \begin{eqnarray}
    % \small{
    \begin{gathered}
    A_{i}^{+}\leftarrow \mathcal{L}[r_1, \dots r_i + \delta, \dots, r_L]\\
    A_{i}^{-}\leftarrow \mathcal{L}[r_1, \dots r_i - \delta, \dots, r_L]\\
    S_{r_i} \approx \frac{A_i^{+} - A_i^{-}}{2\delta}\\
    \end{gathered}
    % }
    \vspace{-0.25in}
    \end{eqnarray}
    where \( \delta \) is a small integer perturbation value.
    \item \textbf{Rank Adjustment:} Rank adjustment is performed iteratively. In each iteration, the layers with the highest and lowest sensitivities are identified, and their ranks are increased and decreased by \( \delta \), respectively.
    \begin{equation}
    \small{
        r_i^{\text{new}} = r_i + \delta \quad \text{for} \quad i = \arg \max_{i} \left[ S_{r_1}, S_{r_2}, \dots, S_{r_L} \right]
        }
    \end{equation}
    \begin{equation}
    \small{
        r_j^{\text{new}} = r_j - \delta \quad
        \text{for} \quad j = \arg \min_{j} \left[ S_{r_1}, S_{r_2}, \dots, S_{r_L} \right]
    }
    \end{equation}

    To improve the convergence property of the optimization, \( \delta \) decays over time during the iterations. The decay strategy is as follows:
    \begin{equation}
        \delta_{n} = \text{round}\left[\frac{\delta_0}{(1 + \alpha n)}\right]
    \end{equation}
    where \( \delta_0 \) is the initial perturbation value, \( n \) is the current iteration number, and \( \alpha \) is a small constant that controls the rate of decay. This decaying \( \delta \) ensures that the gradient approximation has a finer granularity as the algorithm approaches an optimal solution.
    \item \textbf{Termination:} The algorithm terminates when the \texttt{BLEU Score} converges to a maximum value or after a predetermined number of iterations.
\end{enumerate}

