\section{Riesz bases of Sobolev and Barron classes}\label{Sec:2}

The aim of this section is to study the properties of the univariate system 
% \eqref{eq:CSsystem} 
$\cR_1$ and its multivariate analogue $\cR_d$ from \eqref{eq:intro_Riesz_d}
in other function spaces than just $L_2([0,1])$ or $L_2([0,1]^d)$, respectively. To simplify the presentation,
we first deal with the univariate Sobolev spaces before we come their high-dimensional counterparts and to the Barron classes.

\subsection{Univariate Sobolev classes}

Let us consider a real-valued square-integrable function $f:{\mathbb R}\to {\mathbb R}$, which is periodic with period one, i.e., $f$ is given by
\begin{equation}\label{eq:decomp_f_Fourier}
f(x)\,=\, a_0 \,+\, \sum_{m=1}^\infty a_m\cos(2\pi mx) + b_m\sin(2\pi mx),\quad x\in [0,1].
\end{equation}
For a real number $s\ge 0$, we define the usual Sobolev spaces of periodic functions of order~$s$ by 
\begin{align*}
% W^s&:=
W^s([0,1])&:=\left\{f:f \text{ is given by \eqref{eq:decomp_f_Fourier} and }\|f\|_{W^s}^2:= 
a_0^2+
\sum_{m=1}^\infty m^{2s}(a_m^2+b_m^2)<\infty\right\},
\end{align*}
and note that $W^0([0,1])=L_2([0,1])$.
% Obviously, $W^0([0,1])$ contains all functions from $L_2([0,1])$ with vanishing integral. 
% Further note that 
% \[
% \|f^{(s)}\|_{L_2}=2^{s-1/2}\cdot \pi^s\cdot \|f\|_{W^s}
% \]
% for $s\in\N$, where $f^{(s)}$ denotes the $s$-th derivative of $f$.

It was shown in \cite{DD+22} that the system $\cR_1$ from \eqref{eq:intro_Riesz_d} 
forms a Riesz basis in $W^0([0,1])$. The aim of this section is to investigate the properties of 
% \eqref{eq:CSsystem} 
$\cR_1$ 
as subsets of $W^s([0,1])$.
We start by defining the analogues of $W^s([0,1])$ based on \eqref{eq:intro_Riesz_d}.
Let
\begin{equation}\label{eq:decomp_f_CalC}
f(x) = \alpha_0 \,+\, \sum_{k=1}^\infty \alpha_k \CalC_k(x) + \beta_k \CalS_k(x), \quad x\in [0,1],
\end{equation}
with $\alpha_k,\beta_k\in\R$, 
% and with convergence in $L_2([0,1])$. 
which converges in $L_2([0,1])$ if $\alpha=(\alpha_k)_{k=1}^\infty$ and $\beta=(\beta_k)_{k=1}^\infty$ are square-summable.
%
For $s\ge 0$, we define
\begin{align*}
% \F^s&=
\F^s([0,1])\,:=\,\left\{f:f \text{ is given by \eqref{eq:decomp_f_CalC} and }\|f\|_{\F^s}^2:=\alpha_0^2 \,+\,\sum_{m=1}^\infty m^{2s}(\alpha_m^2+\beta_m^2)<\infty\right\}.
\end{align*}

The following theorem shows that $\F^s$ is  a useful tool  for the analysis of $W^s$.

\begin{thm}\label{thm:d1_WF} Let $0\le s<1$. Then, $W^s([0,1])=\F^s([0,1])$ in the sense of equivalent norms. 
Moreover, the system
\begin{equation}\label{eq:Riesz_1}
    \{1\}\cup\left\{k^{-s}\CalC_k, k^{-s}\CalS_k\colon k\in \N\right\}
\end{equation}
is 
% the Riesz basis of 
% the subspace of $W^s([0,1])$ consisting of functions with vanishing mean. Alternatively, adding 
% the constant function 1 to \eqref{eq:Riesz_1} makes it 
a Riesz basis of $W^s([0,1])$ 
and for constants $c,C>0$ it holds  
\begin{equation}\label{ineq-Riesz-1d}
c\,\sum_{k\in \mathbb{N}}
(\alpha_k^{2}+\beta_k^2) 
\;\le\; 
\left\|\sum_{k\in \mathbb{N}}k^{-s}\Bigl(\alpha_k\CalC_k+ 
\beta_k \CalS_k\Bigr)\right\|^2_{W^s}
\;\le\; C\,\sum_{k\in \mathbb{N}}
(\alpha_k^{2}+\beta_k^2). 
\end{equation}
Modifications of \eqref{ineq-Riesz-1d} for functions with constant term are obvious (by incorporating $\alpha_0$).
\end{thm}






\begin{proof} 
We assume without any loss of generality that $a_0=\alpha_0=0$ throughout the proof.

\emph{Step 1.} First, we show that $W^s([0,1])\hookrightarrow \F^s([0,1])$.
%
Let $f$ be given by \eqref{eq:decomp_f_Fourier}.
We combine it with \cite{DD+22} (cf. also \cite[Lemma 2.5]{SV}), which states that
\begin{equation}\label{eq:cos_Riesz}
\sqrt{2}\cos(2\pi x)=\sum_{\ell=0}^\infty \frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot \frac{\sqrt{3}}{\kappa}{\mathcal C}_{2\ell+1}(x),
\end{equation}
\begin{equation}\label{eq:sin_Riesz}
\sqrt{2}\sin(2\pi x)=\sum_{\ell=0}^\infty (-1)^\ell\frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot \frac{\sqrt{3}}{\kappa}{\mathcal S}_{2\ell+1}(x), 
\end{equation}
where $\kappa^2=96/\pi^4$ and 
$\mu(n)\in\{-1,0,1\}$ denotes the  M\"obius function, i.e., the sum of the primitive $n$-th roots of unity.
Let us note, that $\mu(n)=0$ if the $n$ is not square-free, i.e., if it is divisible by some squared prime. 
%\[
%\mu(n)=\begin{cases}
%+1,\quad &\text{if $n$ is a square-free integer with an even number of prime factors},\\
%-1,\quad &\text{if $n$ is a square-free integer with an odd number of prime factors},\\
%0,\quad &\text{if $n$ is not a square-free integer, i.e., if it is divisible by some squared prime.}
%\end{cases}
%\]

Plugging \eqref{eq:cos_Riesz} and \eqref{eq:sin_Riesz} into \eqref{eq:decomp_f_Fourier}, we obtain
\begin{align*}
f(x)&=\frac{\sqrt{3}}{\sqrt{2}\,\kappa}\biggl\{\sum_{m=1}^\infty a_m \sum_{\ell=0}^\infty \frac{\mu(2\ell+1)}{(2\ell+1)^2}\, {\mathcal C}_{(2\ell+1)m}(x)\\
&\qquad \qquad +\sum_{m=1}^\infty b_m \sum_{\ell=0}^\infty (-1)^\ell\frac{\mu(2\ell+1)}{(2\ell+1)^2}\, {\mathcal S}_{(2\ell+1)m}(x)\biggr\}\\
&=\frac{\sqrt{3}}{\sqrt{2}\,\kappa}\sum_{k=1}^\infty \Bigl[\alpha_k \CalC_k(x) + \beta_k \CalS_k(x)\Bigr],
\end{align*}
where
\begin{gather*}
\alpha_k=\sum_{(\ell,m):k=(2\ell+1)m} a_m\cdot\frac{\mu(2\ell+1)}{(2\ell+1)^2} \quad\text{and}\quad 
%\hspace*{-.8\textwidth} \text{and} \label{eq:coef} \\
\beta_k=\sum_{(\ell,m):k=(2\ell+1)m} b_m\cdot(-1)^{\ell}\frac{\mu(2\ell+1)}{(2\ell+1)^2}.
\end{gather*}


%For non-negative sequences $\sigma$ and $\tau$, we define two kinds of function spaces.
%\begin{align*}
%W^\sigma_{c}&=\{f:f \text{ is given by \eqref{eq:decomp_f_Fourier} and }\sum_{m=1}^\infty \alpha_m^2/\sigma_m^2<\infty\},\\
%W^\tau_{{\mathcal C}}&=\{f:f \text{ is given by \eqref{eq:decomp_f_CalC} and }\sum_{m=1}^\infty \beta_m^2/\tau_m^2<\infty\}.
%\end{align*}
%We are interested in embeddings $W^\sigma_{c}\hookrightarrow W^\tau_{{\mathcal C}}$. If $s>0$ and $\sigma_m=m^{-s}$, we simply write $W^s_c$ (or $W^s_{\CalC}$).

We now show that %$\alpha^s:=
$(\alpha_k\cdot k^s)_{k=1}^\infty$ is square summable if $0\le s<1$ and
$a^s:=(a_m\cdot m^s)_{m=1}^\infty$ is square summable. 
We rewrite
\begin{align}
\notag\sum_{k=1}^\infty \alpha_k^2\,k^{2s}&=\sum_{k=1}^\infty k^{2s}\sum_{(\ell,m):k=(2\ell+1)m}a_m\frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot \sum_{(\ell',m'):k=(2\ell'+1)m'}a_{m'}\frac{\mu(2\ell'+1)}{(2\ell'+1)^2}\\
\notag &=\sum_{\substack{k,\ell,m,\ell',m'\\k=(2\ell+1)m\\k=(2\ell'+1)m'}} k^{2s} a_m\frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot a_{m'}\frac{\mu(2\ell'+1)}{(2\ell'+1)^2}\\
\notag &=\sum_{m,m'=1}^\infty a_m a_{m'} m^s (m')^s\sum_{\substack{k,\ell,\ell'\\k=(2\ell+1)m\\k=(2\ell'+1)m'}} \frac{\mu(2\ell+1)}{(2\ell+1)^{2-s}}\cdot \frac{\mu(2\ell'+1)}{(2\ell'+1)^{2-s}}\\
\label{eq:aXa}&=\sum_{m,m'=1}^\infty a_m m^s \cdot a_{m'}(m')^s X_{m,m'}=\langle a^s,X a^s\rangle,
\end{align}
where
\begin{equation}\label{eq:defX}
X_{m,m'}=\sum_{\substack{\ell,\ell'\\(2\ell+1)m=(2\ell'+1)m'}}\frac{\mu(2\ell+1)}{(2\ell+1)^{2-s}}\cdot\frac{\mu(2\ell'+1)}{(2\ell'+1)^{2-s}}.
\end{equation}

We aim to show that $X=(X_{m,m'})_{m,m'=1}^\infty$ is a bounded operator on $\ell_2$, which together with
\eqref{eq:aXa}, finishes the proof.
We shall use the symmetry of $X$ and the following simple observation. If $\sum_{m'}|X_{m,m'}|$ is uniformly bounded over $m$, then $X$ generates
a bounded linear operator on $\ell_1$ and also on $\ell_\infty$ and,
by interpolation, also on $\ell_2$.

We use that, for any $m\ge 1$ fixed,
\begin{align*}
\sum_{m'=1}^\infty |X_{m,m'}|\le \sum_{\ell,\ell'=1}^\infty \frac{|\mu(2\ell+1)|}{(2\ell+1)^{2-s}}\cdot\frac{|\mu(2\ell'+1)|}{(2\ell'+1)^{2-s}}\sum_{m':(2\ell+1)m=(2\ell'+1)m'}1.
\end{align*}
The last sum is (at most) 1 and the sum over $\ell$ and $\ell'$ is convergent.

\emph{Step 2.} The proof of $\F^s([0,1]) \hookrightarrow W^s([0,1])$ for $0\le s<1$
follows the same pattern, only now we assume that $f$ is given by \eqref{eq:decomp_f_CalC}
and invoke the decomposition of $\CalC$ and $\CalS$ into their respective Fourier series, cf. \cite[p. 166]{DD+22}.
As the coefficients of these series decay again quadratically (similarly to \eqref{eq:cos_Riesz} and \eqref{eq:sin_Riesz}),
the rest of the proof follows in the same manner. 


\emph{Step 3.}  We finally show that \eqref{eq:Riesz_1} is a Riesz basis of $W^s$. 
For this, note that the above shows 
$\|f\|_{W^s}\approx\|f\|_{\F^s}$, 
where ``$\approx$'' means upper and lower bounded with constants that are independent of $f$. In particular, 
\[
\left\|\sum_{k\in\N} k^{-s} \Bigl[\alpha_k \CalC_k + \beta_k \CalS_k\Bigr]\right\|^2_{W^s}
\approx 
\left\|\sum_{k\in\N} k^{-s} \Bigl[\alpha_k \CalC_k + \beta_k \CalS_k\Bigr]\right\|^2_{\F^s}=
\sum_{k\in\N} k^{2s} \, \frac{\alpha_k^2+\beta_k^2}{k^{2s}}, 
\]
proving the claim.
\end{proof}

\medskip

\begin{rem} %\label{rem:large-s}
We comment on the restriction to $0\le s<1$ in Theorem \ref{thm:d1_WF}.

% \medskip

If $s\ge 3/2$, then \eqref{eq:cos_Riesz} implies that $\cos(2\pi x)$ does not lie in $\F^s([0,1])$ and, similarly,
one can also show that $\CalC\not\in W^s([0,1])$. Therefore, Theorem \ref{thm:d1_WF} cannot hold if $s\ge 3/2$.

% \medskip

The case $1\le s<3/2$ is more delicate and we conjecture that also in this case Theorem \ref{thm:d1_WF} fails.
Observe, that the proof of Theorem \ref{thm:d1_WF} reduces the study of the embedding
$W^s([0,1])\hookrightarrow \F^s([0,1])$ to the boundedness of the matrix $X=(X_{m,m'})_{m,m'=1}^\infty$
with $X_{m,m'}$ given by \eqref{eq:defX} on $\ell_2.$ To rewrite \eqref{eq:defX} for fixed $m,m'\in\N$,
let $g=\operatorname{gcd}(m,m')$ be the greatest common divisor of $m$ and $m'$. For simplicity, assume for the moment
that $m$ and $m'$ are odd. Then all the integer solutions of the equation $(2\ell+1)m=(2\ell'+1)m'$
are given by $2\ell+1=(2t+1)\cdot \frac{m'}{g}$ and $2\ell'+1=(2t+1)\cdot \frac{m}{g}$, where $t\in\N_0$ is arbitrary.
Therefore, we obtain
\begin{align*}
X_{m,m'}&=\sum_{t=0}^\infty
\frac{\mu((2t+1)\cdot\frac{m'}{g})\mu((2t+1)\cdot\frac{m}{g})}{((2t+1)\cdot \frac{m'}{g})^{2-s}((2t+1)\cdot \frac{m}{g})^{2-s}}\\
&=\frac{\operatorname{gcd}(m,m')^{4-2s}}{m^{2-s}{m'}^{2-s}}
\sum_{t=0}^\infty\frac{\mu((2t+1)\cdot\frac{m'}{g})\mu((2t+1)\cdot\frac{m}{g})}{(2t+1)^{4-2s}}.
\end{align*}
The boundedness of the infinite matrix $Y=(\operatorname{gcd}(m,m')^{4-2s}/[m\cdot m']^{2-s})_{m,m'=1}^\infty$
was investigated in \cite{LK}, \cite{HLS}, and \cite[page 578]{W} and it is known to fail if $3/2>s\ge 1$.
Therefore, we believe that also $X$ is not bounded on $\ell_2$ for this range of $s$.\\
\end{rem}

\begin{rem}
Finally, let us remark that by using similar techniques as above we can also prove the embedding 
\begin{equation*}%\label{embedding_W_F}
W^{ s }([0,1])\hookrightarrow \F^{\gamma}([0,1])\qquad \text{for all }\quad   \gamma<\min\left\{s,\frac{1+s}{2},\frac{3}{2}\right\},  
\end{equation*}
which, in particular, implies 
$W^{ 1 }([0,1])\hookrightarrow \F^{1-\delta}([0,1])$ 
for all $\delta>0$.
We omit the details.  
\end{rem}


