\sum_{m\,\righttriangleplus\, 0} b_m \cos(2\pi m\cdot x)&=
\frac{\sqrt{3}}{\sqrt{2}\, \kappa}\sum_{{m\,\righttriangleplus\, 0}} b_m \sum_{\ell=0}^\infty \frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot {\mathcal C}((2\ell+1)m\cdot x)\\
&=\frac{\sqrt{3}}{\sqrt{2}\, \kappa}\sum_{{k\,\righttriangleplus\, 0}}\alpha_k\CalC(k\cdot x),
\end{align*}
where
\[
\alpha_k=\sum_{(\ell,m):(2\ell+1)m=k}b_m \cdot \frac{\mu(2\ell+1)}{(2\ell+1)^2}.
\]
From this we deduce
\begin{align*}
\sum_{k\,\righttriangleplus\, 0} \alpha_k^2\,\|k\|_2^{2s}&=\sum_{k\,\righttriangleplus\, 0} \|k\|_2^{2s}\sum_{(\ell,m):k=m(2\ell+1)}b_m\frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot \sum_{(\ell',m'):k=m'(2\ell'+1)}b_{m'}\frac{\mu(2\ell'+1)}{(2\ell'+1)^2}\\
&=\sum_{\substack{k,\ell,m,\ell',m'\\k=m(2\ell+1)\\k=m'(2\ell'+1)}} \|k\|_2^{2s} b_m\frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot b_{m'}\frac{\mu(2\ell'+1)}{(2\ell'+1)^2}\\
&=\sum_{m,m'\,\righttriangleplus\, 0} b_m \|m\|_2^s \cdot b_{m'}\|m'\|_2^s X_{m,m'},
\end{align*}
where
\begin{align*}
X_{m,m'}&=\sum_{\substack{\ell,\ell'\\(2\ell+1)m=(2\ell'+1)m'}}
\frac{\|(2\ell+1)m\|_2^s}{\|m\|_2^s}\cdot\frac{\|(2\ell'+1)m'\|_2^s}{\|m'\|_2^s}\cdot\frac{\mu(2\ell+1)}{(2\ell+1)^2}\cdot\frac{\mu(2\ell'+1)}{(2\ell'+1)^2}\\
&=\sum_{\substack{\ell,\ell'\\(2\ell+1)m=(2\ell'+1)m'}}\frac{\mu(2\ell+1)}{(2\ell+1)^{2-s}}\cdot\frac{\mu(2\ell'+1)}{(2\ell'+1)^{2-s}}.
\end{align*}

We finish the proof by showing that $X$ has uniformly bounded row sums and, therefore, is bounded on $\ell_2$.
Indeed,
\begin{align*}
\sum_{m'\,\righttriangleplus\, 0} |X_{m,m'}|\le \sum_{\ell,\ell'=0}^\infty \frac{|\mu(2\ell+1)|}{(2\ell+1)^{2-s}}\cdot\frac{|\mu(2\ell'+1)|}{(2\ell'+1)^{2-s}}\sum_{m':(2\ell+1)m=(2\ell'+1)m'}1,
\end{align*}
which is again convergent for $0\le s<1$, and the norm is uniformly bounded in $d\ge 1.$

\medskip

\emph{Step 2.} The inverse embedding $\F^s([0,1]^d)\hookrightarrow W^s([0,1]^d)$ follows in a very similar way. We assume that
$f$ is given by \eqref{eq:f_Riesz_d}, decompose $\CalC$ and $\CalS$ into their respective Fourier series and reduce the embedding to the boundedness
of a certain infinite matrix on $\ell_2$. As it resembles very much the matrix $X$ used above, the arguments are  very similar. 

\medskip

\emph{Step 3.} 
The proof of \eqref{ineq-Riesz-d} is analogous to Step~3 of the proof of Theorem~\ref{thm:d1_WF}. We leave out the details.
\end{proof}

