\subsection{Barron classes}%\label{sec:Barron}

Barron classes, 
% spaces, 
which were first introduced in \cite{Barron},  turned out to be a very promising function class for the performance analysis  
of artificial neural networks for solving  high-dimensional problems. In particular, if $\mu$ is a probability measure on a $d$-dimensional ball
and $f$ is a function from the 'original' Barron class 
(see \eqref{Barron-orig} below with $s=1$), \cite{Barron} provides a randomized construction of a shallow
%that for functions from a Barron  class 
%(these functions are Lipschitz continuous)
neural network with one hidden layer of $N$ neurons, which achieves an approximation of $f$ with accuracy of the order $N^{-1/2}$
in the $L_2(\mu)$-norm. %, where $\mu$ is a probability measure on a $d$-dimensional ball.
Remarkably, this approximation rate is independent of the dimension $d$ even though the Barron class is so large that every linear approximation method for it suffers
the curse of dimensionality \cite[Theorem~6]{Barron}.  
These results were later extended and generalized in various directions, see  e.g. \cite{CPV23,EW20} and the references given therein.


We start again by introducing the 
(Fourier-analytic version of) Barron classes 
and an alternative based on the 
Riesz basis $\cR_d$ of $L_2$. 
We will see below that, again, 
those spaces coincide with equivalent norms.
Let $s\ge 0$ and define
\[
% {\mathbb B}^s:=
{\mathbb B}^s([0,1]^d):=\left\{f: f\text{ given by \eqref{eq:f_Four}, }
\|f\|_{{\mathbb B}^s}:=|a_0|+\sum_{m\in\Z^d\setminus{\{0\}}}\|m\|_2^s\cdot |a_m|<\infty\right\}, 
\]
and 
\[
% {\mathcal B}^s:=
{\mathcal B}^s([0,1]^d):=\left\{f: f\text{  given by \eqref{eq:f_Riesz_d}, }
\|f\|_{{\mathcal B}^s}:=|\alpha_0|+\sum_{k\,\righttriangleplus\,0}\|k\|_2^s\cdot (|\alpha_k|+|\beta_k|)<\infty\right\}.
\]

Note that in contrast to the Sobolev classes from the previous section, we now invoke the $\ell_1$-norm instead of the $\ell_2$-norm when defining the Barron classes.
For a discussion of other notions of Barron spaces  we refer to  Remark~\ref{rem:different-B} below. 

\medskip
\goodbreak

We now show that the Barron-type spaces above have equivalent norms.

\begin{thm}\label{thm:Barron}
Let $0\le s < 1$. Then ${\mathbb B}^s([0,1]^d) = {\mathcal B}^s([0,1]^d)$ in the sense of equivalent norms.
% Furthermore, t
The constants of equivalence of these norms depend on $s$ but are independent of~$d$. \\
Moreover, it holds that 
\begin{equation}\label{eq:Riesz-Barron}
c\,\sum_{k\righttriangleplus 0}
(|\alpha_k|+|\beta_k|) 
\;\le\; 
\left\|\sum_{k\righttriangleplus 0}\|k\|_2^{-s}\Bigl(\alpha_k\CalC_k+ 
\beta_k \CalS_k\Bigr)\right\|_{\mathbb{B}^s}
\;\le\; C\,\sum_{k\righttriangleplus 0}
(|\alpha_k|+|\beta_k|) 
\end{equation}
where the constants $c,C>0$ can be chosen independently of $d$. \\
(Modifications of \eqref{eq:Riesz-Barron} for functions with constant term are obvious.)
\end{thm}

Some authors call  the 
% (scaled) Riesz basis \eqref{eq:Riesz_d-s}  of $W^s$ 
system \eqref{eq:Riesz_d-s} 
% an $\ell_1$-Riesz 
a $1$-Riesz basis of $\mathbb{B}^s$ 
if it satisfies~\eqref{eq:Riesz-Barron}, 
see e.g.~\cite{CS03}.




\begin{proof} \emph{Step 1.} First, we show that ${\mathbb B}^s([0,1]^d)\hookrightarrow {\mathcal B}^s([0,1]^d)$.

We proceed similarly as in the proof of Theorem \ref{thm:FsWs_d}. Let us provide a  few details. Let $\omega=(\omega_m)_{m\,\righttriangleplus\,0}$
be a sequence given by $\omega_m=\|m\|_2^s$. The norm of the sequence $\alpha=(\alpha_m)_{m\,\righttriangleplus\,0}$
in the weighted space $\ell_1(\omega)$ is then given as usual by
\[
\|\alpha\|_{\ell_1(\omega)}=\sum_{m\,\righttriangleplus\,0} \omega_m\cdot |\alpha_m|.
\]

Repeating the argument of the proof of Theorem \ref{thm:FsWs_d}, we reduce 
the proof of the embedding ${\mathbb B}^s([0,1]^d)\hookrightarrow {\mathcal B}^s([0,1]^d)$
to the estimate of the operator norm of $T:\ell_1(\omega)\to\ell_1(\omega)$,
where, for $k\righttriangleplus 0$, 
\begin{align*}
\alpha_k=(Ta)_k=\sum_{\substack{m\righttriangleplus 0; \ell=0,1,\dots\\(2\ell+1)m=k}}a_m\cdot \frac{\mu(2\ell+1)}{(2\ell+1)^2}.
\end{align*}
Due to convexity, the norm of $T$ is attained on the extreme points of the unit ball of $\ell_1(\omega)$, i.e., 
\[
\|T\|_{\ell_1(\omega)\to \ell_1(\omega)}=\sup_{m\,\righttriangleplus\,0}\frac{\|T e_m\|_{\ell_1(\omega)}}{\|e_m\|_{\ell_1(\omega)}}=
\sup_{m\,\righttriangleplus\,0}\frac{\|T e_m\|_{\ell_1(\omega)}}{\|m\|_2^s}.
\]
If $m\in\Z^d, m\,\righttriangleplus\,0$ is fixed, then
\begin{align*}
   (Te_m)_k&=\sum_{(\ell,n):(2\ell+1)n=k}(e_m)_n\cdot\frac{\mu(2\ell+1)}{(2\ell+1)^2}\\
   &=\sum_{\substack{\ell=0,1,\dots\\(2\ell+1)m=k}}\frac{\mu(2\ell+1)}{(2\ell+1)^2}=
   \begin{cases} 0,&\text{if there is no $\ell\ge 0$ with}\ (2\ell+1)m=k,\\
   \frac{\mu(2\ell+1)}{(2\ell+1)^2},&\text{if} \ (2\ell+1)m=k.
   \end{cases} 
\end{align*}
Hence,
\begin{align}
\notag \|m\|_2^{-s} \|Te_m\|_{\ell_1(\omega)}&=\|m\|_2^{-s}\sum_{\ell=0}^\infty \|(2\ell+1)m\|^s_2\cdot \frac{|\mu(2\ell+1)|}{(2\ell+1)^2}\\
\label{eq:Barron_series} &=\sum_{\ell=0}^\infty \frac{|\mu(2\ell+1)|}{(2\ell+1)^{2-s}},
\end{align}
which is finite for $0\le s<1$ and, of course, independent on $d$.

\emph{Step 2.} The reverse embedding ${\mathcal B}^s([0,1]^d) \hookrightarrow {\mathbb B}^s([0,1]^d)$
can be shown in nearly the same way. 

\emph{Step 3.}  The proof of~\eqref{eq:Riesz-Barron} follows again Step~3 of the proof of Theorem~\ref{thm:d1_WF}.\\
\end{proof}


\begin{rem}
It can be shown that the series \eqref{eq:Barron_series} converges only for $s<1$. Indeed, by \cite[Equation (1.2.7)]{Tit}, it is known that the series
\[
\sum_{n=1}^\infty \frac{|\mu(n)|}{n^\alpha}
\]
converges only for $\alpha>1$. On the other hand,
\begin{align*}
\sum_{n=1}^\infty \frac{|\mu(n)|}{n^\alpha}&=\sum_{n=0}^\infty \frac{|\mu(2n+1)|}{(2n+1)^\alpha}+\sum_{n=0}^\infty \frac{|\mu(4n+2)|}{(4n+2)^\alpha}
+\sum_{n=0}^\infty \frac{|\mu(4n+4)|}{(4n+4)^\alpha}\\
&=\Bigl(1+\frac{1}{2^\alpha}\Bigr)\sum_{n=0}^\infty \frac{|\mu(2n+1)|}{(2n+1)^\alpha},
\end{align*}
where we used that $4(n+1)$ is divisible by 4 implying $\mu(4n+4)=0$, and $\mu(4n+2)=-\mu(2n+1)$ for every $n\ge 0$. Therefore, \eqref{eq:Barron_series} converges only when $2-s>1$
and the restriction to $0\le s<1$ in Theorem \ref{thm:Barron} is necessary. 
\end{rem}

\begin{rem}\label{rem:different-B}
Let us comment on the different notions of Barron spaces in the literature.  
Our Barron spaces ${\mathbb B}^s$ are in the spirit of the ``classical'' Fourier-analytic notion of Barron spaces of periodic functions as introduced in~\cite{Barron}, 
see Example~16 in Section~IX, 
at least for $s=1$. 
However, it seems more common to work with the 
classes of functions on $\R^d$, 
or on certain subsets $\Omega$, 
which are defined by 

% Our Barron spaces resemble the classical Fourier-analytic approach to Barron spaces as used in \cite{Siegel21}, \mario{(M: First ref?)}
\begin{equation}\label{Barron-orig}
% \mathcal{B}_{\mathrm{class}}^s(\Omega) = 
\mathcal{B}_{\mathrm{ext}}^s(\Omega) 
:= \left\{f:\Omega\rightarrow \mathbb{C}: \ 
% \|f\|_{\mathcal{B}_{\mathrm{class}}^s}:=
\inf_{f_e|_{\Omega}=f}\int_{\real^d}(1 +\|\xi\|_2)^s|\hat{f}_e(\xi)|d\xi<\infty\right\}, 
\end{equation}
where the infimum is taken over all extensions $f_e\in L_1(\real^d)$ and $\hat{f}_e$ denotes the Fourier transform of $f_e$.
Barron \cite{Barron} originally introduced  this class for $s=1$, 
and showed that functions from this class can be efficiently approximated by neural networks. 
However, we stress that the  norm 
\eqref{Barron-orig} is dimension-dependent in a non-transparent way: 
It is already a non-trivial research question to determine the norm of a constant function (for bounded~$\Omega$). 
See also~\cite{CPV23,Siegel21} for 
% the extension to~\eqref{Barron-orig}. 
a discussion of issues with general domains.

%\begin{equation}\label{Barron-orig}
%\|f\|_{\mathrm{aux}}:=\int_{\real^d} |\hat{f}(\xi)|\|\xi\|_2d\xi<\infty.
%\end{equation}
Another notion of Barron-type spaces that has been proposed in the literature 
(see e.g.~\cite{EMW22,E1})
% These Barron spaces   essentially consist 
is the space of all “infinitely wide”
neural networks with a certain control over the network parameters. More formally, given an
activation function $\sigma$ (which is often either the ReLU or a Heaviside function), the elements of the associated Barron-type space are all functions that can be written as
\[
f(x)=\int_{\real\times \real^d\times \real}
 a\cdot  \sigma(\langle w, x\rangle + b) \, d\mu (a, w, b),
\]
where $\mu$ is a probability measure satisfying 
\begin{equation}\label{Barron-new}
\|f\|_{B(\sigma)}:=\int_{\real\times \real^d\times \real}
 |a|\cdot  \sigma(\|w\|_2 + |b|) \, d\mu (a, w, b)<\infty. 
\end{equation}
Note that this space/norm is automatically adapted to the activation function $\sigma$. 
It was further generalized in \cite{Per24}, where $\ell_p$ norms and $\mathrm{ReLU}^k$ activation functions were considered in \eqref{Barron-new}. 
Let us point here  that already in \cite{Barron} it was shown that 
the Fourier-analytic Barron space according to \eqref{Barron-orig} is
embedded in the Barron space $B(H)$ associated to the Heaviside function $H$, i.e., 
for bounded domains $\Omega$ it holds that 
% $\|f\|_{B(H)}\leq \|f\|_{\mathcal{B}_{\mathrm{ext}}^1}$, 
$\mathcal{B}_{\mathrm{ext}}^1(\Omega) \hookrightarrow B(H)$. On the other hand, 
when considering  the ReLU activation function $\sigma$, 
we only have 
% $\|f\|_{B(\sigma)}\leq \|f\|_{\mathcal{B}_{\mathrm{ext}}^2}$. 
$\mathcal{B}_{\mathrm{ext}}^2(\Omega) \hookrightarrow B(\sigma)$, 
see~~\cite[Lemma~7.1]{CPV23}.
The latter embedding is best possible  as was shown in~\cite[Prop.~7.4]{CPV23}. 
We also refer to \cite[Section~2]{EMW22}, \cite[Section~3]{E1} or~\cite{KB} 
in this context.
\end{rem}





