\begin{center}\includegraphics[width=15.5cm]{NN-sum-d-dim-3.pdf}
%\vskip-1cm
\caption{ANN representing the sum of   functions $\mathcal{N}_1, \ldots, \mathcal{N}_N$ \\
}
\label{fig:NN-sum}
\end{center}
\end{figure}





This results in the following architecture for 
partial sums of~\eqref{eq:f_Riesz_d}, 
see \cite[Theorem~4.6]{SV}.

\begin{lem} \label{lem:ANN}
Let $d,R\ge1$ and let $I\subset\Z^d\setminus\{0\}$ be nonempty. 
Then, 
\begin{equation}\label{eq:fdecomp}
f(x)\,=\,\alpha_0
% +\sum_{\substack{k\,\righttriangleplus\,0\\ \|k\|_2\le R}} \Bigl[\alpha_k\CalC_k(x)+\beta_k\CalS_k(x)\Bigr],\quad x\in [0,1]^d
+\sum_{k\in I} \Bigl[\alpha_k\CalC_k(x)+\beta_k\CalS_k(x)\Bigr],\quad x\in [0,1]^d, 
\end{equation}
satisfies $f\in\Upsilon_d^{W,L}$ with either 
\begin{equation}\label{constr-1}
W=4\cdot \#I
\qquad\text{and}\qquad 
L\,\le\, 4+\log_2\left(\max_{k\in I} \|k\|_1 \right),
\end{equation}
or
\begin{equation}\label{constr-2}
\qquad
W=d+3 
\qquad\quad\text{and}\qquad 
L \,\le\, 2\,\#I \cdot \log_2\left(16\cdot\max_{k\in I} \|k\|_1 \right). 
\end{equation}
Moreover, all weights in the corresponding ANN are bounded by $8\cdot\max_{k\in I}\{1,|\alpha_k|,|\beta_k|\}$.
\end{lem}


\begin{rem} 
The decomposition \eqref{eq:fdecomp} features $2\,\#I+1$ real parameters, namely $\alpha_0, (\alpha_k)_{k\in I}$ and $(\beta_k)_{k\in I}$.
The ANNs constructed in Lemma \ref{lem:ANN} combine these parameters with pre-cached building blocks (i.e., ANNs, which reproduce the functions $\CalC_k$ and $\CalS_k$ for $k\in I$)
and additional information passing channels.
In this sense, these $2\,\#I+1$ parameters are the only parameters, which we change in the proposed architecture,
the other weights are fixed and do not depend on $f$. This approach was used in \cite[Section VII]{EPGB} under the name \emph{transference principle}
for general decompositions of functions into a given \emph{dictionary}. However, in the next section we take  advantage of the following two facts: 
First, we exploit that the elements of the Riesz basis \eqref{eq:Riesz_d-s} can be easily and exactly recovered by small ANNs. And secondly,
the elements of \eqref{eq:Riesz_d-s} do not rely on any localized decomposition of unity, which would lead to exponential dependence of the constants on
the underlying dimension $d$.\\ 
If we count all nonzero parameters of the architecture, 
then we can employ the fact that the widths and depth of the 
small ANNs are at most 4 and $M:=1+\log_2[\max_{k\in I} \|k\|_1]$, respectively. Hence, there are at most $\mathcal{O}(\#I\cdot\max(d,M))$ non-zero weights in the ANN from the first part of Lemma~\ref{lem:ANN}, 
and $\mathcal{O}(d\cdot \#I\cdot M)$ non-zero weights in the second architecture. 

In contrast, we know from~\eqref{eq:number} that 
the number of parameters in a (general, fully-connected) ANN from $\Upsilon_d^{W,L}$, with $W$ and $L$ chosen as above, 
is of the order $\mathcal{O}((\#I)^2\cdot M+\#I\cdot d)$ 
for the first, and $\mathcal{O}(d^2\cdot \#I\cdot M)$ for the second architecture. 
Note that in the second construction, 
most of the weights are actually equal to 1 due to the additional collation channel.

To ease the presentation, 
we will only employ the first construction \eqref{constr-1} 
for the approximation results below.  
The modifications for the second construction \eqref{constr-2} are straightforward. 
\end{rem}



