\begin{lem}\label{lem:lattice_d} There exist two absolute constants $c_1, c_2>0$
such that for every $d\ge 1$ and $t\ge 0$ the following holds.\\
(i) If $t\ge\sqrt{d}/2$, then 
\[
N(t,d)\le \biggl(\frac{c_1 t}{\sqrt{d}}\biggr)^d.
\]
(ii) If $0<t\le \sqrt{d}/2$, then
\[
N(t,d)\le \biggl(\frac{c_2 d}{t^2}\biggr)^{t^2}.
\]
\end{lem}

\begin{proof}If $t\ge \sqrt{d}/2$, then 
% \\ \begin{minipage}{0.45\textwidth}
\begin{equation}\label{help}
Z(t,d)+[0,1]^d \subset (t+\sqrt{d}) B_2^d,
\end{equation}
see Figure~\ref{fig:split},
and
\begin{align*}
N(t,d)&=\vol(Z(t,d)+[0,1]^d)
\le (t+\sqrt{d})^d\vol(B_2^d)\\
&= (t+\sqrt{d})^d\frac{\pi^{d/2}}{\Gamma(\frac d2+1)}
\le \biggl(\frac{c_1 t}{\sqrt{d}}\biggr)^d.
\end{align*}
Using Stirling's formula 
it can be checked that $c_1:=3\sqrt{2\pi e}$ works. 



If $t\le \sqrt{d}/2$, the proof is more delicate. Recall that, if $0< t<1$, then $N(t,d)=1$
and the result follows. If $1\le t<\sqrt{2}$, then $N(t,d)=2d+1$ and the upper bound again follows. This covers the cases $1\le d\le 7$.

Next, we consider the case when $d\ge 8$ and $\sqrt{d-1}/2\le t\le \sqrt{d}/2$. Then, by (i),
\[
N(t,d)\le N(\sqrt{d}/2,d)\le (c_1/2)^d\le (c_2 d/t^2)^{t^2},
\]
where we used also that $4\le d/t^2\le 4\cdot\frac{d}{d-1}\le 5.$ 

If $d\ge 8$ and $\sqrt{2}\le t\le \sqrt{d-1}/2$, we proceed by induction. 

