%If $d\ge 8$ and $\sqrt{2}\le t\le \sqrt{d-1}/2$, we proceed by induction. 
%We split
%\begin{eqnarray*}
%Z(t,d)
%&=&\{k\in\Z^d:\|k\|_2\le t\}\\
%&=&
%\bigcup_{j=-\lfloor t\rfloor}^{j=\lfloor t\rfloor}\{k\in\Z^d: \|k\|_2\le t, \  k_1=j \}
%\end{eqnarray*}
%\vspace{3cm}
%\end{minipage}\hfill \begin{minipage}{0.5\textwidth}
%\includegraphics[width=8cm]{Gauss_circle_prob_3.pdf}
