%and obtain
\begin{align}
\label{eq:N_est} N(t,d)&=\sum_{j=-\lfloor t\rfloor}^{j=\lfloor t\rfloor} N(\sqrt{t^2-j^2},d-1)
=N(t,d-1)+2\sum_{j=1}^{j=\lfloor t\rfloor}N(\sqrt{t^2-j^2},d-1)\\
\notag&\le N(t,d-1)+2\sum_{j=1}^{j=\lfloor t\rfloor}\biggl(\frac{c_2(d-1)}{t^2-j^2}\biggr)^{t^2-j^2}
\le \biggl(\frac{c_2(d-1)}{t^2}\biggr)^{t^2}+4 \biggl(\frac{c_2(d-1)}{t^2-1}\biggr)^{t^2-1},
\end{align}
where we used inductively (ii) for $d-1$ combined with the fact that $t\le \sqrt{d-1}/2$. Furthermore, to estimate the sum, we used
that every term in this sum is at least twice as large as the next term (for $c_2$ large enough).
Indeed, the ratio of the $(j+1)$-st and the $j$-th term in \eqref{eq:N_est} is equal to
\begin{equation}\label{eq:N_est_2}
\left[\frac{t^2-j^2}{c_2(d-1)}\right]^{2j+1}\left(1+\frac{1}{\lambda_j}\right)^{\lambda_j(2j+1)}, \quad \text{where}\quad
\lambda_j=\frac{t^2-(j+1)^2}{2j+1}.
\end{equation}
Using the elementary inequality $(1+1/z)^z\le e$ valid for $z>0$, we observe that \eqref{eq:N_est_2} is smaller than 1/2
for $c_2>0$ large enough. Therefore, taking the largest term with $j=1$ out of the sum, we can bound the sum by
a geometric series with the sum $\frac{1}{1-\frac 12}$, which in the end gives the 
additional factor $2$ in the  last step in \eqref{eq:N_est}.

Finally, for $c_2\ge 4e$, we apply the mean value theorem to the function $f(u)=u^{t^2}$ and obtain
\begin{align*}
4 \biggl(\frac{c_2(d-1)}{t^2-1}\biggr)^{t^2-1}&=\frac{4}{c_2}\cdot \left(1+\frac{1}{t^2-1}\right)^{t^2-1}\cdot
\left(\frac{c_2}{t^2}\right)^{t^2}\cdot t^2(d-1)^{t^2-1}\\
&\le \frac{4e}{c_2}\cdot \left(\frac{c_2}{t^2}\right)^{t^2}[d^{t^2}-(d-1)^{t^2}]\le
\left(\frac{c_2d}{t^2}\right)^{t^2}-\left(\frac{c_2(d-1)}{t^2}\right)^{t^2}.
\end{align*}
Together with \eqref{eq:N_est} we conclude that
\[
N(t,d)\le \biggl(\frac{c_2d}{t^2}\biggr)^{t^2}.
\]
\end{proof}


The last combinatorial lemma directly leads to our first approximation result using ANNs. Note that the architecture 
and the actual ANN 
mentioned in the theorem is given explicitly, 
by means of partial sums of~\eqref{eq:f_Riesz_d}, see Lemma~\ref{lem:ANN}.


\begin{thm}\label{thm:ANN_Ws}
Let $0<s<1$. Then there is a constant $C_s>0$, depending only on $s$, such that for every $d\in\N$ and $0<\varepsilon<1$ the following statement is true. \\
Let $R:=(C_s/\varepsilon)^{1/s}$ and $N(R,d)$ be as in Lemma~\ref{lem:lattice_d}. 
Then, for every $f\in W^s([0,1]^d)$ there is an ANN $\cN\in\Upsilon_d^{W,L}$  with 
\[
W=4\cdot N(R,d)\quad\text{and}\quad L \le 4+\log_2\left(R\cdot\sqrt{\min(R,d)}\right)
\]
such that 
\[
\|f-\cN\|_2 \,\le\, \eps\cdot\|f\|_{W^s}. 
\]
Moreover, 
$\cN$ can be given explicitly depending on $\alpha_k,\beta_k$ with $\|k\|_2\le R$ in~\eqref{eq:f_Riesz_d}
and the architecture of $\cN$ is independent of $f$.
\end{thm}



\begin{proof}
Let $f\in W^s([0,1]^d)$ with $\|f\|_{W^s([0,1]^d)}\le 1$. By Theorem \ref{thm:FsWs_d}, 
$f\in {\mathcal F}^s([0,1]^d)$ with $\|f\|_{{\mathcal F}^s}\le c$ with $c$ independent of $d$.
Therefore, we can decompose $f$ as in \eqref{eq:f_Riesz_d} with
$\alpha_0^2+\sum_{k\, \righttriangleplus\, 0}\|k\|^{2s}_2(\alpha_k^2+\beta_k^2)\le c^2$.

For $R>0$ we decompose
\[
f=f_R+f^R = \Bigl(\alpha_0 + \sum_{k\,\righttriangleplus\,0: \|k\|_2\le R}\dots\Bigr)+
\Bigl(\sum_{k\,\righttriangleplus\,0: \|k\|_2>R}\dots\Bigr).
\]

We reconstruct $f_R$ exactly as an ANN, the error is given by $f^R$:
\begin{equation*}%\label{reconstr}
\|f-f_R\|^2_2\,=\,\|f^R\|_2^2 
\,\le\, c'\,\sum_{k\,\righttriangleplus\,0: \|k\|_2>R} (\alpha_k^2+\beta_k^2)\cdot \frac{\|k\|_2^{2s}}{R^{2s}}\le C^2 R^{-2s}.
\end{equation*}
To make this smaller than $\varepsilon^2$, we choose $R:=(C/\varepsilon)^{1/s}.$

% On the other hand, we can apply \cite[Theorem 4.6]{SV} to represent $f_R$ as an ANN. Then 
By Lemma~\ref{lem:ANN} with $I:=Z(R,d)$, we see that $f_R\in \Upsilon_d^{W,L}$ with
\[
W=4 N(R,d)\quad\text{and}\quad 
% L=3+\max_{k\in Z(R,d)}\lceil \log_2(\|k\|_1)\rceil \le 3+\lceil \log_2(R\cdot\sqrt{\min(R,d)})\rceil.
L=4+\max_{k\in Z(R,d)}\log_2(\|k\|_1) \le 4+ \log_2\left(R\cdot\sqrt{\min(R,d)}\right).
\]
In the last estimate we used H\"older's inequality together with $\|k\|_2\leq R$ and the simple observation that the number of non-zero indices
of $k\in Z(R,d)$ is bounded from above by $\min(R, d)$. 
\end{proof}

\medskip

\begin{rem}
As the proof above is based on standard estimates from linear approximation, 
the result can easily be generalized to approximation in other norms, like the uniform norm. 
However, this might lead to additional assumptions and $d$-dependent factors. 
\end{rem}

\medskip

We now combine Theorem~\ref{thm:ANN_Ws} with Lemma~\ref{lem:lattice_d} to bound the parameters $W$ and $L$ of
the constructed neural network by quantities involving only $\varepsilon$ and $d$. 
% We use the notation $f=O_s(g)$ for $f\le c_s g$ for a constant $c_s$ that only depends on $s$. 


\begin{cor} \label{cor:ANN_Ws}
Let $0<s<1$, $d\in\N$, and $0<\varepsilon<1$. There are constants $c_3,c_4, c_5$ that depend only on $s$ such that 
\[
\inf_{\cN\in\Upsilon_d^{W,L}}\|f-\cN\|_2 \,\le\, \eps\cdot\|f\|_{W^s} 
\]
for every $f\in W^s([0,1]^d)$ 
if 
\[
\varepsilon\ge c_3\, d^{-s/2}, \quad 
W \ge (c_4 \eps^{2/s} d)^{c_5\, \eps^{-2/s}}, 
\quad\text{and}\quad 
L\ge c_4\,\log_2(1/\varepsilon),
\]
or 
\[
\varepsilon\le c_3\, d^{-s/2}, \quad 
W \ge \left(\frac{c_4}{\eps^{1/s} \sqrt{d}}\right)^{d}, 
\quad\text{and}\quad 
L\ge c_4\,\log_2(1/\varepsilon). 
\]
\end{cor}




\subsection{Barron classes}

When dealing with the Barron classes ${\mathbb B}^s([0,1]^d)$
