% \end{lem}

% First, we derive several results on best $n$-term approximation in sequence spaces, i.e., when $X$ and $Y$ are Banach spaces
% of sequences. In that setting, we always mean by $\Phi:=\{e_n\}$ the set of canonical sequences with $(e_n)_j=1$ if $n=j$ and $(e_n)_j=0$ otherwise.

\medskip

We start with the sequence spaces corresponding to univariate Barron classes. 
% of univariate functions. 

\begin{lem}
Let $s\ge 0$ and let $b_s^1$ be the space of bounded sequences $\alpha=(\alpha_k)_{k=1}^\infty$, for which the norm
\[
\|\alpha\|_{b_s^1}:=\sum_{k=1}^\infty k^{s} |\alpha_k|
\]
is finite. 
%Let $\Phi:=\{e_n:n\in\N\}\subset b_s^1$ be the set of canonical sequences with $(e_n)_j=1$ if $n=j$ and $(e_n)_j=0$ otherwise.
Then, 
% $\sigma_n(b_s^1,\ell_2, \Phi)\le c\, n^{-s-1/2}$ 
$\sigma_n(b_s^1,\ell_2)\le c\, n^{-s-1/2}$ 
for every $n\in\N$  
where $c>0$ only depends on $s$.
\end{lem}
\begin{proof} First, note that $b_s^1\hookrightarrow \ell_1\hookrightarrow \ell_2$ and that 
% $\sigma_n(b_s^1,\ell_2, \Phi)$ 
$\sigma_n(b_s^1,\ell_2)$ 
is well-defined.
We shall use a classical result on rearrangements of sequences, see~\cite[Section 10.2, Theorem 368]{HLP},
which states that for two non-negative sequences $a=(a_j)_{j=1}^\ell$ and $b=(b_j)_{j=1}^\ell$
with non-increasing rearrangements $(a^*_j)_{j=1}^\ell$ and $(b^*_j)_{j=1}^\ell$, we have that 
\[
\sum_{j=1}^\ell a^*_j b^*_{\ell-j+1}
\le \sum_{j=1}^\ell a_j b_j\le \sum_{j=1}^\ell a^*_j b^*_j.
\]
%see~\cite[Section 10.2, Theorem 368]{HLP}.
Actually, using the same proof as in \cite{HLP}, one can show that for every non-negative sequence $a=(a_j)_{j=1}^\infty$ converging to zero
and for every non-negative non-decreasing sequence  $b=(b_j)_{j=1}^\infty$ it holds that
\begin{equation}\label{eq:HLP}
\sum_{j=1}^\infty a_j^* b_j\le \sum_{j=1}^\infty a_jb_j.
\end{equation}

Fix now $\alpha\in b_s^1$ with $\|\alpha\|_{b_s^1}\le 1$. Then we can apply \eqref{eq:HLP} to $a_j=|\alpha_j|$ and $b_j=j^s$ and obtain
\[
|\alpha_\ell|^* \sum_{k=1}^\ell k^{s}\le \sum_{k=1}^\ell k^{s} a_k^* \le \sum_{k=1}^\infty k^{s} a_k^* \le \sum_{k=1}^\infty k^{s} |\alpha_k|\le 1.
\]
This gives
$|\alpha_\ell|^*\le (s+1)\cdot \ell^{-s-1}$.
The best $n$-term approximation of $\alpha$ in $\ell_2$
is given by the $n$ largest coefficients of $\alpha$. Therefore we get
\[
\sigma_n(\alpha)^2=\sum_{k=n+1}^\infty (|\alpha_k|^{\ast})^2 \le (s+1)^2 \sum_{k=n+1}^\infty k^{-2s-2} \le \frac{(s+1)^2}{2s+1} n^{-2s-1}.
\]
\end{proof}
The generalization to sequence spaces corresponding to Barron classes of multivariate functions follows the same pattern, but is more technical.
Let $d\ge 1$ and $s\ge 0$.  Then $b_s^d$ is the space of bounded  sequences $\alpha=(\alpha_k)_{k\,\righttriangleplus\,0}$ for which the norm
\[
\|\alpha\|_{b_s^d}:=\sum_{k\,\righttriangleplus\,0} \|k\|_2^s\cdot |\alpha_k|
\]
is finite.

\begin{lem}\label{lem:sigma_n}
Let $d\ge 2$ and $s\ge 0$. Then, 
there are absolute constants $c_1,c_2>0$, 
and some $C_s>0$ that depends only on $s$, such that 
\begin{equation}\label{eq:sigman}
    \sigma_n(b_s^d,\ell_2)^2
    \,\le\, C_s\,\cdot\begin{cases}
    n^{-1},&\ \text{if}\ 1\le n\le c_2d,\\
    \Bigl(\frac{\log(c_2d)}{\log(n)}\Bigr)^s\cdot n^{-1},&\ \text{if}\ c_2d\le n \le (c_1/2)^d,\\
    d^{-s}\cdot n^{-2s/d-1},&\ \text{if}\ (c_1/2)^d\le n.
    \end{cases}
\end{equation}
% where $C>0$ depends only on $s$. 
\end{lem}

\begin{proof} \emph{Step 1.}\\
Let $\alpha\in b_s^d$ with $\|\alpha\|_{b_s^d}\le 1$.
We define the weight sequence $\omega=(\omega_k)_{k\,\righttriangleplus\,0}$ with $\omega_k=\|k\|_2^{s}$.
We denote by $\alpha^*=(\alpha_\ell^*)_{\ell=1}^\infty$ the one-dimensional non-increasing rearrangement of $(|\alpha_k|)_{k\righttriangleplus 0}$ and by $\omega^{\#}=(\omega^{\#}_\ell)_{\ell=1}^\infty$
the one-dimensional non-decreasing rearrangement of $\omega$.
Again, we have
\[
\alpha_\ell^*\sum_{k=1}^\ell \omega_k^{\#}\le \sum_{k=1}^\ell \alpha^*_k \omega^{\#}_k\le
\sum_{k=1}^\infty \alpha^*_k \omega^{\#}_k\le \sum_{k\,\righttriangleplus\,0}\omega_k |\alpha_k|\le 1,
\]
i.e. $\alpha_\ell^*\le W(\ell,s,d)^{-1}$, where $W(\ell,s,d)=\sum_{k=1}^\ell \omega_k^{\#}$.
The best $n$-term approximation of $\alpha$ in $\ell_2$ is then again given by
\begin{equation}\label{eq:sigma_est}
\sigma_n(\alpha)^2=\sum_{k=n+1}^\infty (\alpha_k^*)^2\le \sum_{k=n+1}^\infty W(k,s,d)^{-2}.
\end{equation}
\emph{Step 2.} Before we prove a lower bound for $W(k,s,d)$, we first establish lower bounds for  the terms of $\omega^{\#}$.
This we do by exploiting Lemma~\ref{lem:lattice_d}. Indeed, if $N(t,d)<n$, then also
\[
\#\{k\in\Z^d: k\,\righttriangleplus\,0\ \text{and}\ \|k\|_2\le t\}\le N(t,d)<n.
\]
Hence, the lattice point with $n$-th smallest value of $\omega$ lies outside of $tB_2^d$ and, therefore,
\[
\omega_n^{\#}> t^{s}.
\]
Combining this observation with Lemma~\ref{lem:lattice_d}, we will prove that
\begin{align}\label{eq:omega_low}
    \omega_n^{\#}\ge \begin{cases}
    1,&\text{if}\ 1\le n\le c_2d,\\
    \displaystyle\left(\frac{\log(n)}{\log(c_2d)}\right)^{s/2},&\text{if}\ c_2d<n\le (c_1/2)^d,\\
    \displaystyle\left(\frac{n^{1/d}\sqrt{d}}{c_1}\right)^s, &\text{if}\ (c_1/2)^d<n
        \end{cases}    
\end{align}
with $c_1,c_2>0$ from Lemma~\ref{lem:lattice_d}, 
with possibly larger $c_2$ to ensure $c_2\ge (c_1/2)^4$.

Indeed, if $1\le n\le c_2d$, then \eqref{eq:omega_low} follows easily. If $n>(c_1/2)^d$, then we choose any $t$ with $\sqrt{d}/2\le t<n^{1/d}\sqrt{d}/c_1$.
Then, by Lemma \ref{lem:lattice_d}, $N(t,d)\le (c_1t/\sqrt{d})^d<n$ and $\omega_n^{\#}> t^s$.
As $t$ was arbitrary within these limits, we get $\omega_n^{\#}\ge  (n^{1/d}\sqrt{d}/c_1)^s$.

Finally, if $c_2d< n\le (c_1/2)^d$, then we put $t^2=\log(n)/\log(c_2d)>1$ and obtain
\[
t^2\le %\frac{d\log(c_1/2)}{\log(c_2d)}\le
\frac{d\log(c_1/2)}{\log(c_2)}\le \frac{d}{4},
\]
where we used that $c_2\ge (c_1/2)^4$. Therefore, Lemma \ref{lem:lattice_d}, gives
\[
\log(N(t,d))\le t^2\log(c_2 d/t^2)<t^2 \log(c_2 d)=\log(n)
\]
and $\omega_n^{\#}> t^s=(\log(n)/\log(c_2d))^{s/2}$, which finishes the proof of \eqref{eq:omega_low}.

\emph{Step 3.}  
Next, we show that
\begin{equation}\label{eq:W_lower}
W(\ell,s,d)\ge \begin{cases}
    \ell,&\text{if}\ 1\le\ell\le c_2d,\\
    (1-s/2)\ell\left(\frac{\log(\ell)}{\log(c_2d)}\right)^{s/2},&\text{if}\ c_2d<\ell\le (c_1/2)^d,\\
    c\,d^{s/2}\cdot\ell^{s/d+1},&\text{if}\ (c_1/2)^d\le \ell,
\end{cases}
\end{equation}
where $c>0$ depends only on $s$.

If $1\le \ell \le c_2d$, this follows immediately from \eqref{eq:omega_low}. If $c_2 d\le \ell\le (c_1/2)^d$,
then we estimate
\begin{align*}
W(\ell,s,d)&=\sum_{k=1}^{c_2d}\omega_k^{\#}+\sum_{k=c_2d+1}^{\ell}\omega_k^{\#}
\ge c_2d +\frac{1}{\log(c_2d)^{s/2}}\sum_{k=c_2d+1}^\ell (\log k)^{s/2}\\
&\ge c_2d +\frac{1}{\log(c_2d)^{s/2}}\int_{c_2d}^\ell (\log t)^{s/2}dt\\
&=c_2d + \frac{\ell\log(\ell)^{s/2}-c_2d\log(c_2d)^{s/2}}{\log(c_2d)^{s/2}}-\frac{s}{2}{\frac{1}{{\log(c_2d)^{s/2}}}}\int_{c_2d}^\ell(\log t)^{s/2-1}dt\\
&\ge \ell\cdot \frac{\log(\ell)^{s/2}}{\log(c_2d)^{s/2}}-\ell\cdot \frac{s}{2}{\frac{\log(\ell)^{s/2}}{{\log(c_2d)^{s/2}}}},
\end{align*}
which gives the second estimate in \eqref{eq:W_lower}.

It remains to prove \eqref{eq:W_lower} for $\ell\ge (c_1/2)^d$. To simplify the presentation, we assume that $c_1\ge 4$ is an even number.
We start with $\ell=(c_1/2)^d$. We set $t^2=\gamma d$ for $\gamma>0$ small enough to ensure that 
\[
N(t,d)\le (c_2d/t^2)^{t^2}=(c_2/\gamma)^{\gamma d}<(c_1/2)^d/2=\ell/2.
\]
This ensures that $\omega^{\#}_{\ell/2}>t^s=(\gamma d)^{s/2}$ and also
\[
W(\ell,s,d)\ge \sum_{k=\ell/2}^{\ell} \omega_k^{\#}\ge \frac{\ell}{2}\omega^{\#}_{\ell/2}\ge \frac{\ell}{2}(\gamma d)^{s/2}
=c\, d^{s/2}\ell^{s/d+1},
\]
where $c$ depends only on $s$ (and the absolute constants $c_1$ and $c_2$).

If $(c_1/2)^d\le \ell \le 4(c_1/2)^d$, the proof of \eqref{eq:W_lower} follows by monotonicity
\[
W(\ell,s,d)\ge W((c_1/2)^d,s,d)\ge c d^{s/2} [4(c_1/2)^d]^{s/d+1}\cdot 4^{-2}\ge c' d^{s/2}\ell^{s/d+1}.
\]

Finally, for $\ell \ge 4(c_1/2)^d$, we use \eqref{eq:omega_low} and estimate
\[
W(\ell,s,d)\ge \sum_{k=(c_1/2)^d+1}^\ell \omega_k^{\#}\ge c_1^{-s} d^{s/2} \sum_{k=(c_1/2)^d+1}^\ell k^{s/d},
\]
which finishes the proof of \eqref{eq:W_lower}.

\emph{Step 4.} As the last step, we prove \eqref{eq:sigman}.

If $n\ge (c_1/2)^d$, we use \eqref{eq:sigma_est} and obtain
\begin{align*}
\sigma_n(\alpha)^2\le \sum_{k=n+1}^\infty W(k,s,d)^{-2}\le \sum_{k=n+1}^\infty c^{-2} d^{-s} k^{-2(s/d+1)}.
\end{align*}

If $c_2d\le n \le (c_1/2)^d$, then we estimate similarly
\begin{align}
\notag \sigma_n(\alpha)^2&=\sum_{k=n+1}^{(c_1/2)^d}W(k,s,d)^{-2}+\sum_{k=(c_1/2)^d+1}^\infty W(k,s,d)^{-2}\\
\label{eq:sigma_middle}&\le c\, \log(c_2d)^s \sum_{k=n+1}^{(c_1/2)^d} k^{-2}\log(k)^{-s}+c\, d^{-s}(c_1/2)^{-2s-d}\\
\notag &\le c\, \Bigl(\frac{\log(c_2d)}{\log(n)}\Bigr)^s\cdot n^{-1}.
\end{align}

And finally, if $1\le n\le c_2d$ we combine \eqref{eq:sigma_est} and \eqref{eq:sigma_middle} to 
\begin{align*}
\sigma_n(\alpha)^2&\le \sum_{k=n+1}^{c_2d} W(k,s,d)^{-2} + c\, (c_2d)^{-1}\le \sum_{k=n+1}^{c_2d} k^{-2} + c\, (c_2d)^{-1}
\end{align*}
and the result follows. \\
\end{proof}

We now show the analogue of our ANN approximation result in Theorem ~\ref{thm:ANN_Ws} for Barron classes.


\begin{thm}\label{thm:ANN_Bs}
Let $0<s<1$. Then there are constants $c,C>0$, depending only on $s$, such that
for every $d\in\N$ and $0<\varepsilon<1$ the following statement is true. \\
Let $R:=(C/\varepsilon)^{1/s}$ and 
$n$ such that $\sigma_n(b_s^d,\ell_2)<c\eps$. 
Then, for every $f\in \mathbb{B}^s([0,1]^d)$
there is an ANN $\cN\in\Upsilon_d^{W,L}$ with 
\[
W=4 n\quad\text{and}\quad L
% \le 3+\lceil \log_2(R\cdot\sqrt{\min(R,d)})\rceil,
\le 4+\log_2\left(R\cdot\sqrt{\min(R,d)}\right)
\]
such that 
\[
\|f-\cN\|_2 \,\le\, \eps\cdot\|f\|_{\mathbb{B}^s}. 
\]
Moreover, 
$\cN$ can be given explicitly 
% based on the knowledge of 
depending on 
the coefficients of the best $n$-term approximation of $f$.
\end{thm}

\begin{proof}
Let $f$ be the unit ball of ${\mathbb B}^s([0,1]^d)$. By Theorem \ref{thm:Barron}, there is a constant $C_s>0$, such that
$\|f\|_{{\mathcal B}^s([0,1]^d)}\le C_s$. We can therefore decompose $f$ as in \eqref{eq:f_Riesz_d} into a series
\[
f=\alpha_0+\sum_{k\righttriangleplus 0}\Bigl[\alpha_k\CalC_k+\beta_k\CalS_k\Bigr]
\]
with
\[
\|\alpha\|_{b^d_s}=\sum_{k\righttriangleplus 0} \|k\|_2^s \cdot|\alpha_k|\le C_s \quad\text{and}\quad
\|\beta\|_{b^d_s}=\sum_{k\righttriangleplus 0} \|k\|_2^s \cdot|\beta_k|\le C_s.
\]
We define 
$R:=(C/\varepsilon)^{1/s}$ as well as
$\alpha^R=(\alpha^R_k)_{k\righttriangleplus 0}$ by $\alpha^R_k=\alpha_k$ if $\|k\|_2\le R$ and $\alpha^R_k=0$ otherwise.
Then
\begin{align} \label{eq:ANN-Bs-calc}
\|\alpha-\alpha^R\|_2&=\biggl(\sum_{k\righttriangleplus 0: \|k\|_2>R}|\alpha_k|^2\biggr)^{1/2}
\le \sum_{k\righttriangleplus 0: \|k\|_2>R}|\alpha_k|\\
\notag&\le R^{-s}\sum_{k\righttriangleplus 0: \|k\|_2>R}\|k\|_2^s\cdot |\alpha_k|\le C_s R^{-s}.
\end{align}
Next, we define $\widehat \alpha^{R,n}$ to be the best $n$-term approximation of $\alpha^R$ in $\ell_2$ (with respect to the
canonical basis of $\ell_2$).
% , which we again denote by $\Phi$. 
Hence,
\[
\|\alpha^R-\widehat \alpha^{R,n}\|_2\le \|\alpha^R\|_{b^d_s}\cdot \sigma_n(b_s^d,\ell_2)\le C_s\cdot \sigma_n(b_s^d,\ell_2).
\]
Furthermore, we define $\beta^R$ and $\widehat \beta^{R,n}$ similarly.

We approximate $f$ by $f^{R,n}$, which is defined as follows
\[
f^{R,n}=\alpha_0+\sum_{k\righttriangleplus 0}\Bigl[\widehat\alpha^{R,n}_k\CalC_k+\widehat\beta^{R,n}_k\CalS_k\Bigr]
\]
Then, 
\begin{align*}
\|f-f^{R,n}\|_2&=\left\|\sum_{k\righttriangleplus 0}\Bigl[(\alpha_k-\widehat\alpha^{R,n}_k)\CalC_k+(\beta_k-\widehat\beta^{R,n}_k)\CalS_k\Bigr]\right\|_2\\
&\le \frac{\sqrt{2}}{2}\cdot \Bigl(\|\alpha-\widehat\alpha^{R,n}\|_2 + \|\beta-\widehat\beta^{R,n}\|_2\Bigr)\qquad \\
&\le \frac{\sqrt{2}}{2}\cdot \Bigl(\|\alpha-\alpha^{R}\|_2+\|\alpha^R-\widehat\alpha^{R,n}\|_2 + \|\beta-\beta^{R}\|_2+\|\beta^R-\widehat\beta^{R,n}\|_2\Bigr)\\
&\le C_s'\cdot [R^{-s}+\sigma_n(b_s^d,\ell_2)]\le\varepsilon, 
\end{align*}
where we use the choice of $n$.


Finally, by 
% \cite[Theorem 4.6]{SV}, 
Lemma~\ref{lem:ANN}, 
$f^{R,n}$ can be reproduced by an artificial neural network $f^{R,n}\in \Upsilon_d^{W,L}$ with
\[
W=4n\quad \text{and} \quad 
% L=\lceil \log_2(Rd^{1/2}) \rceil+3.
%L=4+ \log_2(Rd^{1/2}),
L\le 4+\log_2\left(R\cdot\sqrt{\min(R,d)}\right)
\]
where we again use that $\|k\|_1\le\sqrt{\min(R,d)}\|k\|_2$ for $k\in\Z^d$. \\
\end{proof}


