\end{theorem}

\begin{theorem}
\label{thm:Trib k2unbalanced}
Let $\infw{t}$ be the Tribonacci sequence, fixed point of $0\mapsto 01, 1\mapsto 02, 2 \mapsto 0$.
For each $k\geq 1$, the sequence $\infw{t}$ is totally $(k,1)$-unbalanced.
\end{theorem}

