\newcommand{\ppref}{\operatorname{prefb}}
\newcommand{\pfac}{\operatorname{facb}}
\newcommand{\pmin}{\operatorname{minb}}
\newcommand{\pdiff}{\operatorname{diffb}}
\newcommand{\pborder}{\operatorname{border}}
\newcommand{\pconv}{\operatorname{conv}}

If we show that the $k$-abelian complexity is furthermore $\mathcal{N}_\tau$-regular, it is then $\mathcal{N}_\tau$-automatic. Recall $\pfeq_\infw{x}$ and $\pabeq_\infw{x}$ from~\cref{sec:method 1}.
We now introduce the following relations and functions:
\begin{align*}
    \ppref_{\infw{x},a}(n) &= \Psi\left(B_k(\infw{x})\interv{0}{n}\right)[a],\\
    \pfac_{\infw{x},a}(i,n) &= \ppref_{\infw{x},a}(i+n) - \ppref_{\infw{x},a}(n),\\
    \pmin_{\infw{x},a}(n) &= \min_{i\geq 0} \{ \pfac_{\infw{x},a}(i,n) \}, \\
    \pdiff_{\infw{x},a}(i,n) &=\pfac_{\infw{x},a}(i,n)-\pmin_{\infw{x},a}(n), \\
    \pborder_\infw{x} &= \left\{ (i,j,k,n) \mid \left(k\leq n \Rightarrow \pfeq_\infw{x}(i,j,k-1)\right) \land \left(n<k \Rightarrow \pfeq_\infw{x}(i,j,n)\right)\right\}.
\end{align*}

\begin{theorem}
\label{thm:regular}
    Let $k\ge 1$ be an integer and let $\infw{x}\in A^\NN$ be a sequence such that $B_k(\infw{x})$ is automatic in some regular numeration system $\mathcal{N}_k$.
    If the Parikh vectors of length-$n$ prefixes of $B_k(\infw{x})$ form an $\mathcal{N}_k$-synchronized sequence, then $(\abk{k}{x}(n))_{n\ge 0}$ is $\mathcal{N}_k$-regular.
\end{theorem}

\begin{proof}
Fix $k\ge 1$ and let $A_k=\{1,\ldots,m:=\facc{x}(k)\}$ be the alphabet over which $B_k(\infw{x})$ is defined. By hypothesis, the functions $\ppref_{\infw{x},a}$ are all synchronized. Therefore, the functions $\pfac_{\infw{x},a}$ are all synchronized with the following formula in first-order logic: $\pfac_a(i,n,z)=\exists x,y \; \ppref_{\infw{x},a}(i,x) \land \ppref_{\infw{x},a}(i+n,y) \land z+x=y$. Similarly, the functions $\pmin_{\infw{x},a}$ and $\pdiff_{\infw{x},a}$ are also all synchronized. We now provide a formula for $\pabeq_\infw{x}(i,j,k,n)$. This formula is split in two cases: if $n\leq k$, then the $k$-abelian equivalence is simply the factor equivalence, and otherwise we use the border condition; see \cref{lem:equivalent def for k-ab equiv}: \begin{align*}
\pabeq_\infw{x}(i,j,k,n)&= [n<k \land \pfeq_{\infw{x}}(i,j,n)] \land [ \pborder_\infw{x}(i,j,k,n+k) \\
 & \land \exists z (\pdiff_{\infw{x},1}(i,n,z) \land \pdiff_{\infw{x},1}(j,n,z) ) \land \cdots \\ & \land \exists z (\pdiff_{\infw{x},m}(i,n,z) \land \pdiff_{\infw{x},m}(j,n,z) ].
\end{align*} Therefore, this relation is also synchronized. Finally, we define the following relation that identifies the first occurrences of $k$-abelian equivalent factors: \begin{align*}
    \Lambda_\infw{x}= \left\{ (i,k,n) \mid \forall j \; \pabeq_\infw{x}(i,j,k,n) \implies i\leq j \right\}.
\end{align*} 
By using the path-counting technique \cite[Section 9.8]{Shallit:2023}, $(\abk{k}{x}(n))_{n\ge 0}$ is a regular sequence. 
\end{proof}

\begin{corollary}\label{cor:kab-auto}
Let $k\ge 1$ be an integer and let $\infw{x}$ be a fixed point of a primitive substitution $\tau$.
Let $\mathcal{N}_k$ be the numeration system associated with $\tau_k$.
If $\tau_2$ is ultimately Pisot, then the $k$-abelian complexity $(\abk{k}{x}(n))_{n\ge 0}$ is $\mathcal{N}_\tau$-automatic.
\end{corollary}

\begin{proof}
Note that $B_k(\infw{x})$ is the fixed point of $\tau_k$, so $B_k(\infw{x})$ is $\mathcal{N}_k$-automatic. Since a regular sequence that is bounded is automatic, we deduce that $(\abk{k}{x}(n))_{n\ge 0}$ is $\mathcal{N}_k$-automatic, by combining both \cref{thm:bounded,thm:regular}. Finally, we apply \cref{lem:subset of spectres} and \cref{prop:converter} to deduce that this sequence is also $\mathcal{N}_\tau$-automatic. 
\end{proof}

