\section{Open problems and questions}
\label{sec:open pbs}

\begin{conjecture}
Let $\infw{t}$ be the Tribonacci sequence, fixed point of $0\mapsto 01, 1\mapsto 02, 2 \mapsto 0$.
The $2$-dimensional sequence $(\abk{k}{t}(n))_{k\ge 1, n\ge 0}$ is not synchronized but computed by a sequence automaton of polynomial $(X-1)(X^3-X^2-X-1)$.
\end{conjecture}

\begin{question}
 We checked the computed complexities for the Fibonacci sequence and the $3$-abelian complexity of the Tribonacci sequence.
 In general, can we obtain some inductive procedure to check/certify/validate our result?
\end{question}

%For an integer $m\ge 2$, the \emph{$m$-bonacci sequence} $\infw{x}_m$ is the fixed point, starting with $0$, of the substitution $0\mapsto 01, 1 \mapsto 02, \ldots, m-2 \mapsto 0(m-1), m-1 \mapsto 0$.
%These sequences generalize the Fibonacci and Tribonacci sequences for which $m=2$ and $m=3$ respectively.
Given in~\cref{thm:Fib k2balanced,thm:Trib k2balanced} on the Fibonacci and Tribonacci sequences, we raise the following question. 

\begin{question}
For an integer $m\ge 2$, let $\infw{x}_m$ be the $m$-bonacci sequence, fixed point of $0\mapsto 01, 1 \mapsto 02, \ldots, m-2 \mapsto 0(m-1), m-1 \mapsto 0$.
    What is the value of the smallest integer $C^{(m)}_k\ge 1$ such that $\infw{x}_m$ is $(k,C^{(m)}_k)$-balanced? Bounds on $C^{(m)}_1$ are given in~\cite{Brinda:2014}.
\end{question}

