\section{Validation script for \cref{subsec:check validity}}

Here is the details of the \texttt{Walnut} script used to check the DFAO and ensure it computes $\pbal_\infw{t}$, where $\infw{t}$ is the Tribonacci sequence, fixed point of $0\mapsto 01, 1\mapsto 02, 2 \mapsto 0$.

\begin{lstlisting}
eval init "?msd_tri Ai,j1,j2,k Dequitri[i][j1][j2][k][0]=@-1
| Dequitri[i][j1][j2][k][0]=@0
| Dequitri[i][j1][j2][k][0]=@1":
\end{lstlisting}

\begin{lstlisting}
eval initXX "?msd_tri Ai,j1,j2,k 
        ($feq_tri(i,j1,k) <=> $feq_tri(i,j2,k)) 
    <=> Dequitri[i][j1][j2][k][0]=@0":
eval initTF "?msd_tri Ai,j1,j2,k 
        ($feq_tri(i,j1,k) & ~$feq_tri(i,j2,k)) 
    <=> Dequitri[i][j1][j2][k][0]=@1":
eval initFT "?msd_tri Ai,j1,j2,k 
        (~$feq_tri(i,j1,k) & $feq_tri(i,j2,k)) 
    <=> Dequitri[i][j1][j2][k][0]=@-1":
\end{lstlisting}

\begin{lstlisting}
def increase "?msd_tri 
  (Dequitri[i][j1][j2][k][n]=@-2 & Dequitri[i][j1][j2][k][n+1]=@-1) 
| (Dequitri[i][j1][j2][k][n]=@-1 & Dequitri[i][j1][j2][k][n+1]=@0) 
| (Dequitri[i][j1][j2][k][n]=@0 & Dequitri[i][j1][j2][k][n+1]=@1)
| (Dequitri[i][j1][j2][k][n]=@1 & Dequitri[i][j1][j2][k][n+1]=@2)":
def decrease "?msd_tri 
  (Dequitri[i][j1][j2][k][n]=@-1 & Dequitri[i][j1][j2][k][n+1]=@-2)
| (Dequitri[i][j1][j2][k][n]=@0 & Dequitri[i][j1][j2][k][n+1]=@-1)
| (Dequitri[i][j1][j2][k][n]=@1 & Dequitri[i][j1][j2][k][n+1]=@0) 
| (Dequitri[i][j1][j2][k][n]=@2 & Dequitri[i][j1][j2][k][n+1]=@1)":
def constant "?msd_tri 
  (Dequitri[i][j1][j2][k][n]=@-2 & Dequitri[i][j1][j2][k][n+1]=@-2)
| (Dequitri[i][j1][j2][k][n]=@-1 & Dequitri[i][j1][j2][k][n+1]=@-1)
| (Dequitri[i][j1][j2][k][n]=@0 & Dequitri[i][j1][j2][k][n+1]=@0)
| (Dequitri[i][j1][j2][k][n]=@1 & Dequitri[i][j1][j2][k][n+1]=@1) 
| (Dequitri[i][j1][j2][k][n]=@2 & Dequitri[i][j1][j2][k][n+1]=@2)":
