    y_1 + y_2 + y_3 + x_1 + x_2 + x_3 \leq 5, \\
    y_2^2 + x_1^2 + x_2^2 + x_3^2 \leq 5.5, \\
    y_1 + x_1 \leq 1.2, \,
    y_2 + x_2 \leq 1.8, \\
    y_3 + x_3 \leq 2.5, \,
    y_4 + x_1 \leq 1.2, \\
    y_2^2 + x_2^2 \leq 1.64, \,
    y_3^2 + x_3^2 \leq 4.25, \,
    y_2^2 + x_3^2 \leq 4.64, \\
    (x_1 \, x_2 \,x_3)^{\top} \in \lcrc{0}{1.2} \times \lcrc{0}{1.8}  \times \lcrc{0}{2.5},\\ 
    y_i \in \{0,1\} \text{ for each } i = 1, 2, 3, 4.
