\section{An exposition to Walker slice sampling techniques}\label{subsec:ws}
% The Walker-Slice sampler \cite{ref:SGW-14} is one of the primary technical engines driving our algorithm. It is a preferred alternative to the Metropolis-Hastings algorithm for sampling from a distribution on a countable state-space \(\stsp \subset \Zbb\) since there is no rejection step in it.
% , which we pick to be \(\stsp \subset \Zbb\) here.
% , and is represented by a set of unnormalized probabilities \( (\pi(j))_{j \in \Nz} \). The sampling of such probabilities cannot be done directly and exactly due to the unknown normalizing constant.
Let \( \pi(\cdot) \) be the stationary distribution of the Markov chain defined on \(\ol{\stsp}\) with the transition density \( p_A\cprobof[]{\cdot \given \cdot} \). Pick the \emph{annealing temperature} \(\temp>0\). We choose \(\pi\) to be the unnormalized Boltzmann distribution given by the following expression: 
%
\begin{equation}
    \label{eq:pi}
    \pi(r) = \exp{\bigl( -\obj(r) / \temp \bigr)} \quad \text{for }r \in \ol{\stsp}.
\end{equation}
%
Fix the \emph{exploration parameter} \( k \in \N \). For states \(r,s \in \ol{\stsp}\) such that \( |r - s| \leq k - 1 \), the transition probability mass function of the Walker slice sampler is given by
%
\begin{equation}\label{eq:transition probability}
    p_A\cprobof[]{r\given s} = \frac{\pi(r)}{k} \sum_{\ell=\max\{s, r\}}^{\min\{s+k-1, r+k-1\}} \frac{1}{\sum_{j=\max\{1, \ell-k+1\}}^{l} \pi(j)}.
\end{equation}
%
For a fixed choice of the exploration parameter \( k \), the total number of neighboring states that can be explored is  \( 2k - 1 \). The following result is crucial: 
\begin{proposition}[\cite{ref:SGW-14}]
    \label{prop:WS sampler}
    Consider the Walker slice sampler with the transition probability mass function \(p_A \cprobof[]{\cdot \given \cdot }\) defined in \eqref{eq:transition probability}. Denote the normalized version of \( \pi \) by 
    \begin{equation}\label{eq:unnorm pi}
        \widetilde{\pi}(r) = \frac{1}{Z}\pi(r) \quad \text{for }r \in \ol{\stsp},
    \end{equation} 
    %
    where \(Z>0\) is the normalization parameter. If \(r_0 = \max\{1, s-k+1\}\), then \(\sum_{r=r_0}^{s+k-1} p_A\cprobof[]{r\given s} = 1\). Moreover,  
    \begin{align*}
        p_A\cprobof[]{r\given s} \xrightarrow[k \to +\infty]{} \widetilde{\pi}(r) \quad \text{for all \(r,s, \in \ol{\stsp}\)}.
    \end{align*}
    % \begin{align*}
    %     &,\\
    %     &p_A(r|s) \xrightarrow[k \to +\infty]{} \tilde{\pi}(r),
    % \end{align*}
\end{proposition}
%
Proposition \ref{prop:WS sampler} asserts that the transition probability converges to the stationary distribution \(\widetilde{\pi}\); consequently, one can replace the Metropolis-Hasting sampling scheme in the simulated annealing algorithm with the Walker slice sampler. It is straightforward to see that the transition density \( p_A \cprobof[]{\cdot \given \cdot}\) defined in \eqref{eq:transition probability} also satisfies the detailed balance condition
%
\begin{equation*}
    p_A \cprobof[]{r \given s} \pi(s) = p_A \cprobof[]{s \given r} \pi(r) \quad \text{for every }r,s \in \ol{\stsp}. 
\end{equation*}
Readers are referred to \cite{ref:SGW-14} for more details on this sampling scheme.
