\end{enumerate}
%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
\begin{algorithm}[ht]
\footnotesize
\SetAlgoLined
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\SetKwInOut{ini}{Initialize}
\Input{\(\text{\texttt{r}}\),  \(\text{\texttt{s}}\), \(k\), \(\text{\texttt{currdim}}\), \(\text{\texttt{neigh}}\), \(\text{\texttt{currentState}}\), \(\text{\texttt{lb}}\), \(\text{\texttt{ub}}\), \(\text{\texttt{objectiveFunc}}\), \(\text{\texttt{optimValues}}\), \(\text{\texttt{pi\_table}}\)}
\ini{\(\text{\texttt{l\_min}} \gets \max(\text{\texttt{s}}, \text{\texttt{r}})\), \(\text{\texttt{l\_max}} \gets \min(\text{\texttt{s}} + k - 1, \text{\texttt{r}} + k - 1)\)}
\Output{Probability \(\text{\texttt{pA}}\) and updated table \(\text{\texttt{pi\_table}}\)}

\SetKwFunction{Fpi}{pi}
\SetKwProg{Fn}{Function}{:}{end}
\Fn{\Fpi{r}}{
    \If{\(\text{\texttt{pi\_table(r)}} == -1\)}{
        \(\text{\texttt{proObj}} \gets \text{\texttt{currentState}}\)\hspace{2mm}\tcp{\(\text{\texttt{currentState}}\) denotes \(s(t)\)}
        \(\text{\texttt{proObj(currdim,1)}} \gets \text{\texttt{neigh(r,1)}}\) \hspace{2mm} \tcp{\text{\texttt{currdim}} is the index of the dimension. Vector containing all the \(2k-1\) neighbors of \(s\) is represented by  \(\text{\ttt{neigh}}\)}
        \If{\(\text{\texttt{proObj(currdim,1)}} < \text{\texttt{lb(currdim,1)}} \,||\, \text{\texttt{proObj(currdim,1)}} > \text{\texttt{ub(currdim,1)}}\)}{
            \(\text{\texttt{pie}} \gets 0\)\;
        } \hspace{2mm} \tcp{\(\text{\texttt{lb}}\) and \(\text{\texttt{ub}}\) denote the lower bound and upper bound, respectively, of the feasible region of \eqref{eq:global opt prob}}
        \Else{
            % \(\text{\texttt{prop}} \gets \text{\texttt{objectiveFunc(proObj)}}\)\;
            \(\text{\texttt{pie}} \gets \exp{\biggl( \frac{-\text{\texttt{objectiveFunc(proObj)}}}{\text{\texttt{optimValues.temperature(currdim,1)}}}\biggr)}\)\;
        }
        \(\text{\texttt{pi\_table(r)}}\) $\gets$ \(\text{\texttt{pie}}\)\;
        }

    \Else{
        \(\text{\texttt{pie}}\) $\gets$ \(\text{\texttt{pi\_table(r)}}\)\;
    }
}
% \BlankLine
\(\texttt{sum\_l} \gets 0\) \;

\For{\(l = \texttt{l\_min} : \texttt{l\_max}\)}{
    \texttt{sum\_j} $\gets$ 0\;

    \For{\(j = \max(1, l - k + 1) : \texttt{l}\)}{
        \texttt{sum\_j} += \Fpi{j}\;
    }
    \texttt{sum\_l} += $\frac{1}{\texttt{sum\_j}}$\;
}

% \BlankLine
Return \(\text{\texttt{pA}} \gets \frac{\Fpi{\texttt{r}} \cdot \texttt{sum\_l}}{k} \)\;
\caption{\textsf{ProbCal}: Routine to compute \(p_A \cprobof[]{\text{\ttt{r}} \, \mid \, \text{\ttt{s}}}\)}
\label{alg:probcal}
\end{algorithm}
