\section{Proofs}
\subsection{Lemma \ref{lemma:battery}}
\begin{proof}
    For all $t \in \mathcal{T}$, if $\mathcal{B}^{t-1}(\underline{y}, \overline{y}) \subseteq \mathcal{F}^{t-1}_{ i}$ and 
    \begin{equation}\label{eq:lmma_inc}
        \underline{y}(t) \leq \sum_{s=1}^t u(s) \leq \overline{y}(t) \quad \forall \; u \in \mathcal{F}^{t}_{ i},
    \end{equation}
    then $\mathcal{B}^{t}(\underline{y}, \overline{y}) \subseteq \mathcal{F}^{t}_{ i}$, ensuring  $\mathcal{B}^{t}(\underline{y}, \overline{y})$ is an inner approximation. Furthermore, if $\underline{y}_b(t) \leq \underline{y}_a(t)$ and $\overline{y}_a(t) \leq \overline{y}_b(t)  \;\;\forall t \in \mathcal{T}$  then $\mathcal{B}(\underline{y}_a, \overline{y}_a) \subseteq \mathcal{B}(\underline{y}_b, \overline{y}_b)$. Therefore finding the maximum for $\overline{y}(t)$ and minimum for $\underline{y}(t)$, provides us with the maximal inner approximation. 
\end{proof}
\subsection{Lemma \ref{lemma:reformulation}}
\begin{proof}
    When maximizing $u \in \mathcal{F}_{ i}$ either one of the following two constraints will be active at the optimum:
    \begin{align*}
         \sum_{s=1}^t a^{t-s}u(s) &\leq \overline{x}_i(t) \\
         u(t) &\leq \overline{u}_i  \quad \forall \; t\in \mathcal{T}.
    \end{align*}
    Combing these two, we define a plane,  $\mathcal{H}$, where either of these constraints is tight:
    \begin{equation*}
        \overline{\mathcal{H}}:= \left\{ u\in \mathbb{R}^t \; \mid \sum_{s=1}^t a^{t-s}u(s) = \overline{z}_i(t)\right\},
    \end{equation*}
    where $\overline{z}_i(t) = \textrm{min} \left\{\overline{x}_i(t), \sum_{s=1}^t a^{t-s}\overline{u}_i \right\}$. 
    Now consider the problem:
    \begin{align*}
    u^* = \underset{u}{\textrm{argmin}} \quad & \sum_{s=1}^t u(s) \\
    \text{s.t.} \quad  & u\in \overline{\mathcal{H}}\\
    & u \in \mathcal{F}_{ i}. \\
\end{align*}
    By construction we have $\sum_{s=1}^t u^*(s) \leq  \sum_{s=1}^t u(s) \quad \forall u \in \mathcal{F}_{ i}$. Setting $\overline{y}^*(t) =  \sum_{s=1}^t u(s)$ we get the desired result for the upper bound on $\overline{y}(t)$.

    Similarly when to obtain the lower bound  $\underline{y}(t)$ we minimize  $u \in \mathcal{F}_{ i}$, where the active constraints are:
        \begin{align*}
         \overline{x}_i(t)  \leq \sum_{s=1}^t a^{t-s}u(s) \\
          \underline{u}_i \leq u(s) \quad \forall \; t\in \mathcal{T}.
    \end{align*}
    The plane defining the active constraints is then
        \begin{equation*}
        \underline{\mathcal{H}}:= \left\{ u\in \mathbb{R}^t \; \mid \sum_{s=1}^t a^{t-s}u(s) = \underline{z}_i(t)\right\},
    \end{equation*}
    where $\underline{z}_i(t) = \textrm{max} \left\{\underline{x}_i(t), \sum_{s=1}^t a^{t-s}\underline{u}_i \right\}$. As before for the optimal solution of the problem
    \begin{align*}
    u^* = \underset{u}{\textrm{argmax}} \quad & \sum_{s=1}^t u(s) \\
    \text{s.t.} \quad  & u\in \underline{\mathcal{H}}\\
    & u \in \mathcal{F}_{ i}. \\
\end{align*}
    we have $ \sum_{s=1}^t u(s) \leq \sum_{s=1}^t u^*(s)  \quad \forall u \in \mathcal{F}_{ i}$. Setting $\underline{y}(t) =  \sum_{s=1}^t u^*(s)$ we conclude our proof.
\end{proof}


